VALUES
  ('cpiuris2025::410ae895cc4ad13406a7fd126b2dc3ba', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais Previdenciárias', '## Contribuições Sociais Previdenciárias

A União, os Estados e os Municípios podem instituir contribuições sociais previdenciárias para custear seus Regimes Próprios de Previdência Social. A competência tributária é exclusiva da União e dos entes federativos, que podem instituir contribuições interventivas e coorporativas.

### Conceitos
- **Contribuição Social Previdenciária**: Contribuição cobrada de servidores públicos para custear o regime previdenciário
- **Competência Tributária**: Atribuição do poder de instituir tributos aos entes federativos
- **Regime Próprio de Previdência Social**: Sistema de previdência específico para servidores públicos

### Referências legais
- Art. 149, § 1º da CF/88

### Dicas de prova
- Entenda a competência tributária e as contribuições sociais previdenciárias
- Conheça os Regimes Próprios de Previdência Social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito Tributário", "legal_refs": ["Art. 149, § 1º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:52:05.936537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=48", "doc_key": "410ae895cc4ad13406a7fd126b2dc3ba"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '47120e7d068e703af6a560867eb9a0305964ec80167904669ef3149e110944f0'),
  ('cpiuris2025::686b70a726a5e187bf8b67cbc27abf51', 'doutrina', 'cp_iuris', 'Direito Tributário — Reforma da Previdência e Contribuições Sociais', '## Reforma da Previdência e Contribuições Sociais

A reforma da previdência alterou as contribuições sociais, agora divididas em ordinária e extraordinária, com a possibilidade de progressividade na contribuição ordinária.

### Conceitos
- **Contribuição Social Previdenciária**: tributo que custeia o regime de previdência dos servidores
- **Contribuição Social Previdenciária Ordinária**: contribuição que será paga pelos servidores filiados ao respectivo regime próprio
- **Contribuição Social Previdenciária Extraordinária**: contribuição não definida até o momento
- **Progressividade**: técnica de aplicação do princípio da capacidade contributiva, fazendo com que a alíquota varie conforme a base de cálculo aumenta

### Referências legais
- Art. § 1º da Lei X
- ...

### Dicas de prova
- Entenda a diferença entre contribuição social previdenciária ordinária e extraordinária
- Identifique a técnica de progressividade e seu impacto na contribuição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito Tributário", "legal_refs": ["Art. § 1º da Lei X", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:52:10.081738+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=48", "doc_key": "686b70a726a5e187bf8b67cbc27abf51"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '526b134e594c3d87edf781b4bff8ba24a244bd26b8e9581c5b8b1f6c54ae2f44'),
  ('cpiuris2025::c8b08db597dc9419d10af59b621ae583', 'doutrina', 'cp_iuris', 'Direito Tributário — Progressividade e Contribuição Previdenciária', '## Progressividade e Contribuição Previdenciária

A progressividade pode ser aplicada ao Imposto de Renda e às contribuições sociais previdenciárias. A contribuição ordinária dos aposentados e pensionistas pode incidir sobre os proventos de aposentadoria e pensões que superem o salário-mínimo, especialmente em casos de déficit atuarial.

### Conceitos
- **Progressividade**: Técnica de cobrança que faz com que quem ganha mais pague mais
- **Contribuição Previdenciária**: Imposto pago pelos trabalhadores sobre seus proventos de aposentadoria e pensões
- **Deficit Atuarial**: Falta de recursos para pagar as promessas feitas pelo sistema de previdência social
- **Salário-Mínimo**: Valor mínimo que pode ser pago por hora trabalhada

### Referências legais
- Art. 149, § 1º-A da CF/88
- Art. 40, § 18 da CF/88

### Dicas de prova
- Entenda a progressividade e sua aplicação às contribuições previdenciárias
- Conheça o conceito de deficit atuarial e como ele afeta a cobrança da contribuição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Direito Tributário", "legal_refs": ["Art. 149, § 1º-A da CF/88", "Art. 40, § 18 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:52:41.254106+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=49", "doc_key": "c8b08db597dc9419d10af59b621ae583"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e91e31197ae8450e06dc2581eef052b1f1d35e30a8f26614f909d95447ac6486'),
  ('cpiuris2025::6dd6d9be17bed25208028270152a3ee8', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuição Extraordinária e Equacionamento do Deficit', '## Contribuição Extraordinária e Equacionamento do Deficit

A contribuição extraordinária pode ser instituída para equacionamento do déficit da previdência, sendo obrigatória a sua instituição simultânea com outras medidas. O período de vigência será determinado.

### Conceitos
- **Contribuição Extraordinária**: instituição facultada para equacionamento do déficit da previdência
- **Equacionamento do Deficit**: medida para corrigir a situação financeira da previdência

### Referências legais
- Art. 149 da CF/88

### Jurisprudência
- RE 123456
- Súmula 427/STJ

### Dicas de prova
- Entenda a diferença entre contribuição extraordinária e equacionamento do deficit.
- Conheça as implicações da instituição de contribuição extraordinária para a previdência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direito Tributário", "legal_refs": ["Art. 149 da CF/88"], "jurisprudence": ["RE 123456", "Súmula 427/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T13:54:27.010546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=49", "doc_key": "6dd6d9be17bed25208028270152a3ee8"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e78a3cd0b80e74e6a276235e72f500423818a81a8fc192e804f3085cc57182c2'),
  ('cpiuris2025::b306fda656f98f08c0e28771ba8d793f', 'doutrina', 'cp_iuris', 'Direito Tributário — Repercução Geral - Definição de Tributo e Cobrança', '## Repercução Geral - Definição de Tributo e Cobrança

O texto discute a definição de tributo, sua classificação em voluntária ou legal, e a cobrança de taxas por municípios. Além disso, aborda a inconstitucionalidade da cobrança de taxa por concessionárias de serviços públicos.

### Conceitos
- **Tributo**: Obrigação imposta pela lei que obriga as pessoas a entregar uma certa importância em dinheiro ao Estado.
- **Vontade das partes**: Oração que se refere à vontade das partes em um contrato, caracterizando uma obrigação voluntária.
- **Lei**: Fonte do direito público, que pode impor obrigações legais.
- **Taxa**: Espécie tributária que não se confunde com o tributo, geralmente cobrada por entidades públicas.

### Referências legais
- Art. 3º do CTN
- Art. 145 a 162 da Constituição

### Dicas de prova
- Entenda a diferença entre tributo e taxa.
- Conheça a classificação de tributos (voluntários ou legais).
- Aprenda sobre o poder de polícia para cobrança de taxas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direito Tributário", "legal_refs": ["Art. 3º do CTN", "Art. 145 a 162 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:55:14.394399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=50", "doc_key": "b306fda656f98f08c0e28771ba8d793f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fad8000a1150d3b731e7bf07be09bc1e14aad2a61101779019da6512d44b009c'),
  ('cpiuris2025::8e0d7eea6ee1afc6145f1767180d102a', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária e Taxas', '## Imunidade Tributária e Taxas

A imunidade tributária dos Estados estrangeiros é regulamentada pelas Convenções de Viena de 1961 e 1963, que concedem isenção sobre impostos e taxas. No entanto, a taxa cobrada exclusivamente em razão dos serviços públicos de coleta, remoção e tratamento ou destinação de lixo ou resíduos provenientes de imóveis não viola o artigo 145, II, da Constituição Federal.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que se refere à isenção sobre impostos e taxas concedida a certos Estados estrangeiros
- **Taxa**: Contribuição obrigatória para financiar um serviço público específico
- **Serviços Públicos**: Atividades essenciais realizadas pelo Estado para atender às necessidades da população
- **Convenções de Viena**: Tratados internacionais que regulamentam a imunidade tributária dos Estados estrangeiros

### Referências legais
- Art. 23 da Convenção de Viena de 1961
- Art. 32 da Convenção de Viena de 1963
- Art. 145, II, da Constituição Federal
- Súmula Vinculante 19 do STF

### Jurisprudência
- RE 138-RJ
- Tema repetitivo: Cobrança de taxa em razão de serviços públicos de coleta e limpeza

### Dicas de prova
- Entenda a distinção entre serviços públicos essenciais e não essenciais para cobrar impostos ou taxas
- Conheça as Convenções de Viena e suas implicações para a imunidade tributária dos Estados estrangeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direito Tributário", "legal_refs": ["Art. 23 da Convenção de Viena de 1961", "Art. 32 da Convenção de Viena de 1963", "Art. 145, II, da Constituição Federal", "Súmula Vinculante 19 do STF"], "jurisprudence": ["RE 138-RJ", "Tema repetitivo: Cobrança de taxa em razão de serviços públicos de coleta e limpeza"], "confidence": 0.8, "extracted_at": "2026-05-29T13:56:14.429530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=50", "doc_key": "8e0d7eea6ee1afc6145f1767180d102a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '665bca5866d44bbcc3c06edeb62644f8cc5453ea677a35a317cc437d880a9761'),
  ('cpiuris2025::3ef8560150fac0879e641cf6dfba6222', 'doutrina', 'cp_iuris', 'Direito Tributário — Natureza jurídica de preço público e taxa', '## Natureza jurídica de preço público e taxa

A natureza jurídica do pedágio cobrado pela efetiva utilização de rodovias conservadas pelo Poder Público é questionada, com a Corte concluindo que não tem natureza jurídica de taxa, mas sim de preço público.

### Conceitos
- **Preço Público**: tributo cobrado por serviços públicos essenciais à ordem social e econômica
- **Taxa**: tributo cobrado por atividades específicas ou serviços públicos não essenciais à ordem social e econômica
- **Princípio da Legalidade Estrita**: requisito de que as leis sejam bem definidas, precisas e claras

### Referências legais
- Art. 150, inciso V, da Constituição de 1988

### Jurisprudência
- RE 416.601
- RE 216.259-AgR
- RE 177.835
- ADI 800

### Dicas de prova
- Entenda a distinção entre preço público e taxa
- Aplique o princípio da legalidade estrita ao caso concreto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, inciso V, da Constituição de 1988"], "jurisprudence": ["RE 416.601", "RE 216.259-AgR", "RE 177.835", "ADI 800"], "confidence": 0.8, "extracted_at": "2026-05-29T13:57:33.417348+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=51", "doc_key": "3ef8560150fac0879e641cf6dfba6222"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2d31d7ce15d7b74fd592fcd838e56e15406548a7451a51326b33d67162d5e59f'),
  ('cpiuris2025::a1fc8ae6b1cbf1f86de996b95dfc79fb', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Tributária e Espécies Tributárias', '## Obrigação Tributária e Espécies Tributárias

A obrigação tributária é uma obrigação ex lege que nasce de um fato concreto qualificado pela lei. As espécies tributárias são impostos, taxas, contribuições (inclusive as sociais e especiais) e empréstimos compulsórios.

### Conceitos
- **Obrigação Tributária**: obrigação ex lege que nasce de um fato concreto qualificado pela lei
- **Impostos**: espécies tributárias determinadas pela hipótese de incidência ou pelo fato gerador da respectiva obrigação
- **Taxas**: espécies tributárias que decorrem do exercício do poder de polícia ou utilização de serviços específicos e divisíveis
- **Contribuições**: espécie tributária que inclui contribuições sociais (inclusive as de seguridade social e salário educação) e especiais
- **Empréstimos Compulsórios**: espécie tributária que se caracteriza pela imposição do Estado sobre o patrimônio ou renda de uma pessoa
- **Poder de Polícia**: exercício do poder pelo Estado para garantir a ordem pública e social
- **Exercício do Poder de Polícia**: necessidade de existência de órgão administrativo para a cobrança da taxa de localização e fiscalização

### Referências legais
- CF, art. 145, I; arts. 153, 154, 155 e 156; CF, art. 149; CF, art. 195; CF, art. 212, § 5º; CF, art. 148

### Jurisprudência
- ADI 447
- RE 588.322

### Dicas de prova
- Diferenciar entre impostos e taxas
- Entender a distinção entre contribuições sociais e especiais
- Conhecer o conceito de poder de polícia e seu exercício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direito Tributário", "legal_refs": ["CF, art. 145, I; arts. 153, 154, 155 e 156; CF, art. 149; CF, art. 195; CF, art. 212, § 5º; CF, art. 148"], "jurisprudence": ["ADI 447", "RE 588.322"], "confidence": 0.8, "extracted_at": "2026-05-29T13:58:05.824474+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=51", "doc_key": "a1fc8ae6b1cbf1f86de996b95dfc79fb"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '33423b058a9a07ad4f26ba1a41e209e4d0b02a344fa2263011341f4bf1963bc6'),
  ('cpiuris2025::3c28787f6b7bd50c3d42d2dbc4b18fb1', 'doutrina', 'cp_iuris', 'Direito Tributário — Instituição de tributos e suas características', '## Instituição de tributos e suas características

Questões sobre instituição de tributos, natureza jurídica do tributo e hipóteses de decadência.

### Conceitos
- **Tributo compulsório**: tributo instituído pela União ou por ente federado mediante lei complementar
- **Imposto residual**: imposto cobrado sobre a renda ou patrimônio de uma pessoa física ou jurídica
- **Fato gerador**: ocorrência que gera direito ou obrigação tributária
- **Destinação do recurso arrecadado**: finalidade para a qual o recurso arrecadado é destinado
- **Juros moratórios**: juros aplicados sobre débitos não pagos com tempo de vencimento

### Referências legais
- Art. 96 da Constituição Federal
- Código Tributário Nacional (CTN)

### Dicas de prova
- Entenda a distinção entre tributo compulsório e imposto residual
- Conheça o fato gerador e sua relação com a natureza jurídica do tributo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da Constituição Federal", "Código Tributário Nacional (CTN)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:58:39.120057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=52", "doc_key": "3c28787f6b7bd50c3d42d2dbc4b18fb1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '06b27ca413e6f5eb8f788a329f3fe033d30dafca389c006cd6f0d6e1a2896a6b'),
  ('cpiuris2025::e6270c887368bcd8711e61e1cb7e472e', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais', '## Contribuições Sociais

Resumo objetivo: Contribuições sociais têm natureza parafiscal e não se aplicam as normas gerais de direito tributário. A lei pode instituir contribuição social com a vinculação apenas de parte do produto da arrecadação.

### Conceitos
- **Contribuição Social**: tem natureza parafiscal
- **Imposto**: diferente de contribuição social pela destinação do produto da arrecadação
- **Vinculação**: apenas parte do produto da arrecadação

### Referências legais
- Art. 25 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a natureza parafiscal das contribuições sociais
- Diferencie as contribuições sociais dos impostos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.52 (2)", "page_number": 52, "discipline": "Direito Tributário", "legal_refs": ["Art. 25 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T13:59:11.240209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=52", "doc_key": "e6270c887368bcd8711e61e1cb7e472e"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '142df048bd413e980e349600728a2984087a645bcc0b1f6643321548067bbfbe'),
  ('cpiuris2025::bbb45ed80f12d2d84c545fee8eab9c75', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais e Natureza Jurídica', '## Contribuições Sociais e Natureza Jurídica

A questão discute a natureza jurídica das contribuições sociais, como a anuidade da OAB, a contribuição ao SEBRAE e a contribuição sindical, com o objetivo de determinar se elas são tributárias ou não.

### Conceitos
- **Contribuição Social**: Contribuição obrigatória para fins sociais
- **Tributação**: Imposto sobre a renda ou valor acrescido ao bem ou serviço
- **Natureza Jurídica**: Caracterização da obrigação tributária em relação à sua essência e finalidade

### Referências legais
- Art. 25 da CF/88
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Contribuições Sociais e Natureza Jurídica

### Dicas de prova
- Distinção entre contribuição social e tributação
- Análise da natureza jurídica das anuidades da OAB, do SEBRAE e da contribuição sindical', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.53 (1)", "page_number": 53, "discipline": "Direito Tributário", "legal_refs": ["Art. 25 da CF/88", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Contribuições Sociais e Natureza Jurídica"], "confidence": 0.8, "extracted_at": "2026-05-29T14:00:23.362222+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=53", "doc_key": "bbb45ed80f12d2d84c545fee8eab9c75"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2a65af5a4d3970ea6a4f3f566eff8cf06ca477def05d503143189956d6bb2f33'),
  ('cpiuris2025::29407346a3e554998a288f971bc523f8', 'doutrina', 'cp_iuris', 'Direito Tributário — Instituição de empréstimos compulsórios e impostos não previstos', '## Instituição de empréstimos compulsórios e impostos não previstos

A União pode instituir empréstimos compulsórios e impostos não previstos, mediante lei complementar, desde que sejam não-cumulativos e não tenham fato gerador ou base de cálculo próprios.

### Conceitos
- **Empréstimo compulsório**: instituição de crédito forçado pela União
- **Imposto não previsto**: imposto criado após a Constituição vigente

### Referências legais
- Art. 148 da Lei Complementar
- Art. 154 da Lei Complementar

### Dicas de prova
- Entenda que o empréstimo compulsório é uma instituição de crédito forçado pela União.
- Identifique se o imposto não previsto é não-cumulativo e não tem fato gerador ou base de cálculo próprios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.53 (2)", "page_number": 53, "discipline": "Direito Tributário", "legal_refs": ["Art. 148 da Lei Complementar", "Art. 154 da Lei Complementar"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:00:35.383051+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=53", "doc_key": "29407346a3e554998a288f971bc523f8"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '22bb9ce1b8c9d8edc969ad82cfae9e1fcf44cc546a382feac67619460876247b'),
  ('cpiuris2025::d7a8f9fc909a562d5ce7ee8d891d72b4', 'doutrina', 'cp_iuris', 'Direito Tributário — Natureza jurídica específica do tributo', '## Natureza jurídica específica do tributo

O artigo 4º da CTN determina que a natureza jurídica do tributo é determinada pelo fato gerador, independentemente das características formais e da destinação legal do produto da arrecadação.

### Conceitos
- **Fato gerador**: O evento ou situação que gera a obrigação tributária
- **Natureza jurídica específica do tributo**: A caracterização da tributação como um direito real ou uma obrigação de fazer algo

### Referências legais
- Art. 4º da CTN

### Dicas de prova
- Entenda a noção de fato gerador e sua importância na determinação da natureza jurídica do tributo
- Leia atentamente o artigo 4º da CTN e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.54", "page_number": 54, "discipline": "Direito Tributário", "legal_refs": ["Art. 4º da CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:01:09.951003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=54", "doc_key": "d7a8f9fc909a562d5ce7ee8d891d72b4"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a8f6115cb5262c29928963da7e6677d5e438863e565b4d55df3f2ccb7f5e3e3f'),
  ('cpiuris2025::d2668f817b43ecf8624347b52fba0cad', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuição Sindical e Imposto sobre Serviços', '## Contribuição Sindical e Imposto sobre Serviços

A contribuição sindical passou a ser facultativa com a Reforma Trabalhista, alterando os arts. 578 e 579 da CLT.

### Conceitos
- **Contribuição Sindical**: facultativa desde a Reforma Trabalhista
- **Reforma Trabalhista**: alterou os arts. 578 e 579 da CLT
- **Imposto sobre Serviços**: incide sobre operações de locação de bens móveis
- **Súmula Vinculante do STF**: não sujeita ao princípio da anterioridade
- **Taxa de Agenciamento**: incide apenas sobre a taxa de agenciamento em sociedades empresárias de trabalho temporário

### Referências legais
- Art. 70, parágrafo único e art. 71, I da CF/88
- Lei nº 13.467/2017

### Jurisprudência
- STF Plenário MS 28465/DF
- Súmula Vinculante do STF (Enunciado 41)

### Dicas de prova
- Diferenciar entre contribuição sindical facultativa e obrigatória
- Entender a alteração nos arts. 578 e 579 da CLT com a Reforma Trabalhista
- Conhecer as regras do Imposto sobre Serviços de Qualquer Natureza (ISS)
- Identificar a aplicabilidade da Súmula Vinculante 50 do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.55 (2)", "page_number": 55, "discipline": "Direito Tributário", "legal_refs": ["Art. 70, parágrafo único e art. 71, I da CF/88", "Lei nº 13.467/2017"], "jurisprudence": ["STF Plenário MS 28465/DF", "Súmula Vinculante do STF (Enunciado 41)"], "confidence": 0.8, "extracted_at": "2026-05-29T14:03:15.318634+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=55", "doc_key": "d2668f817b43ecf8624347b52fba0cad"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c1b723a0c54f6b10610e56e49d3a6c799edc5f3bc403e57b675b5da64d6fb4eb'),
  ('cpiuris2025::b1047f5f43c16911f70f131e8f318cb2', 'doutrina', 'cp_iuris', 'Direito Tributário — Técnica tributária e autonomia federativa', '## Técnica tributária e autonomia federativa

A técnica tributária promove a destinação de recursos para o Estado, sendo duas formas: atribuição de competência e participação no produto da arrecadação. A autonomia federativa é caracterizada pelo exercício da tributação e pela possibilidade de criar tributos.

### Conceitos
- **Técnica tributária**: Métodos utilizados para promover a destinação de recursos para o Estado
- **Atribuição de competência**: Distribuição da competência tributária sobre determinadas materialidades abertas à tributação pela Constituição Federal
- **Participação no produto da arrecadação**: Compartilhamento dos recursos arrecadados com os demais entes federativos
- **Autonomia federativa**: Direito do Estado de exercer a tributação e criar tributos

### Referências legais
- Art. 100 da Constituição Federal
- Súmula 646 do Supremo Tribunal Federal

### Jurisprudência
- RE 705.423

### Dicas de prova
- Entenda a diferença entre atribuição de competência e participação no produto da arrecadação
- Conheça o conceito de autonomia federativa e seu relação com a tributação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 da Constituição Federal", "Súmula 646 do Supremo Tribunal Federal"], "jurisprudence": ["RE 705.423"], "confidence": 0.8, "extracted_at": "2026-05-29T14:03:34.246369+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=57", "doc_key": "b1047f5f43c16911f70f131e8f318cb2"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '711b74e82f7748ef6ef23a7996617fa7eaef495a22452f5a68baf838693ae7b3'),
  ('cpiuris2025::8af4a6bb763bf5feeb07f0a36d697767', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência dos Conselhos Regionais de Fiscalização Profissional', '## Competência dos Conselhos Regionais de Fiscalização Profissional

A competência dos Conselhos Regionais de Fiscalização Profissional é discutida em relação à fixação e aumento do valor das anuidades, com decisões do STF que consideram inconstitucional a delegação de competência sem parâmetro legal.

### Conceitos
- **Competência**: A capacidade ou autoridade para agir em um determinado assunto
- **Delegação de Competência**: O ato de transferir uma competência de uma entidade para outra
- **Parâmetro Legal**: Um critério ou limite estabelecido por lei para a fixação de valores ou taxas
- **Autarquia**: Uma entidade pública que opera com autonomia administrativa e financeira
- **Sui Generis**: Um termo usado para descrever uma categoria ou conceito que não se enquadra em nenhuma das categorias existentes
- **Contribuição Tributária**: Uma contribuição obrigatória imposto pelo Estado sobre a renda ou atividade econômica de uma pessoa física ou jurídica
- **Micro e Pequenas Empresas**: Empresas com número de funcionários e faturamento limitados, que recebem apoio do Serviço Brasileiro de Apoio às Micro e Pequenas Empresas (SEBRAE)
- **Contribuição Social**: Uma contribuição obrigatória imposto pelo Estado sobre a renda ou atividade econômica de uma pessoa física ou jurídica, destinada a financiar programas sociais

### Referências legais
- Art. 8º, da Lei n.º 12.514/11
- RE 704.292/PR
- STF no RE 396.266
- RE 389.016-AgR

### Jurisprudência
- Repercussão Geral pelo STF no RE 704.292/PR
- RE 396.266
- RE 389.016-AgR

### Dicas de prova
- Entenda a competência dos Conselhos Regionais de Fiscalização Profissional e as implicações da delegação de competência sem parâmetro legal.
- Identifique o conceito de autarquia e sua aplicação nos casos apresentados.
- Aprenda a distinguir entre contribuição tributária e contribuição social, bem como suas características e exemplos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Direito Tributário", "legal_refs": ["Art. 8º, da Lei n.º 12.514/11", "RE 704.292/PR", "STF no RE 396.266", "RE 389.016-AgR"], "jurisprudence": ["Repercussão Geral pelo STF no RE 704.292/PR", "RE 396.266", "RE 389.016-AgR"], "confidence": 0.8, "extracted_at": "2026-05-29T14:04:51.557367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=55", "doc_key": "8af4a6bb763bf5feeb07f0a36d697767"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8ef48b64a30c8f61cb2b449fd751389ad79d32a1ea11b112942d86faa194969c'),
  ('cpiuris2025::8edc97597f4d212eb6539e1f89ca9512', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária', '## Competência Tributária

A competência tributária própria ou por participação no produto da arrecadação de outro ente federativo é um conceito importante na legislação tributária brasileira.

### Conceitos
- **Competência Tributária**: A capacidade do Estado de instituir e cobrar impostos
- **Autonomia Federativa**: O direito dos estados federados de agir de acordo com suas próprias necessidades e interesses
- **Prerrogativa Única e Indelegável**: O direito exclusivo do Estado de instituir um tributo
- **Desprestígio Normogenético Tributário**: A perda da capacidade de instituir um tributo

### Referências legais
- Art. 100 da CF
- Súmula 646/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Tributária

### Dicas de prova
- Entenda a autonomia federativa e sua relação com a competência tributária
- Diferencie entre prerrogativa única e indelegável e desprestígio normogenético tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 da CF", "Súmula 646/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T14:05:23.334033+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=57", "doc_key": "8edc97597f4d212eb6539e1f89ca9512"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'dc4bb30f2c727fb159b4e94530815c091e367bc6cbaaf738fa7740425fd87cc3'),
  ('cpiuris2025::50821984db6f348b9fe2e99e2169e376', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária', '## Competência Tributária

A competência tributária é uma prerrogativa federativa que permite ao ente federativo exercer o poder de tributar e se financiar mediante a tributação. É uma espécie de autonomia federativa, mas não se confunde com a competência legislativa ou a competência para legislar sobre Direito Tributário.

### Conceitos
- **Autonomia Federativa**: Capacidade do ente federativo de se organizar e cumprir as finalidades da Constituição
- **Competência Tributária**: Prerrogativa federativa que permite ao ente federativo exercer o poder de tributar
- **Poder de Tributar**: Direito do ente federativo de instituir e cobrar tributos
- **Competência Legislativa**: Direito do ente federativo de legislar sobre Direito Tributário
- **Competência para Legislar sobre Direito Tributário**: Espécie de competência legislativa concorrente que permite ao Município estabelecer seu próprio Código Tributário Municipal

### Referências legais
- Art. 100 da CF/88

### Jurisprudência
- RE 123456
- Súmula 455/STF

### Dicas de prova
- Entenda a distinção entre competência tributária e competência legislativa
- Conheça a autonomia federativa e sua relação com a competência tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 da CF/88"], "jurisprudence": ["RE 123456", "Súmula 455/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T14:05:52.013080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=58", "doc_key": "50821984db6f348b9fe2e99e2169e376"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '40d7144e83a34e72bf4ab315e0e0fcaa90020a4257f3f780fec1942e2b558b02'),
  ('cpiuris2025::9d47209bb2f0d3cd287a72a4fe9a9229', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência e Capacidade Tributária Ativa', '## Competência e Capacidade Tributária Ativa

A competência tributária é a capacidade do Estado de criar o tributo, enquanto a capacidade tributária ativa é a capacidade para figurar no polo ativo de uma relação obrigacional tributária.

### Conceitos
- **Competência Tributária**: A capacidade do Estado de criar o tributo
- **Capacidade Tributária Ativa**: A capacidade para figurar no polo ativo de uma relação obrigacional tributária

### Referências legais
- Art. 7º do CTN

### Dicas de prova
- Entenda a distinção entre competência e capacidade tributária ativa.
- Lembre-se de que a delegação da capacidade tributária ativa é permitida pelo CTN.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direito Tributário", "legal_refs": ["Art. 7º do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:05:57.788162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=58", "doc_key": "9d47209bb2f0d3cd287a72a4fe9a9229"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '32fbc3ca9d8ef7967c6728b160c1d81ce6ef76aedacc777d4818bb51cd31d286'),
  ('cpiuris2025::9d097bb2460a84d704bc179aa05a97da', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições para o custeio de serviços públicos', '## Contribuições para o custeio de serviços públicos

A contribuição instituída pelos Municípios e Distrito Federal para financiar a iluminação pública e sistemas de monitoramento, com possibilidade de cobrança na fatura de energia elétrica.

### Conceitos
- **Contribuição**: imposto ou tributo instituído por entidades políticas para financiar serviços públicos
- **Serviços Públicos**: atividades essenciais e necessárias à coesão social, como educação, saúde, segurança, etc.
- **Cobrança**: procedimento pelo qual o Estado exige a pagamento de um tributo ou imposto
- **Fatura de Consumo**: documentação que comprova o consumo de energia elétrica por uma unidade federativa ou município

### Referências legais
- Art. 149-A
- Art. 150, I e III

### Dicas de prova
- Entenda a distinção entre contribuição e imposto
- Conheça as regras de cobrança de contribuições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Direito Tributário", "legal_refs": ["Art. 149-A", "Art. 150, I e III"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:08:11.424204+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=59", "doc_key": "9d097bb2460a84d704bc179aa05a97da"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '763cd5c3f6be4f95f454a1dae85a557675a5cc6d257a62823839ff5b83ba8987'),
  ('cpiuris2025::c04c0eeeaee10597b11c4bc47f404684', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária na CF/88', '## Competência Tributária na CF/88

A competência tributária é prerrogativa federativa não delegável, que não pode ser exercida concomitantemente por dois entes federativos, evitando a ''bitributação'' jurídica.

### Conceitos
- **Competência Tributária**: Prerrogativa federativa que determina a competência dos entes federativos para instituir tributos.
- **Delegabilidade da Competência Tributária**: Não é delegável, pois seria vedada a ''bitributação'' jurídica.
- **Entes Federativos**: União, Estados, Distrito Federal e Municípios.
- **Tributos**: Impostos, taxas, contribuição de melhoria e empréstimos compulsórios.

### Referências legais
- Art. 145 da CF/88
- Art. 148 da CF/88
- Art. 149 da CF/88

### Dicas de prova
- Entenda a noção de competência tributária e sua não delegabilidade.
- Conheça os entes federativos e seus poderes para instituir tributos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Direito Tributário", "legal_refs": ["Art. 145 da CF/88", "Art. 148 da CF/88", "Art. 149 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:08:34.925298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=59", "doc_key": "c04c0eeeaee10597b11c4bc47f404684"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '65d35720c73123dca1689f5f30a4b5dba00ec43217a430f3b25a2a0bff98f038'),
  ('cpiuris2025::da51a51ee879cb27e33650d931205148', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária', '## Competência Tributária

A competência tributária pode ser classificada em privativa, comum, residual, cumulativa e compartilhada. A competência privativa é atribuída a um ente político específico, enquanto a comum é atribuída aos entes políticos em geral.

### Conceitos
- **Competência Privativa**: Atribuição de competência tributária a um ente político específico
- **Competência Comum**: Atribuição de competência tributária aos entes políticos em geral
- **Residual**: Competência atribuída ao ente federativo que não é privativa ou comum
- **Cumulativa**: Competência que pode ser exercida por mais de um ente político
- **Compartilhada**: Competência atribuída a múltiplos entes políticos

### Referências legais
- Art. 154, § 1º, da CF
- Art. 155 e 156 da CF
- CTN, art. 80

### Dicas de prova
- Entenda a distinção entre competência privativa e comum
- Conheça as diferentes formas de competência tributária (residual, cumulativa, compartilhada)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.60", "page_number": 60, "discipline": "Direito Tributário", "legal_refs": ["Art. 154, § 1º, da CF", "Art. 155 e 156 da CF", "CTN, art. 80"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:09:00.237190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=60", "doc_key": "da51a51ee879cb27e33650d931205148"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'bb0323355265797032ff1e74a7800cdd30c1b31d150170755081b380119cde66'),
  ('cpiuris2025::15f76f787c4b057114ad76e83e654abf', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária e Capacidade Tributária Ativa', '## Competência Tributária e Capacidade Tributária Ativa

A competência tributária é indelegível e somente pode ser exercida por entes políticos. A capacidade tributária ativa é uma possibilidade de estar no polo ativo da relação obrigacional, podendo decorrer da lei ou legislação tributária.

### Conceitos
- **Competência Tributária**: instituição do tributo por meio de lei
- **Capacidade Tributária Ativa**: possibilidade de estar no polo ativo da relação obrigacional, poder de cobrar e fiscalizar
- **Competência Tributária Indelegável**: não pode ser delegada a outra pessoa jurídica de direito público

### Referências legais
- Art. 7º do CTN
- Art. 18 da Constituição

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a distinção entre competência tributária e capacidade tributária ativa
- Conheça a regra de não delegação de competência tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.62", "page_number": 62, "discipline": "Direito Tributário", "legal_refs": ["Art. 7º do CTN", "Art. 18 da Constituição"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T14:10:48.761389+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=62", "doc_key": "15f76f787c4b057114ad76e83e654abf"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '1f213bed89acf3895f8f5fd8a2887a148abe9cfb7ba9a01c74bfc8f6a4bf4d26'),
  ('cpiuris2025::13d1b33bb386c8dd543df28fd93ee3ef', 'doutrina', 'cp_iuris', 'Direito Tributário — Delegabilidade e Capacidade Tributária Ativa', '## Delegabilidade e Capacidade Tributária Ativa

A capacidade tributária ativa é delegável, enquanto a competência tributária não. A delegação de capacidade tributária pode ser revogada por ato unilateral da pessoa jurídica de direito público que a tenha conferido.

### Conceitos
- **Delegabilidade**: A capacidade tributária ativa é delegável
- **Capacidade Tributária Ativa**: Prerrogativa de cobrar os tributos previamente criados
- **Competência Tributária**: Legislativa para a criação do tributo
- **Atribuição Revogável**: Pode ser revogada por ato unilateral da pessoa jurídica de direito público

### Referências legais
- Art. 7º, § 2º, CTN
- Art. 153, § 4º, inciso III, CF/88

### Dicas de prova
- Entenda a distinção entre capacidade tributária ativa e competência tributária
- Conheça as limitações constitucionais ao poder de tributar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.63", "page_number": 63, "discipline": "Direito Tributário", "legal_refs": ["Art. 7º, § 2º, CTN", "Art. 153, § 4º, inciso III, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:11:11.664686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=63", "doc_key": "13d1b33bb386c8dd543df28fd93ee3ef"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '699f3b6e94c4540dbff3f014b340c30d644a4bd3c73f03d10b3d1e304bb9d020'),
  ('cpiuris2025::19cb5530e889336a45d4ab42ce8c3399', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária', '## Competência Tributária

A competência tributária é distribuída entre os entes federativos e a União, com competências comum, privativa, cumulativa e compartilhada definidas por dispositivos constitucionais.

### Conceitos
- **Competência Comum**: Atribuída a todos os entes federativos (União, Estados, DF e Municípios)
- **Competência Privativa**: Privativa quanto às espécies de impostos
- **Competência Cumulativa**: Exercida pela União nos Territórios e DF
- **Competência Compartilhada**: Instituída por lei complementar entre Estados, Distrito Federal e Municípios
- **Competência Residual**: Atribuída à União nos termos do art. 154, I da CF/88
- **Competência Extraordinária**: Instituída pelo art. 154, II da CF/88

### Referências legais
- Art. 145 da CF/88
- Art. 147 da CF/88
- Art. 149-A da CF/88
- Art. 149 da CF/88
- Art. 153 da CF/88
- Art. 154, I da CF/88
- Art. 154, II da CF/88
- Lei Complementar nº 39 de 2002

### Jurisprudência
- RE 123456
- Tema repetitivo COSIP

### Dicas de prova
- Entenda a competência comum, privativa, cumulativa e compartilhada
- Conheça as exceções, como a competência residual e extraordinária
- Lembre-se de que a União tem competência sobre impostos estaduais em Territórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.61", "page_number": 61, "discipline": "Direito Tributário", "legal_refs": ["Art. 145 da CF/88", "Art. 147 da CF/88", "Art. 149-A da CF/88", "Art. 149 da CF/88", "Art. 153 da CF/88", "Art. 154, I da CF/88", "Art. 154, II da CF/88", "Lei Complementar nº 39 de 2002"], "jurisprudence": ["RE 123456", "Tema repetitivo COSIP"], "confidence": 0.8, "extracted_at": "2026-05-29T14:11:55.375341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=61", "doc_key": "19cb5530e889336a45d4ab42ce8c3399"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '030129d3449a2ab4964aa95df9a5c6fdd8d919c924c52e851b973d07b03ffdd2'),
  ('cpiuris2025::26a55c464fef091cc2e06e7368ef03bb', 'doutrina', 'cp_iuris', 'Direito Tributário — Delegação de competência tributária', '## Delegação de competência tributária

A delegação de competência tributária é possível, mas com limitações, sendo permitida a delegação das funções de fiscalização e arrecadação, bem como a produção de normas para definição dos tributos.

### Conceitos
- **Delegação de competência**: A transferência da competência tributária de um ente para outro
- **Competência tributária**: O poder do Estado de instituir e cobrar tributos
- **Fiscalização**: A atividade de verificar se as pessoas físicas ou jurídicas estão cumprindo com as obrigações fiscais
- **Arrecadação**: O ato de coletar os tributos instituídos pelo Estado

### Referências legais
- Art. 100 da CF/88

### Dicas de prova
- Entenda a distinção entre delegação de competência e transferência de competência
- Leia atentamente as alternativas para identificar a correta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.64 (2)", "page_number": 64, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:13:16.268343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=64", "doc_key": "26a55c464fef091cc2e06e7368ef03bb"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'bd895d95c7869af4f39f4c33b80e8d06352bfa6c84d56a0386ecc5c39cc75722'),
  ('cpiuris2025::750f06fb0679bf2cb4f0e78a4da5619c', 'doutrina', 'cp_iuris', 'Direito Tributário — Limitações ao Poder Tributário', '## Limitações ao Poder Tributário

O Estado pode tributar, mas atendendo à sistemática adotada e preservando interesses constitucionalmente importantes. A tributação se relaciona ao direito de propriedade e deve garantir a garantia prevista no art. 5º da CF/88.

### Conceitos
- **Competência Tributária**: A competência do Estado para instituir tributos
- **Imunidade Tributária**: Previsão constitucional que dispensa o pagamento de tributo
- **Isenção Tributária**: Previsão constitucional que permite redução ou exclusão do pagamento de tributo
- **Poder Tributário**: O poder do Estado para instituir e cobrar tributos
- **Competência Residual**: A competência do Estado para instituir tributos que não estão expressamente previstas em lei

### Referências legais
- Art. 5º da CF/88
- Art. 150 da CF/88

### Dicas de prova
- Entenda a distinção entre imunidade e isenção tributárias
- Avalie a competência do Estado para instituir tributos
- Lembre-se de que a tributação se relaciona ao direito de propriedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.64 (1)", "page_number": 64, "discipline": "Direito Tributário", "legal_refs": ["Art. 5º da CF/88", "Art. 150 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:13:36.275363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=64", "doc_key": "750f06fb0679bf2cb4f0e78a4da5619c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '56b33371075f688c1c8283b5f6346da65b7dd10acae1d451a3197d8fdcf7af06'),
  ('cpiuris2025::dc566cc58d80248d87d1391f0aa48368', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária', '## Competência Tributária

A competência tributária é privativa, mas a União pode instituir impostos de competência dos Estados e do Distrito Federal em Territórios Federais. A imunidade tributária expressa a incompetência do ente para instituição do tributo.

### Conceitos
- **Competência Tributária**: A capacidade do Estado de instituir tributos
- **Imunidade Tributária**: A falta de competência do ente para instituição do tributo
- **Privatividade da Competência Tributária**: A competência é exclusiva de um ente político
- **Competência Constitucional**: A competência é prevista na Constituição Federal

### Referências legais
- Art. 96 da CF/88
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Tributária

### Dicas de prova
- Entenda a noção de competência tributária e imunidade tributária
- Conheça as regras de privatividade da competência tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.65", "page_number": 65, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da CF/88", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T14:14:16.747660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=65", "doc_key": "dc566cc58d80248d87d1391f0aa48368"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ef9580e6f6936df4ebb70ca64732dc409fb2dc35adbe4e380642d6411f157c0b'),
  ('cpiuris2025::5e607410522eefef55f7d3e2b4ab0f1e', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária', '## Competência Tributária

A competência tributária é indelegível, salvo atribuição de funções específicas, e não pode ser exercida concomitantemente por dois entes federativos.

### Conceitos
- **Competência Tributária**: Poder do Estado de exigir impostos
- **Indelegabilidade**: Não pode ser delegada a outrem
- **Atribuição de Funções**: Conferida por uma pessoa jurídica de direito público a outra
- **Competência Concomitante**: Exercida simultaneamente por dois entes federativos

### Referências legais
- Art. 7º, do CTN
- Art. 156, da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de competência tributária e sua indelegabilidade
- Conheça as exceções à regra geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direito Tributário", "legal_refs": ["Art. 7º, do CTN", "Art. 156, da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T14:15:22.588702+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=67", "doc_key": "5e607410522eefef55f7d3e2b4ab0f1e"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '16e7887e5d84ecbc32c09b7a0dbf23d83a177abbf0b0f45310b3d24da9230600'),
  ('cpiuris2025::4ecfb8db2aba646822032861b0fa7ca0', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais', '## Contribuições Sociais

A União tem exclusiva competência para instituir contribuições sociais, de intervenção no domínio econômico e de interesse das categorias profissionais ou econômicas.

### Conceitos
- **Contribuição Social**: instituto tributário destinado a financiar atividades sociais
- **Competência Exclusiva da União**: direito do Estado para instituir contribuições sociais

### Referências legais
- CF/88, Art. 149

### Jurisprudência
- Súmula n.º 670 do STF

### Dicas de prova
- Entenda a competência exclusiva da União para instituir contribuições sociais.
- Conheça as categorias profissionais ou econômicas que podem ser atingidas por essas contribuições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direito Tributário", "legal_refs": ["CF/88, Art. 149"], "jurisprudence": ["Súmula n.º 670 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T14:15:51.305409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=67", "doc_key": "4ecfb8db2aba646822032861b0fa7ca0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '067a61ea1c19dbf6376db2c6a57374cbd52d957b0156fa972ba4fcf8b809260b'),
  ('cpiuris2025::5f341c54011f34465e8059f0bd476942', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária', '## Competência Tributária

O município pode instituir contribuição para o custeio do serviço de iluminação pública, desde que observe os princípios da legalidade e da anterioridade. A competência tributária é exercida pela União, pelos Estados e pelo Distrito Federal, mas não há competência residual tributária a ser exercida pelos Estados.

### Conceitos
- **Competência Tributária**: A capacidade do Estado de instituir impostos
- **Sistema Tributário Nacional**: O sistema que regula a tributação no Brasil
- **Princípio da Legalidade**: O princípio que estabelece que os impostos devem ser instituídos e aplicados em conformidade com a lei
- **Princípio da Anterioridade**: O princípio que estabelece que os impostos devem ser pagos antes de ocorrer o fato gerador do imposto

### Referências legais
- Art. 154 da CF/88

### Dicas de prova
- Pergunte sobre a competência tributária e os princípios que regem o sistema tributário nacional
- Lembre-se de que a União, os Estados e o Distrito Federal têm competência tributária residual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.66", "page_number": 66, "discipline": "Direito Tributário", "legal_refs": ["Art. 154 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:16:06.638216+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=66", "doc_key": "5f341c54011f34465e8059f0bd476942"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a43ee88c092ca4aef90bd11dcb948282f4d48dd9e79eb9b6b62054ff9fa08397'),
  ('cpiuris2025::db85589b6543a31bb1cf09b39b6521f7', 'doutrina', 'cp_iuris', 'Direito Tributário — Exigência de Lei para Aumento ou Exigência de Tributo', '## Exigência de Lei para Aumento ou Exigência de Tributo

O artigo 150 da Constituição Federal estabelece que os Estados, Distrito Federal e Municípios não podem exigir ou aumentar tributos sem lei que o estabeleça.

### Conceitos
- **Art. 150**: Garante a necessidade de lei para aumento ou exigência de tributo
- **Progressividade**: Aumento do imposto com base no valor do imóvel ou da operação
- **Competência Tributária**: O poder do Estado para cobrar tributos

### Referências legais
- Art. 150 da Constituição Federal

### Dicas de prova
- Entenda a progressividade no tempo e sua aplicação aos impostos
- Conheça as regras de competência tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.68", "page_number": 68, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:17:12.482345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=68", "doc_key": "db85589b6543a31bb1cf09b39b6521f7"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b61a8aa68335324fc5d0d70ad189c32b7b8404a937228e362a0c7779019965cd'),
  ('cpiuris2025::05e44091982c3337560f11498390b246', 'doutrina', 'cp_iuris', 'Direito Tributário — Justiça Tributária', '## Justiça Tributária

A justiça tributária é um princípio matriz que guia todos os princípios constitucionais tributários, visando a obtenção de uma justiça tributária transparente e previsível para os contribuintes.

### Conceitos
- **Justiça Tributária**: Princípio matriz que guia todos os princípios constitucionais tributários
- **Legalidade**: Princípio que determina a legalidade das obrigações tributárias
- **Irretroatividade**: Princípio que proíbe a retroatividade de leis tributárias
- **Anterioridades**: Princípio que determina a anterioridade das leis tributárias
- **Cooperação**: Princípio que visa a cooperação entre o Fisco e os contribuintes, bem como entre as esferas federativas tributantes

### Referências legais
- Art. 100 da Constituição Federal

### Dicas de prova
- Entenda a importância da justiça tributária e seus princípios
- Diferencie a cooperação do Fisco com os contribuintes de outros tipos de cooperação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:18:20.277533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=70", "doc_key": "05e44091982c3337560f11498390b246"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '911018e063c51abf65c842e0dfbdfb54d2dbf946843606ec6b92914f41b50ab7'),
  ('cpiuris2025::df6812374960d074cbede4ab76f37adf', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios Constitucionais Tributários de Proteção Federativa e Cooperação', '## Princípios Constitucionais Tributários de Proteção Federativa e Cooperação

Os princípios tributários são diretrizes para a tributação, ditando as diretrizes que devem ser seguidas e respeitadas. São como sinalizações em uma estrada.

### Conceitos
- **Princípio da Simplicidade**: O princípio da simplicidade exige que os tributos sejam criados com materialidades bem expressas e expostas de modo claro aos contribuintes.
- **Princípio da Transparência**: O princípio da transparência exige que a Administração tributária seja transparente em sua atuação, evitando discussões judiciais acerca da futura cobrança.
- **Princípio da Justiça Tributária**: O princípio da justiça tributária exige que o processo administrativo tributário e judicial seja simples e justo.
- **Princípio da Cooperação**: O princípio da cooperação exige que a Administração tributária se pauta pelo princípio da cooperação com os demais entes federativos.
- **Princípio da Defesa do Meio Ambiente**: O princípio da defesa do meio ambiente exige que a Administração tributária busque atenuar efeitos regressivos e proteger o meio ambiente.

### Referências legais
- Art. 145 §3º da CF/88
- EC 132/2023

### Dicas de prova
- Entenda os princípios tributários e suas implicações na tributação.
- Análise do artigo 145 da Constituição Federal e sua relação com a Reforma Tributária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Direito Tributário", "legal_refs": ["Art. 145 §3º da CF/88", "EC 132/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:18:49.933745+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=70", "doc_key": "df6812374960d074cbede4ab76f37adf"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'dae34881b4686b4c9fe938db6f105d4ce979fa7c83f013602570775fd58bc655'),
  ('cpiuris2025::a1de2df2d64858cb1254969f0c4763d9', 'doutrina', 'cp_iuris', 'Direito Tributário — Defesa do meio ambiente como diretriz principiológica na Reforma Tributária', '## Defesa do meio ambiente como diretriz principiológica na Reforma Tributária

A defesa do meio ambiente é uma diretriz principiológica da Reforma Tributária, buscando atingir um efeito extrafiscal na tributação para proteger o meio ambiente.

### Conceitos
- **Reforma Tributária**: Modificação das leis tributárias para atender a novas diretrizes principiológicas
- **Imposto sobre produção, extração, comercialização ou importação de bens e serviços prejudiciais à saúde ou ao meio ambiente**: Novo imposto criado pela Reforma Tributária para proteger o meio ambiente
- **Fundo Nacional de Desenvolvimento Regional**: Fundo criado pela Reforma Tributária para reduzir as desigualdades regionais e sociais com prioridade a projetos de sustentabilidade ambiental
- **Incentivos regionais**: Benefícios concedidos aos Estados e ao Distrito Federal para promover o desenvolvimento regional com critérios de sustentabilidade ambiental
- **Isenções, reduções ou diferimento temporário de tributos federais**: Incentivos regionais que incluem isenções, reduções ou diferimento temporário de tributos federais

### Referências legais
- Art. 153 da Lei Complementar nº 132/2023
- Art. 43, §4º da Constituição Federal

### Dicas de prova
- Entenda a relação entre a defesa do meio ambiente e a Reforma Tributária
- Identifique os novos impostos criados pela Reforma Tributária para proteger o meio ambiente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direito Tributário", "legal_refs": ["Art. 153 da Lei Complementar nº 132/2023", "Art. 43, §4º da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:19:07.814867+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=71", "doc_key": "a1de2df2d64858cb1254969f0c4763d9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '78018755bdcce9cc34fcde5499d882cac97f91293fc2909b7964b7c4a4f208d9'),
  ('cpiuris2025::7ecbb9481aa336eddb127a613f5c1d6c', 'doutrina', 'cp_iuris', 'Direito Tributário — Capacidade Contributiva e Tributação', '## Capacidade Contributiva e Tributação

O artigo 145, § 1º da CF/88 estabelece que os impostos terão caráter pessoal e serão graduados segundo a capacidade econômica do contribuinte.

### Conceitos
- **Capacidade Contributiva**: A capacidade de um contribuinte para pagar imposto, relacionada à sua capacidade econômica
- **Tributação**: O direito do Estado de exigir contribuições ou impostos dos cidadãos
- **Graduação segundo a capacidade econômica**: A aplicação da alíquota do imposto com base na capacidade econômica do contribuinte

### Referências legais
- Art. 145, § 1º da CF/88

### Dicas de prova
- Entenda a noção de capacidade contributiva e como ela se relaciona com a tributação
- Identifique a base para a graduação dos impostos segundo a capacidade econômica do contribuinte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direito Tributário", "legal_refs": ["Art. 145, § 1º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:21:10.840756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=71", "doc_key": "7ecbb9481aa336eddb127a613f5c1d6c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2d2c319d5ee168b860928f36675fae713e4140c20d0713c966f7bb51562f2f31'),
  ('cpiuris2025::6d10eb1eabb3dd36ca7821521275a448', 'doutrina', 'cp_iuris', 'Direito Tributário — Autorização judicial para fins fiscais e aplicação retroativa de leis tributárias', '## Autorização judicial para fins fiscais e aplicação retroativa de leis tributárias

O artigo 6º da Lei Complementar nº 105/2001 permite a obtenção de informações financeiras do contribuinte sem autorização judicial, garantindo igualdade em relação aos cidadãos. A Lei 10.174/01 não é aplicável retroativamente, pois tem caráter instrumental e não viola o princípio da irretroatividade.

### Conceitos
- **Princípio da capacidade contributiva**: Garante igualdade em relação aos cidadãos
- **Requisitos objetivos**: Estabelecidos para garantir a legalidade das ações fiscais
- **Translado do dever de sigilo**: Da esfera bancária para a fiscal
- **Princípio da irretroatividade**: Proíbe a aplicação retroativa de leis tributárias sem expressa previsão na norma original

### Referências legais
- Art. 6º da Lei Complementar nº 105/2001
- Art. 144, § 1º, do CTN

### Dicas de prova
- Distinção entre autorização judicial e requisitos objetivos
- Caráter instrumental da Lei 10.174/01
- Importância do princípio da capacidade contributiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direito Tributário", "legal_refs": ["Art. 6º da Lei Complementar nº 105/2001", "Art. 144, § 1º, do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:21:58.106360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=72", "doc_key": "6d10eb1eabb3dd36ca7821521275a448"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd1bb1f1409672639fbf1623fbb7d77ef564f2816ab2470faf4dbfff158ef8b63'),
  ('cpiuris2025::e0e623528b5633a77f09125afbe5c420', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípio da Capacidade Contributiva', '## Princípio da Capacidade Contributiva

O princípio da capacidade contributiva é um corolário do princípio da isonomia, estabelecendo que os contribuintes devem pagar tributos de acordo com suas possibilidades, sem confisco excessivo.

### Conceitos
- **Princípio da Capacidade Contributiva**: princípio que determina a relação entre o contribuinte e o Estado
- **Isonomia**: princípio que estabelece igualdade perante a lei
- **Piso (patrimônio mínimo)**: limite mínima de patrimônio para pagamento de tributos
- **Teto (vedação do confisco)**: limite máxima de confisco para pagamento de tributos

### Referências legais
- Art. 118 do CTN
- Art. 145, § 1º da CF/88

### Jurisprudência
- {''RE'': ''656'', ''Tema'': ''Inconstitucionalidade da lei com alíquotas progressivas para ITBI''}
- {''RE'': ''668'', ''Tema'': ''Inconstitucionalidade da lei municipal com alíquotas progressivas para IPTU''}

### Dicas de prova
- Entenda a relação entre o princípio da capacidade contributiva e a isonomia
- Conheça os subprincípios da capacidade contributiva (proporcionalidade, progressividade, seletividade)
- Aprenda sobre o piso e o teto na tributação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direito Tributário", "legal_refs": ["Art. 118 do CTN", "Art. 145, § 1º da CF/88"], "jurisprudence": ["{''RE'': ''656'', ''Tema'': ''Inconstitucionalidade da lei com alíquotas progressivas para ITBI''}", "{''RE'': ''668'', ''Tema'': ''Inconstitucionalidade da lei municipal com alíquotas progressivas para IPTU''}"], "confidence": 0.8, "extracted_at": "2026-05-29T14:22:04.911265+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=72", "doc_key": "e0e623528b5633a77f09125afbe5c420"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b7cb78e2e48537f0e77f9782e57dda7c91585030d9d4c5e74a6e66bda70dc389'),
  ('cpiuris2025::3366aa4c0a84e8a32acea8399e2b2043', 'doutrina', 'cp_iuris', 'Direito Tributário — Majoração de Tributo', '## Majoração de Tributo

Define majoração de tributo e distingue-a da atualização do valor monetário da base de cálculo.

### Conceitos
- **majoração de tributo**: alteração que torna o tributo mais oneroso
- **atualização do valor monetário**: mudança no valor nominal da base de cálculo
- **base de cálculo**: valor ou quantidade utilizada para calcular o tributo

### Referências legais
- Art. 110 da Lei nº 10.365/2001

### Dicas de prova
- Distinguir entre majoração e atualização do valor monetário
- Entender a noção de base de cálculo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direito Tributário", "legal_refs": ["Art. 110 da Lei nº 10.365/2001"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:23:30.705111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=73", "doc_key": "3366aa4c0a84e8a32acea8399e2b2043"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6ed15ba108fd5c902f2bc44ce3a25e2320e37cb815decaca77f7a96c1855c537'),
  ('cpiuris2025::103316afffa4f0653d23fb9f757c7274', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípio da Legalidade', '## Princípio da Legalidade

O princípio da legalidade tributária é garantido pela Constituição Federal de 1988 e deve ser observado em instituir, desonerar ou majorar tributos. A lei é necessária para estabelecer os tributos, sua extinção, majoração ou redução, definição do fato gerador da obrigação tributária principal, fixação de alíquota e base de cálculo, bem como cominação de penalidades.

### Conceitos
- **Princípio da Legalidade**: Garantia constitucional que a lei é necessária para instituir, desonerar ou majorar tributos
- **Representatividade Popular**: A população tem direito de participar do processo legislativo e decidir sobre os impostos
- **Análise Parlamentar**: O parlamento deve analisar e aprovar as desonerações tributárias para evitar a injustiça
- **Lei Específica**: Uma lei específica é necessária para regular os tributos, contribuições e impostos
- **Garantias Constitucionais**: As garantias constitucionais incluem a liberdade, segurança, propriedade, família, educação, saúde, trabalho, lazer, prevenção da pobreza e do abuso de poder
- **Tributos**: São impostos ou contribuições exigidos pelo Estado para financiar suas atividades
- **Contribuições**: São tributos ou impostos exigidos por entes públicos para financiar suas atividades

### Referências legais
- Art. 5, II da CF/88
- Art. 150, § 6º da CF/88
- Art. 97 do CTN

### Jurisprudência
- ADIs supracitadas
- RE 123456

### Dicas de prova
- Entenda a importância da representatividade popular e do papel do parlamento na aprovação de desonerações tributárias
- Conheça as garantias constitucionais que protegem os direitos dos contribuintes
- Aprenda a distinguir entre tributos, contribuições e impostos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direito Tributário", "legal_refs": ["Art. 5, II da CF/88", "Art. 150, § 6º da CF/88", "Art. 97 do CTN"], "jurisprudence": ["ADIs supracitadas", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T14:25:04.913287+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=73", "doc_key": "103316afffa4f0653d23fb9f757c7274"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '03e528aa8886448e50a5cf37038f518cba42e4497e26bc1c14dacb09a9a506bd'),
  ('cpiuris2025::b47b1e240b4ce443f54cea219ea9ef16', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios do Direito Tributário', '## Princípios do Direito Tributário

Resumo objetivo: Princípios fundamentais do direito tributário, incluindo a atualização da base de cálculo e a fixação do prazo para recolhimento. Além disso, aborda o princípio da isonomia e sua relação com a capacidade contributiva.

### Conceitos
- **Atualização da base de cálculo**: Recomposição do valor monetário da base de cálculo corroída pela inflação
- **Fixação do prazo para recolhimento**: Regulamentação do tempo em que o crédito tributário deve ser pago
- **Princípio da isonomia**: Garantia de igualdade entre contribuintes que se encontram em situação equivalente
- **Capacidade contributiva**: Condição necessária para a igualdade entre contribuintes, considerando sua capacidade econômica

### Referências legais
- Art. 97, § 2º, do CTN
- Súmula n.º 160, do STJ
- Art. 150, CF/88
- Art. 160, CTN

### Jurisprudência
- RE 172.394/SP
- RE 195.218/MG

### Dicas de prova
- Entenda a atualização da base de cálculo e sua relação com a inflação
- Conheça o princípio da isonomia e como ele se aplica à capacidade contributiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direito Tributário", "legal_refs": ["Art. 97, § 2º, do CTN", "Súmula n.º 160, do STJ", "Art. 150, CF/88", "Art. 160, CTN"], "jurisprudence": ["RE 172.394/SP", "RE 195.218/MG"], "confidence": 0.8, "extracted_at": "2026-05-29T14:26:12.688678+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=75", "doc_key": "b47b1e240b4ce443f54cea219ea9ef16"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b1e1058bfd4a8543a181a59c7f8106fddf706d41e067189c0db32502350481ef'),
  ('cpiuris2025::e4b81d405d802f41cc49b10755e3d27b', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípio da Interpretação Objetiva do Fato Gerador', '## Princípio da Interpretação Objetiva do Fato Gerador

O princípio da interpretação objetiva do fato gerador significa que a definição legal do fato gerador deve ser interpretada de forma abstrata, sem considerar os efeitos dos fatos efetivamente ocorridos ou a validade jurídica dos atos praticados pelos contribuintes.

### Conceitos
- **Princípio da Interpretação Objetiva**: interpretação abstrata da definição legal do fato gerador
- **Fato Gerador**: evento que gera a obrigação tributária
- **Interpretação Abstrata**: interpretação que se afasta dos efeitos dos fatos efetivamente ocorridos

### Referências legais
- Art. 118, CTN

### Dicas de prova
- Entenda a diferença entre interpretação objetiva e subjetiva do fato gerador.
- Aprenda a aplicar o princípio da interpretação objetiva em diferentes situações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direito Tributário", "legal_refs": ["Art. 118, CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:27:04.876476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=75", "doc_key": "e4b81d405d802f41cc49b10755e3d27b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3795f8c8a1b5bb95dd7857e2b32d76ed7d0da7e967942e70ca12d4a519a9e4f0'),
  ('cpiuris2025::f770238c6267a76baa2d5cd87ac1a5ff', 'doutrina', 'cp_iuris', 'Direito Tributário — Previsibilidade no Direito Tributário: irretroatividade e anterioridade', '## Previsibilidade no Direito Tributário: irretroatividade e anterioridade

O princípio da irretroatividade estabelece que a lei não pode retroagir para cobrar tributos de fatos geradores ocorridos antes do início da vigência da lei. A lei posterior não alcança fato passado para gerar uma obrigação de pagar tributo.

### Conceitos
- **Irretroatividade**: Princípio que proíbe a aplicação de leis posteriores a fatos geradores ocorridos antes do início da vigência da lei.
- **Anterioridade**: Regra que estabelece que a lei posterior não pode aumentar ou alterar tributos existentes sem consentimento do contribuinte.

### Referências legais
- Art. 150, III, “a”, da CF/88

### Dicas de prova
- Entenda a diferença entre irretroatividade e anterioridade.
- Conheça as exceções ao princípio da irretroatividade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, III, “a”, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:29:01.201848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=77", "doc_key": "f770238c6267a76baa2d5cd87ac1a5ff"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a7532ebe93dc4bdfbd962c3be800cc613260ae30328028863481154b7c40e5d2'),
  ('cpiuris2025::4b1ad0953ba344a782bf3a3f14e5286b', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios do Direito Tributário e Irretroatividade', '## Princípios do Direito Tributário e Irretroatividade

O texto discute os princípios do direito tributário, incluindo a isonomia, progressividade, proporcionalidade e seletividade. Além disso, aborda a irretroatividade, que proíbe a cobrança de tributos com base em fatos geradores ocorridos antes da vigência da lei que os instituiu.

### Conceitos
- **Isonomia**: igualdade perante a lei
- **Progressividade**: alíquotas variadas com base na base de cálculo
- **Proporcionalidade**: tributação ordinária com bases de cálculo variáveis
- **Seletividade**: tributação inversamente proporcional à base de cálculo e seletividade do tributo
- **Irretroatividade**: proíbe a cobrança de tributos com base em fatos geradores ocorridos antes da vigência da lei que os instituiu

### Referências legais
- Art. 150, III, da CF/88
- Art. 105 do CTN
- Art. 144 do CTN

### Jurisprudência
- STF: viola o princípio da isonomia a isenção de IPTU exclusivamente em decorrência da qualidade de servidor público do contribuinte

### Dicas de prova
- Entenda a diferença entre progressividade e proporcionalidade
- Conheça a regra de irretroatividade prevista na CF/88
- Análise do lançamento reportado pela legislação tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.76", "page_number": 76, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, III, da CF/88", "Art. 105 do CTN", "Art. 144 do CTN"], "jurisprudence": ["STF: viola o princípio da isonomia a isenção de IPTU exclusivamente em decorrência da qualidade de servidor público do contribuinte"], "confidence": 0.8, "extracted_at": "2026-05-29T14:29:13.936824+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=76", "doc_key": "4b1ad0953ba344a782bf3a3f14e5286b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '4f2b034c28dd83b9a848deddb6a40b8f817a432c0e7925425fa0be79eb9a30e6'),
  ('cpiuris2025::cdfa0d8d72238ee784044c214cba74d7', 'doutrina', 'cp_iuris', 'Direito Tributário — Fato Gerador e Lei Contemporânea', '## Fato Gerador e Lei Contemporânea

A obrigação tributária principal de pagar tributo se regula pela lei contemporânea, mesmo que essa lei seja revogada. A multa em caso de infração tributária pode não ser recolhida se a lei nova trazer benefícios.

### Conceitos
- **Fato Gerador**: elemento que gera a obrigação tributária principal
- **Lei Contemporânea**: leis vigentes no momento da ocorrência do fato gerador
- **Obrigação Tributária Principal**: obrigação de pagar tributo, regida pela lei contemporânea
- **Lei Revogada**: leis que não mais são aplicáveis
- **Multa**: sancionamento aplicado em caso de infração tributária

### Referências legais
- Art. 106, I do CTN

### Dicas de prova
- Entenda a diferença entre obrigação tributária principal e multa.
- Conheça o conceito de lei contemporânea e sua aplicação no fato gerador.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direito Tributário", "legal_refs": ["Art. 106, I do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:31:04.012463+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=77", "doc_key": "cdfa0d8d72238ee784044c214cba74d7"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '02a82d55175193a7bc22e71c53580cfea53e312db86950a70d6783e43e2459be'),
  ('cpiuris2025::64228b8927e7ee4e08fdf98d8c8de382', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento de Tributos e Lei Vigente', '## Lançamento de Tributos e Lei Vigente

O lançamento de tributos ocorre com base na lei vigente à época do fato gerador, mas pode ser aplicada a legislação posteriormente instituída, desde que não seja para alterar a hipótese de incidência ou majorar o tributo.

### Conceitos
- **Lançamento de Tributos**: Ocorre com base na lei vigente à época do fato gerador
- **Lei Vigente**: A legislação aplicável à época do fato gerador
- **Decadência**: Prazo para o lançamento do tributo, após o qual a Fazenda pode utilizar a lei vigente ao tempo do fato gerador
- **Revisão da Lei**: A aplicação de legislação posteriormente instituída, desde que não seja para alterar a hipótese de incidência ou majorar o tributo

### Referências legais
- Art. 144, § 1º do CTN
- Art. 173, I do CTN

### Dicas de prova
- Entenda a diferença entre lançamento de tributos e revisão da lei
- Conheça o prazo decadencial para o lançamento do tributo
- Aplique a legislação vigente ao tempo do fato gerador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direito Tributário", "legal_refs": ["Art. 144, § 1º do CTN", "Art. 173, I do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:31:42.837575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=78", "doc_key": "64228b8927e7ee4e08fdf98d8c8de382"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '1537f1b6a80ded6425aed76d607d8184984e6ab6706b8279feadbe34f9790f85'),
  ('cpiuris2025::37da509826d06f4c112f58ae85de0d34', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios do Direito Tributário', '## Princípios do Direito Tributário

O texto discute as exceções ao princípio da legalidade tributária, incluindo a liberdade do Estado para manipular os tributos extrafiscais e a necessidade de lei específica para instituição, revogação ou atualização de tributos.

### Conceitos
- **Princípio da Legalidade**: Requisito de que o tributo seja instituído por meio de lei
- **Exceções ao Princípio da Legalidade**: Hipóteses em que o Estado tem liberdade para agir sem a necessidade de lei específica
- **Tributos Extrafiscais**: Tributos que não são destinados a financiar atividades públicas, mas sim influenciar diretamente o meio econômico
- **Delegabilidade dos Tributos**: A capacidade do Estado de instituir ou alterar os tributos por meio de decreto ou resolução

### Referências legais
- Art. 153, § 1º da CF/88
- Art. 155, § 4º, IV da CF/88
- Art. 177, § 4º, I, ''b'' da CF/88
- Art. 150, § 6º da CF/88
- Art. 97, § 2º do CTN

### Jurisprudência
- Súmula n.º 160 do STJ

### Dicas de prova
- Entenda a noção de delegabilidade dos tributos e suas implicações
- Conheça as exceções ao princípio da legalidade tributária e sua aplicação prática
- Avalie a importância do paralelismo das formas na instituição e revogação de tributos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.74", "page_number": 74, "discipline": "Direito Tributário", "legal_refs": ["Art. 153, § 1º da CF/88", "Art. 155, § 4º, IV da CF/88", "Art. 177, § 4º, I, ''b'' da CF/88", "Art. 150, § 6º da CF/88", "Art. 97, § 2º do CTN"], "jurisprudence": ["Súmula n.º 160 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T14:32:44.437505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=74", "doc_key": "37da509826d06f4c112f58ae85de0d34"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '1e066c68e1833b51a941eb03d0224e086d0b5d70a8ced7d15d46f81c653287ab'),
  ('cpiuris2025::1b2d102596881681103193dfe7c50773', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípio da Anterioridade do Exercício Financeiro', '## Princípio da Anterioridade do Exercício Financeiro

O princípio da anterioridade do exercício financeiro é regra que proíbe a retroatividade das leis tributárias para os fatos geradores da obrigação principal de pagar tributo, exceto para as normas processuais e as obrigações principais de pagar multa tributária.

### Conceitos
- **Princípio da Anterioridade**: Regra que proíbe a retroatividade das leis tributárias para os fatos geradores da obrigação principal de pagar tributo
- **Retroatividade**: A aplicação imediata de uma lei para um fato anteriormente não considerado
- **Normas Processuais**: Leis que podem retroagir para normas processuais
- **Obrigações Principais**: Pagar multa tributária

### Referências legais
- Art. 150, III, “b”, da CF/88

### Dicas de prova
- Entenda a distinção entre a retroatividade das leis tributárias e a aplicação de normas processuais
- Conheça as exceções ao princípio da anterioridade, como a retroatividade em benefício do infrator', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, III, “b”, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:33:29.467406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=78", "doc_key": "1b2d102596881681103193dfe7c50773"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '64516b7884b9d46e2c79f5d40cd2254a598fd9d8f71f300e921b779de230faaf'),
  ('cpiuris2025::a6fc5fe9eb696f75afde7ec7e4df389b', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípio da Anterioridade e Irretroatividade', '## Princípio da Anterioridade e Irretroatividade

O princípio da anterioridade é aplicado a leis que alteram prazos de recolhimento de obrigações tributárias, mas não se aplica a atualizações monetárias ou descontos para pagamento antecipado. Exceções incluem tributos com fundamento na extrafiscalidade e isenções onerosas.

### Conceitos
- **Princípio da Anterioridade**: Aplicação de leis que alteram prazos de recolhimento de obrigações tributárias
- **Irretroatividade**: Lei vigente produz efeitos no tempo, mas não retroage
- **Extrafiscalidade**: Fundamento para tributos com natureza fiscal

### Referências legais
- Art. 97, § 2º, do CTN
- Súmula Vinculante n.º 50

### Jurisprudência
- RE 123456
- Tema repetitivo da Anterioridade e Irretroatividade

### Dicas de prova
- Distinguir entre atualizações monetárias e descontos para pagamento antecipado
- Identificar exceções ao princípio da anterioridade, como tributos com fundamento na extrafiscalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Direito Tributário", "legal_refs": ["Art. 97, § 2º, do CTN", "Súmula Vinculante n.º 50"], "jurisprudence": ["RE 123456", "Tema repetitivo da Anterioridade e Irretroatividade"], "confidence": 0.8, "extracted_at": "2026-05-29T14:34:07.963715+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=79", "doc_key": "a6fc5fe9eb696f75afde7ec7e4df389b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b9ff0c1e22634b1e99e66ccf51443a20a64e4349abb31614502b010069c3ba6b'),
  ('cpiuris2025::930ee368a03eb6f4439d6292b8685b91', 'doutrina', 'cp_iuris', 'Direito Tributário — Isenções Tributárias', '## Isenções Tributárias

As isenções tributárias não são onerosas, pois não exigem cumprimento de obrigação para o Estado. O contribuinte precisa apenas se encaixar nos pressupostos da isenção.

### Conceitos
- **Isenção Tributária**: Exigência de cumprimento de obrigação para o Estado
- **Ônus**: Previsão de uma obrigação para o contribuinte
- **Condição**: Requisito necessário para a isenção

### Referências legais
- Lei 7.713/1988, art. 6º, XIV

### Dicas de prova
- Distinção entre condição e ônus
- Importância de se encaixar nos pressupostos da isenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Direito Tributário", "legal_refs": ["Lei 7.713/1988, art. 6º, XIV"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:34:17.263126+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=79", "doc_key": "930ee368a03eb6f4439d6292b8685b91"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f3db65950fe910707364542ee725118581f2c87f39f899aade2226bba560926c'),
  ('cpiuris2025::90946a7feac82488a0bcc2b7314d5c81', 'doutrina', 'cp_iuris', 'Direito Tributário — Isenções Onerosas', '## Isenções Onerosas

Isenções que exigem do contribuinte esforço, gasto ou preparação. Direito subjetivo após cumprimento dos requisitos.

### Conceitos
- **Isenção Onerosa**: exigência de esforço, gasto ou preparação do contribuinte
- **Direito Subjetivo**: direito do contribuinte após cumprimento dos requisitos
- **Princípio da Não Surpresa**: aplicação do princípio anterioridade clássica e nonagésima em hipóteses de redução ou supressão de benefícios

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 564225 AgR-EDv-AgR
- ...

### Dicas de prova
- Entenda a diferença entre isenção onerosa e não onerosa.
- Conheça o princípio da não surpresa e sua aplicação em hipóteses de redução ou supressão de benefícios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Direito Tributário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 564225 AgR-EDv-AgR", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T14:34:37.451645+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=80", "doc_key": "90946a7feac82488a0bcc2b7314d5c81"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f3496770cd0aa2a2642377496a967b4b262c94d71a7de5a41148b8ba88813583'),
  ('cpiuris2025::18b5d991945b57e906ab3659475d9f11', 'doutrina', 'cp_iuris', 'Direito Tributário — Isenção e Revogação', '## Isenção e Revogação

A isenção é uma dispensa legal do pagamento de um tributo. A revogação da isenção não significa a instituição de um novo tributo, mas sim a exigibilidade imediata do tributo existente.

### Conceitos
- **Isenção**: dispensa legal do pagamento de um tributo
- **Revogação**: atualização da legislação tributária
- **Princípio da Anterioridade**: não se aplica ao tributo existente após a revogação da isenção

### Referências legais
- Art. 6º, XIV da Lei 7.713/1988

### Jurisprudência
- RE 204.062
- Súmula 473 do STF

### Dicas de prova
- Entenda a diferença entre isenção e revogação
- Conheça o princípio da anterioridade e sua aplicabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Direito Tributário", "legal_refs": ["Art. 6º, XIV da Lei 7.713/1988"], "jurisprudence": ["RE 204.062", "Súmula 473 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T14:36:35.422843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=80", "doc_key": "18b5d991945b57e906ab3659475d9f11"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '47e20d95a553e80fd48133ace5c35bd2c4381dd6f3cd974f5547c62e38f527b0'),
  ('cpiuris2025::1c5ede94421106ead9c039c39fe1ef57', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípio da Anterioridade Nonagesimal', '## Princípio da Anterioridade Nonagesimal

O princípio da anterioridade nonagesimal é aplicado à majoração indireta decorrente de revogação de benefícios fiscais, além da majoração direta de tributos.

### Conceitos
- **Princípio da Anterioridade**: Regra que determina que os novos impostos ou taxas devem ser mais baixos do que os antigos
- **Anterioridade Nonagesimal**: Aplicação do princípio da anterioridade a majorações indiretas decorrentes de revogação de benefícios fiscais
- **Benefício Fiscal**: Concessão ou redução de impostos ou taxas por parte do Estado

### Referências legais
- Art. 150, alínea c) da CF/1988

### Jurisprudência
- RE 564225 AgR
- RE 1081041 AgR
- RE 1259379 AgR

### Dicas de prova
- Entenda a aplicação do princípio da anterioridade nonagesimal em casos de revogação de benefícios fiscais
- Conheça a diferença entre majoração direta e indireta de tributos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, alínea c) da CF/1988"], "jurisprudence": ["RE 564225 AgR", "RE 1081041 AgR", "RE 1259379 AgR"], "confidence": 0.8, "extracted_at": "2026-05-29T14:37:16.204422+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=81", "doc_key": "1c5ede94421106ead9c039c39fe1ef57"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '723b95a46990ab7896ec2af9954bb6c5b28ec8c6463ea884704db94d57c056e3'),
  ('cpiuris2025::376ad23a93e7ef1d143e09312b7f4207', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípio da Anterioridade e Nonagesimal', '## Princípio da Anterioridade e Nonagesimal

A revogação de benefício fiscal deve se submeter ao princípio da não surpresa, ou seja, a cobrança do tributo ou a majoração do tributo deve ser feita de acordo com o que já estava previsto na legislação. O STF entende que a revogação de isenção é uma ''majoração indireta'' de tributo.

### Conceitos
- **Princípio da Anterioridade**: O princípio segundo o qual as novas regras tributárias só podem ser aplicadas a partir do momento em que são promulgadas.
- **Princípio da Eficácia Tributária Diferida**: O princípio que estabelece que as novas regras tributárias só podem ser aplicadas a partir do momento em que são promulgadas.
- **Princípio da Não Surpresa**: O princípio segundo o qual a cobrança do tributo ou a majoração do tributo deve ser feita de acordo com o que já estava previsto na legislação.
- **Majoração Indireta de Tributo**: A revogação de isenção ou outro benefício fiscal que reestabelece a cobrança do tributo ou a majoração do tributo, considerada como uma ''majoração indireta'' de tributo.
- **Princípio da Anterioridade Nonagesimal**: O princípio que estabelece que as hipóteses em que a revogação de benefício fiscal acarreta aumento indireto de tributo devem ser consideradas com base nos princípios da anterioridade geral e da noventena.

### Referências legais
- Art. 96, § 3º, da CF/88
- Súmula 856 do STF

### Jurisprudência
- ADI 2.325 MC
- ARE 914.045
- ARE 1339119 AgR

### Dicas de prova
- Entenda o princípio da não surpresa e como ele se relaciona com a revogação de benefícios fiscais.
- Conheça as hipóteses em que a revogação de benefício fiscal acarreta aumento indireto de tributo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Direito Tributário", "legal_refs": ["Art. 96, § 3º, da CF/88", "Súmula 856 do STF"], "jurisprudence": ["ADI 2.325 MC", "ARE 914.045", "ARE 1339119 AgR"], "confidence": 0.8, "extracted_at": "2026-05-29T14:38:44.225076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=81", "doc_key": "376ad23a93e7ef1d143e09312b7f4207"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'cc2b09a8379818e89d2c0ea23af52bc8f5f5d6dc78b545243b635eb310128890'),
  ('cpiuris2025::c1f8e6a7f52d4b90ce87259514b3c447', 'doutrina', 'cp_iuris', 'Direito Tributário — Medidas Provisórias em Matéria Tributária', '## Medidas Provisórias em Matéria Tributária

A Medida Provisória pode instituir ou aumentar impostos, exceto alguns previstos em arts. 153 e 154, apenas se convertida em lei até o último dia do exercício financeiro seguinte.

### Conceitos
- **Medida Provisória**: Decrito pelo Presidente da República com força de lei
- **Instituição ou Aumento de Impostos**: Exceção aos impostos previstos em arts. 153 e 154

### Referências legais
- Art. 62, §2º da CF/88

### Dicas de prova
- Distinção entre Medida Provisória e Lei Ordinária
- Importância do prazo para conversão em lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direito Tributário", "legal_refs": ["Art. 62, §2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:38:44.493038+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=82", "doc_key": "c1f8e6a7f52d4b90ce87259514b3c447"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '153fc8097d413d123177b413415046721a6694b42a2621481e8a1d4f08112019'),
  ('cpiuris2025::87b5701a690e346702a39fd189ac7476', 'doutrina', 'cp_iuris', 'Direito Tributário — Limites suportáveis do tributo', '## Limites suportáveis do tributo

O Estado não pode tributar além de determinado limite, sob pena de sufocar a atividade econômica e inviabilizar a continuidade no pagamento de tributos.

### Conceitos
- **Limite suportável**: Quantidade máxima de tributo que o Estado pode exigir
- **Sufocamento tributário**: Situação em que a tributação excessiva impede a atividade econômica
- **Arrecadação**: Montante total de receita pública

### Referências legais
- Art. 105 da CF/88

### Dicas de prova
- Entenda a noção de limite suportável e como ele se relaciona com a arrecadação
- Diferencie entre sufoamento tributário e redução da arrecadação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Direito Tributário", "legal_refs": ["Art. 105 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:40:23.639002+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=83", "doc_key": "87b5701a690e346702a39fd189ac7476"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '951d70e76ce066aaac8230dd61e1a647bb47db6dd71cad0e495d8b3fee953e26'),
  ('cpiuris2025::75990389f3ad25f53d8f8fbdd43f591a', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios do Direito Tributário', '## Princípios do Direito Tributário

Descreve as regras para a conversão de medidas provisórias em lei e o princípio da vedação ao confisco.

### Conceitos
- **Medida Provisória**: Instrumento legislativo temporário que pode ser convertido em lei.
- **Conversão em Lei**: O processo de transformar uma medida provisória em lei, dentro de um prazo específico.
- **Prazo de Conversão**: Sessenta dias para a conversão de uma medida provisória em lei, com possibilidade de prorrogação.
- **Efeito de Confisco**: Tributo que tem o objetivo de confiscar uma atividade produtiva ou um bem.
- **Princípio da Vedação ao Confisco**: Regra que proíbe tributar abaixo dos valores essenciais à garantia do mínimo existencial e respeitar o limite do efeito confiscatório.

### Referências legais
- Art. 150, III, ''b'' e ''c'', da CF/88
- Art. 62, §§ 3º e 7º, da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre medida provisória e lei.
- Conheça o prazo de conversão e as regras para a sua prorrogação.
- Aprenda a aplicar o princípio da vedação ao confisco em casos práticos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, III, ''b'' e ''c'', da CF/88", "Art. 62, §§ 3º e 7º, da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T14:41:29.632455+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=83", "doc_key": "75990389f3ad25f53d8f8fbdd43f591a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '29ee82a3924b9231ce21b57f5ff5caad646cf3b45dec12b782f10dadcc2e2b72'),
  ('cpiuris2025::3c8f4ada18425fc1ab439294bb9ce4be', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios do Direito Tributário e Exceções à Anterioridade Nonagesimal', '## Princípios do Direito Tributário e Exceções à Anterioridade Nonagesimal

Resumo sobre as exceções ao princípio da anterioridade nonagesimal, incluindo o Imposto de Renda e IPTU/IPVA.

### Conceitos
- **Anterioridade nãoagesimal**: Princípio que determina que os tributos devem ser majorados apenas após a decorridão de um período específico (noventa dias) desde a publicação da lei que os instituiu ou aumentou.
- **Imposto de Renda**: Tributo cujo fato gerador é classificado como periódico e sujeito à anterioridade do exercício financeiro, mas não à anterioridade nonagesimal.
- **IPTU/IPVA**: Tributos que não precisam respeitar o princípio da anterioridade nonagesimal porque o fato gerador ocorre em 1º de janeiro.

### Referências legais
- Art. 150, III, c), CF/88
- Emenda Constiticional n.º 42, de 19 de dezembro de 2003

### Jurisprudência
- Súmula n. 584 do STF

### Dicas de prova
- Entenda a diferença entre anterioridade nonagesimal e anterioridade do exercício financeiro.
- Conheça as exceções ao princípio da anterioridade nonagesimal, como o Imposto de Renda e IPTU/IPVA.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, III, c), CF/88", "Emenda Constiticional n.º 42, de 19 de dezembro de 2003"], "jurisprudence": ["Súmula n. 584 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T14:41:51.842056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=82", "doc_key": "3c8f4ada18425fc1ab439294bb9ce4be"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a6ead775d3c66346eb7ed77ece52e1c3a7e704cd87994d8ab42a61446dc9f15a'),
  ('cpiuris2025::55d466c0f3f0f0f6b2dda2db80b9278b', 'doutrina', 'cp_iuris', 'Direito Tributário — Moderação na imposição tributária e proteção do contribuinte', '## Moderação na imposição tributária e proteção do contribuinte

A cláusula constitucional de vedação ao confisco (art. 150, IV, da CF/88) protege o contribuinte e informa um limite ao Estado, além do qual há inviabilização da atividade produtiva.

### Conceitos
- **Princípios do Direito Tributário**: Regras que regem a tributação
- **Vedação ao confisco**: Proteção do contribuinte e limite para o Estado
- **Não confiscatoriedade**: Princípio que proíbe a absorção total ou excessiva do produto econômico da atividade privada

### Referências legais
- Art. 150, IV, da CF/88

### Jurisprudência
- RE 448.432 AgR
- ...

### Dicas de prova
- Entenda a vedação ao confisco e sua relação com a não confiscatoriedade
- Análise dos princípios do Direito Tributário para resolver questões de tributação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.84 (1)", "page_number": 84, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, IV, da CF/88"], "jurisprudence": ["RE 448.432 AgR", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T14:42:36.189570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=84", "doc_key": "55d466c0f3f0f0f6b2dda2db80b9278b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9de14cf4770e7684125c0be2bce46118c1a8655b6f345f76f9c34bdd7f5686f3'),
  ('cpiuris2025::5d483a6585a28381e45b5c0f6235b389', 'doutrina', 'cp_iuris', 'Direito Tributário — Proibição Constitucional do Confisco em Matéria Tributária', '## Proibição Constitucional do Confisco em Matéria Tributária

A proibição constitucional do confisco em matéria tributária significa que o Estado não pode apropriar-se indevidamente do patrimônio ou dos rendimentos dos contribuintes. A multa fiscal moratória deve ser sancionadora, mas não confiscatória.

### Conceitos
- **Confisco**: Apropriação indevida do patrimônio ou dos rendimentos de um contribuinte pelo Estado.
- **Multa Fiscal Moratória**: Sancionadora, mas não confiscatória, para desencorajar o inadimplemento das obrigações tributárias.
- **Razoabilidade**: Princípio que qualifica como parâmetro de aferição da constitucionalidade material dos atos estatais.

### Referências legais
- Art. 150, IV, da CF

### Jurisprudência
- ADI 1.075 MC
- RE 582.461

### Dicas de prova
- Entenda a distinção entre confiscatória e sancionadora em relação à multa fiscal moratória.
- Aprenda o princípio da razoabilidade como parâmetro de aferição da constitucionalidade dos atos estatais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.84 (2)", "page_number": 84, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, IV, da CF"], "jurisprudence": ["ADI 1.075 MC", "RE 582.461"], "confidence": 0.8, "extracted_at": "2026-05-29T14:44:01.383799+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=84", "doc_key": "5d483a6585a28381e45b5c0f6235b389"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b140fdb6b0057d471c6269d6450b15d618c46963c98eba48f17b138552c271cc'),
  ('cpiuris2025::06d8cc9a5e1f163f43e554b9e50df84a', 'doutrina', 'cp_iuris', 'Direito Tributário — Constitucionalidade da majoração de alíquotas do imposto de importação', '## Constitucionalidade da majoração de alíquotas do imposto de importação

A jurisprudência do STF e do TRF-5 considera a constitucionalidade da majoração de alíquotas do imposto de importação, com base no princípio da vedação de confisco.

### Conceitos
- **Princípio da Não Surpresa**: não pode haver mudança em regras tributárias sem prévia autorização do Congresso Nacional
- **Vedação de Confisco**: proibição de confisco de bens ou direitos por meio de impostos
- **Imposto de Importação**: imposto cobrado sobre a entrada de mercadorias no país

### Referências legais
- Art. 100 da CF/88
- Súmula 646 do STF

### Jurisprudência
- RE 456.123
- Tema repetitivo: majoração de alíquotas do imposto de importação

### Dicas de prova
- Entenda o princípio da não surpresa e sua aplicação aos impostos
- Conheça a vedação de confisco e como ela se aplica ao imposto de importação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 da CF/88", "Súmula 646 do STF"], "jurisprudence": ["RE 456.123", "Tema repetitivo: majoração de alíquotas do imposto de importação"], "confidence": 0.8, "extracted_at": "2026-05-29T14:44:45.573382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=85", "doc_key": "06d8cc9a5e1f163f43e554b9e50df84a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9df0c2bda960762c0ff1c67649646b1bf55ad93baa538c83402722a2eb0ddfbb'),
  ('cpiuris2025::12b8d777769fd4151462fd26804220d0', 'doutrina', 'cp_iuris', 'Direito Tributário — Multa Punitiva e Sanção Tributária', '## Multa Punitiva e Sanção Tributária

A multa punitiva é aplicada em situações de descumprimento voluntário da obrigação tributária, com o objetivo de coibir ilícitos tributários. A Corte entende que a abusividade da multa se revela quando ela excede 100% do valor do tributo.

### Conceitos
- **Multa Punitiva**: Sanção aplicada em situações de descumprimento voluntário da obrigação tributária
- **Sanção Tributária**: Meio utilizado pelo Estado para coibir o incumprimento das obrigações tributárias
- **Abusividade**: Ocorrência quando a multa punitiva excede 100% do valor do tributo
- **Carga Tributária**: Somatório de todos os impostos e contribuições pagas por uma pessoa ou empresa
- **Função Social**: Objetivo da fiscalização tributária, que é garantir a coleta de receitas públicas para atender às necessidades do Estado

### Referências legais
- Art. 153, Parágrafo 1º, da CF/88
- RE 602.686 AgR-segundo

### Jurisprudência
- RE 851.038 AgR
- AI 851.038 AgR

### Dicas de prova
- Entenda a diferença entre multa punitiva e sanção tributária
- Conheça o conceito de abusividade da multa punitiva
- Avalie a importância da carga tributária e sua relação com a função social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Direito Tributário", "legal_refs": ["Art. 153, Parágrafo 1º, da CF/88", "RE 602.686 AgR-segundo"], "jurisprudence": ["RE 851.038 AgR", "AI 851.038 AgR"], "confidence": 0.8, "extracted_at": "2026-05-29T14:44:50.991455+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=85", "doc_key": "12b8d777769fd4151462fd26804220d0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'eb63e265f1a84dfa0e001d8d2b59f26ed85c8e2b16e7ea12ee23f9d5c9073b52'),
  ('cpiuris2025::43239fbca7eebea3186db17f7096b429', 'doutrina', 'cp_iuris', 'Direito Tributário — Extrafiscalidade e Limitações ao Tráfego de Pessoas e Bens', '## Extrafiscalidade e Limitações ao Tráfego de Pessoas e Bens

Os tributos extrafiscais não estão sujeitos à regra do art. 150, IV, da CF/88, pois o confisco é voltado para os tributos fiscais. A utilização de um tributo para efeitos extrafiscais não é confiscatória. Além disso, a proibição do estabelecimento de limitações ao tráfego de pessoas e bens por meio de tributos interestaduais e intermunicipais está prevista no art. 150, inciso V, da CF/88.

### Conceitos
- **Extrafiscalidade**: Natureza predominantemente não tributária
- **Limitações ao tráfego de pessoas e bens**: Proibição de estabelecer limitações ao tráfego por meio de tributos interestaduais ou intermunicipais
- **Tributo confiscatório**: Tributo que tem como objetivo confisca a propriedade ou o consumo

### Referências legais
- Art. 150, IV da CF/88
- Art. 150, V da CF/88
- Art. 155, II da CF/88

### Dicas de prova
- Entenda a diferença entre extrafiscalidade e tributo confiscatório
- Conheça o artigo 150, inciso V, da CF/88
- Aprenda com os exemplos de tributos interestaduais e intermunicipais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.86 (1)", "page_number": 86, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, IV da CF/88", "Art. 150, V da CF/88", "Art. 155, II da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:46:50.640756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=86", "doc_key": "43239fbca7eebea3186db17f7096b429"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '54e6e746df28542af9b48443dbadb1bd6da3918e2385f2daa0bd534a3005190f'),
  ('cpiuris2025::0ce4a7ef4dbe7ff79355567fd964953a', 'doutrina', 'cp_iuris', 'Direito Tributário — Vedação de isenções heterônomas e sua aplicabilidade aos Estados e DF', '## Vedação de isenções heterônomas e sua aplicabilidade aos Estados e DF

A União não pode conceder isenções tributárias aos Estados e Distrito Federal, mas pode celebrar tratados internacionais que veiculem cláusulas de exoneração tributária em matéria de tributos locais.

### Conceitos
- **Vedação de isenções heterônomas**: Proibição da União conceder isenções tributárias aos Estados e Distrito Federal
- **Isenção heterônoma**: Concessão de isenção tributária por meio de tratado internacional ou acordo entre a União e outro Estado
- **Ente federativo tributante**: A União, como ente federativo, não pode conceder isenções tributárias aos Estados e Distrito Federal

### Referências legais
- Art. 151, III da CF/88

### Jurisprudência
- Súmula n.º 178 do STJ
- RE 123456

### Dicas de prova
- Diferenciar a posição da União como ente federativo tributante da que ela assume como representante da República Federativa do Brasil
- Entender a distinção entre isenção heterônoma e vedação de isenções heterônomas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Direito Tributário", "legal_refs": ["Art. 151, III da CF/88"], "jurisprudence": ["Súmula n.º 178 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T14:47:16.696781+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=87", "doc_key": "0ce4a7ef4dbe7ff79355567fd964953a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '4e61df502c1161e55178d005207e44f33dcddc032ea62ef6dd6885f95d339b21'),
  ('cpiuris2025::b69f1097e9d29f58b36c42ebef8f1ab8', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípio da Uniformidade Geográfica e Art. 151 da CF/88', '## Princípio da Uniformidade Geográfica e Art. 151 da CF/88

O artigo 150 da Constituição Federal de 1988 não é uma taxa, mas sim um preço público, o que significa que não está sujeito ao princípio da legalidade estrita. Além disso, o artigo 151 da CF/88 proíbe a instituição de tributos que não sejam uniformes em todo o território nacional e que impliquem distinção ou preferência em relação aos Estados, Distrito Federal ou Municípios.

### Conceitos
- **Princípio da Legalidade Estrita**: Requer a existência de uma fonte legal específica para a instituição de um tributo
- **Taxa**: Um tributo que não é considerado um preço público
- **Preço Público**: Um tributo que é considerado um preço público, o que significa que não está sujeito ao princípio da legalidade estrita
- **Uniformidade Geográfica**: A igualdade dos tributos em todo o território nacional
- **Instituição de Tributos**: O ato de criar um tributo

### Referências legais
- Art. 150 da Constituição Federal de 1988
- STF, ADI 800
- Art. 151 da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre taxa e preço público
- Conheça o princípio da uniformidade geográfica e sua aplicação no art. 151 da CF/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.86 (2)", "page_number": 86, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 da Constituição Federal de 1988", "STF, ADI 800", "Art. 151 da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T14:47:42.581684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=86", "doc_key": "b69f1097e9d29f58b36c42ebef8f1ab8"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6bc2473b550d199bb3b94d190c257885aab989398a59a9880ed222b7655cfac6'),
  ('cpiuris2025::f45dc07a4e75a29056e53b85f24931ae', 'doutrina', 'cp_iuris', 'Direito Tributário — Isenção de tributos estaduais em acordos internacionais', '## Isenção de tributos estaduais em acordos internacionais

A isenção de tributos estaduais prevista em acordos internacionais é recepcionada pela Constituição de 1988, mas há limitações para os Estados e Municípios firmar tratados.

### Conceitos
- **Treaty-making power**: Poder de um Estado para criar tratados
- **Monopólio da soberania**: Direito exclusivo do Estado sobre a soberania
- **Personalidade internacional**: Qualidade de um Estado que lhe confere direitos e deveres internacionais
- **Isenção heterônoma**: Benefício concedido por meio de uma fonte externa ao ordenamento jurídico

### Referências legais
- Art. 52, § 2º da CF
- Art. 98 do CTN
- Art. 151, III da CF

### Jurisprudência
- RE 543.943 AgR
- RE 229.096

### Dicas de prova
- Entenda o conceito de treaty-making power e sua relação com a soberania
- Conheça as limitações dos Estados e Municípios em firmar tratados
- Avalie se a isenção de tributos estaduais é uma vedação direta ou indireta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Direito Tributário", "legal_refs": ["Art. 52, § 2º da CF", "Art. 98 do CTN", "Art. 151, III da CF"], "jurisprudence": ["RE 543.943 AgR", "RE 229.096"], "confidence": 0.8, "extracted_at": "2026-05-29T14:48:40.797858+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=87", "doc_key": "f45dc07a4e75a29056e53b85f24931ae"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '664f171235d56576396ca6a20387ead562803d0361dcf816933c1686227b66d2'),
  ('cpiuris2025::c6b6f33b12b287e62a7d6d216983f36c', 'doutrina', 'cp_iuris', 'Direito Tributário — Diferenças tributárias entre bens e serviços', '## Diferenças tributárias entre bens e serviços

A Constituição proíbe a discriminação tributária de natureza espacial, estabelecendo o mercado único e indiferenciado do ponto de vista tributário. Não é justificável a discriminação em razão da origem ou do destino com base na redução das desigualdades regionais.

### Conceitos
- **Princípio da não cumulatividade**: A União pode instituir impostos que sejam não-cumulativos, compensando-se o que for devido em cada operação com o montante cobrado nas anteriores.
- **Mercado único e indiferenciado**: Reflexo da própria soberania nacional e da unidade política e econômica da República.
- **Diferenças tributárias**: Proíbe a discriminação tributária de natureza espacial, estabelecendo o mercado único e indiferenciado do ponto de vista tributário.
- **Princípio da igualdade**: Não é justificável a discriminação em razão da origem ou do destino com base na redução das desigualdades regionais.
- **Imposto sobre a Propriedade de Veículos Automotores**: É um imposto não cumulativo, compensando-se o que for devido em cada operação com o montante cobrado nas anteriores.
- **Alíquota diferenciada**: Não é admissível a alíquota diferenciada para veículos importados e os de procedência nacional.
- **Precedentes**: Agravo regimental a que se nega provimento, RE n° 367.785/RJ-AgR, Segunda Turma, Relator o Ministro Eros Grau, DJ de 2/6/06
- **ADI 5.472**: Ação Direta de Inconstitucionalidade nº 1.655/AP

### Referências legais
- Art. 150, inciso II, do Diploma Maior
- Art. 153, § 3º, da Constituição Federal
- Art. 154, I, da Constituição Federal

### Jurisprudência
- ADI 5.472
- RE n° 367.785/RJ-AgR
- ...

### Dicas de prova
- Pergunte sobre a não cumulatividade do Imposto sobre a Propriedade de Veículos Automotores.
- Entenda o conceito de mercado único e indiferenciado do ponto de vista tributário.
- Aprenda com os precedentes da Ação Direta de Inconstitucionalidade nº 1.655/AP e RE n° 367.785/RJ-AgR.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, inciso II, do Diploma Maior", "Art. 153, § 3º, da Constituição Federal", "Art. 154, I, da Constituição Federal"], "jurisprudence": ["ADI 5.472", "RE n° 367.785/RJ-AgR", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T14:49:28.596315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=88", "doc_key": "c6b6f33b12b287e62a7d6d216983f36c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '748724084aa89d68e47be981f1c40f68bab3ae04f90f617f7a61e4b1195a8ecf'),
  ('cpiuris2025::715e3e7914d11f93e2bf49ff6e905d2d', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios do Direito Tributário', '## Princípios do Direito Tributário

O Direito Tributário não se importa com a validade dos atos praticados, mas sim com a ocorrência do fato gerador. A renda é renda, independentemente da sua origem.

### Conceitos
- **Fato Gerador**: O evento ou situação que gera a obrigação tributária
- **Renda**: O fato gerador do imposto sobre a renda, independentemente da sua origem
- **Princípio da Responsabilidade Fiscal**: A responsabilidade dos entes políticos em gerenciar eficientemente os recursos públicos

### Referências legais
- Art. 11 da Lei Complementar n.º 101/2000

### Dicas de prova
- Entenda a distinção entre fato gerador e renda
- Lembre-se de que o Direito Tributário não se importa com a validade dos atos praticados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direito Tributário", "legal_refs": ["Art. 11 da Lei Complementar n.º 101/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:51:35.750017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=90", "doc_key": "715e3e7914d11f93e2bf49ff6e905d2d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3b3909523f02dc1470de6b5b49127ede9070a764502830a4b3a57deba5796364'),
  ('cpiuris2025::f7f902d6763a6a4b09d9e6354c3049c9', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos não cumulativos e sua característica de compensação', '## Impostos não cumulativos e sua característica de compensação

Os impostos não cumulativos são aqueles que não podem ser acumulados com outros impostos, sendo compensados em operações de circulação de mercadorias ou prestação de serviços.

### Conceitos
- **Imposto não cumulativo**: imposto que não pode ser acumulado com outros impostos
- **Compensação**: a prática de deduzir o valor do imposto cobrado em um estado pelo valor do imposto cobrado em outro estado
- **Contribuinte de direito**: aquele que tem relação jurídica direta com o ente político tributante
- **Contribuinte de fato**: aquele que sofre a repercussão jurídica ou financeira do tributo
- **Repercussão econômica ou financeira**: a influência que o tributo tem sobre a economia ou finanças de uma pessoa ou empresa
- **Operação de circulação de mercadorias**: o ato de vender um bem para outro estado ou distrito federal
- **Prestação de serviços**: o ato de fornecer um serviço a outra pessoa ou empresa

### Referências legais
- Art. 155 da Constituição Brasileira
- Emenda Constitucional nº 3, de 1993

### Dicas de prova
- Entenda a diferença entre contribuinte de direito e contribuinte de fato
- Aprenda a aplicar a regra da compensação nos impostos não cumulativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Direito Tributário", "legal_refs": ["Art. 155 da Constituição Brasileira", "Emenda Constitucional nº 3, de 1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:52:25.261610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=88", "doc_key": "f7f902d6763a6a4b09d9e6354c3049c9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ad71b0bedda6d8954ca857b9cce5277f0f613d221fca8c11ef687bf92571b309'),
  ('cpiuris2025::651ec7082011b853045eb0398b6323c5', 'doutrina', 'cp_iuris', 'Direito Tributário — Transferências voluntárias de impostos', '## Transferências voluntárias de impostos

A transferência de impostos entre entes públicos é regulamentada pelo artigo 11 do LRF, proibindo a transferência para entes que não cobrem todos os impostos de sua competência.

### Conceitos
- **Art. 11**: Regula as transferências voluntárias de impostos entre entes públicos
- **LRF**: Lei que regula a tributação no Brasil

### Referências legais
- Art. 11, LRF

### Dicas de prova
- Entenda a regra de transferência de impostos entre entes públicos
- Conheça o artigo 11 do LRF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direito Tributário", "legal_refs": ["Art. 11, LRF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:53:06.310271+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=90", "doc_key": "651ec7082011b853045eb0398b6323c5"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '84d0136727f2de5742bf6628dc476bce2438a99f5a268573c56c7cb6251344dd'),
  ('cpiuris2025::97fbae1dd15bc550bb4649e026149a4f', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios do Direito Tributário', '## Princípios do Direito Tributário

O contribuinte deve conhecer com clareza a hipótese de incidência e a base de cálculo para evitar interpretações extensivas ou analogias. O tributo não depende da natureza lícita ou ilícida do fato gerador.

### Conceitos
- **Princípio da Tipicidade Tributária**: A hipótese de incidência e a base de cálculo são definidos de forma taxativa e completa pela lei tributária.
- **Analogia**: Não pode ser utilizada para exigir tributo não previsto em lei.
- **Equidade**: Não pode resultar na dispensa do pagamento de tributo devido.
- **Princípio do Non Olet**: O tributo é devido independentemente da natureza lícita ou ilícida do fato gerador.
- **Interpretação Objetiva**: A definição legal do fato gerador é interpretada abstraindo-se dos efeitos dos fatos efetivamente ocorridos.
- **Hipótese de Incidência**: É o fato da vida que dá origem à obrigação tributária.
- **Base de Cálculo**: O valor que serve como base para a determinação do valor do tributo.
- **Alíquota**: A taxa ou porcentagem aplicada à base de cálculo para determinar o valor do tributo.

### Referências legais
- Art. 108, § 1º, do CTN

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda o princípio da tipicidade tributária e a importância de conhecer a hipótese de incidência.
- Não confunda a analogia com a interpretação extensiva.
- O princípio do non olet é fundamental para entender que o tributo é devido independentemente da natureza lícita ou ilícida do fato gerador.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.89", "page_number": 89, "discipline": "Direito Tributário", "legal_refs": ["Art. 108, § 1º, do CTN"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T14:53:35.244952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=89", "doc_key": "97fbae1dd15bc550bb4649e026149a4f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '316d9d2f9c6b17c3ef68809f65116a1177243947bdb585d2515e1016a3636468'),
  ('cpiuris2025::e70e6b28a14e3e4031810a987c565616', 'doutrina', 'cp_iuris', 'Direito Tributário — Pagamento mensal e aumento de alíquota', '## Pagamento mensal e aumento de alíquota

O pagamento mensal e o aumento de alíquota são exigíveis a partir de fevereiro de 2019 e julho de 2019, respectivamente.

### Conceitos
- **Pagamento mensal**: Prazo para pagamento de impostos ou contribuições
- **Aumento de alíquota**: Mudança na taxa aplicada a uma determinada base

### Referências legais
- Art. 30 da Lei nº 11.196/2006

### Dicas de prova
- Perguntas sobre pagamento mensal e aumento de alíquota geralmente exigem distinção entre diferentes prazos e taxas.
- Verifique se o texto menciona a data exata para esses pagamentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direito Tributário", "legal_refs": ["Art. 30 da Lei nº 11.196/2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:54:40.501573+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=91", "doc_key": "e70e6b28a14e3e4031810a987c565616"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '334daeab4251a8d8ae2f5654e53a1655e6bfb3573a46afe82501611e6209e619'),
  ('cpiuris2025::3a812605088e2bfaeb4cf11e5d745b05', 'doutrina', 'cp_iuris', 'Direito Tributário — Alteração do Prazo de Recolhimento de Obrigação Tributária', '## Alteração do Prazo de Recolhimento de Obrigação Tributária

A questão discute a alteração do prazo de recolhimento de obrigação tributária e se ela está sujeita ao princípio da anterioridade.

### Conceitos
- **Princípio da Anterioridade**: Regra que determina que as leis e atos do Executivo devem ser compatíveis com as leis e atos anteriores.
- **Lei Formal**: Lei que exige a aprovação do Congresso Nacional para ser promulgada.
- **Modificação de Base de Cálculo**: Alteração do valor ou critério utilizado para calcular o imposto.
- **Valor Venal**: Preço de mercado do imóvel no momento da sua aquisição.
- **Índice Oficial de Inflação**: Índice utilizado como base para ajuste dos valores tributários.

### Referências legais
- Art. 96, § 3º do CTN
- Súmula 773/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Alteração de base de cálculo

### Dicas de prova
- Entenda o princípio da anterioridade e sua aplicação às alterações de base de cálculo.
- Diferencie entre lei formal e modificação de base de cálculo.
- Conheça a importância do valor venal e do índice oficial de inflação na fixação dos valores tributários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direito Tributário", "legal_refs": ["Art. 96, § 3º do CTN", "Súmula 773/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Alteração de base de cálculo"], "confidence": 0.8, "extracted_at": "2026-05-29T14:55:21.496251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=91", "doc_key": "3a812605088e2bfaeb4cf11e5d745b05"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b2538d2463193d6227940deb48e20b3260692bbcf36bb47c13b84dca08ca0c1f'),
  ('cpiuris2025::c7f78e5c5037802f2c6bfc6b6510c77a', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios do Direito Tributário', '## Princípios do Direito Tributário

Resumo das principais assertivas sobre os princípios tributários.

### Conceitos
- **Princípio da liberdade de tráfego**: Proíbe a instituição de imposto que viola o direito de livre circulação.
- **Retroatividade in bonam partem**: Permite reduzir tributo ou penalidade por meio de atos infralegais.
- **Princípio da progressividade tributária**: Estabelece alíquotas progressivas para o imposto sobre transmissão de bens imóveis.
- **Princípio da anterioridade tributária**: Veda a cobrança de tributos cujos fatos geradores ocorreram antes do início da vigência da lei que os criou ou aumentou.
- **Princípio do não-confisco**: Vede o emprego da tributação com finalidade extrafiscal.

### Referências legais
- Art. 96 da CF/88
- Súmula 773/TST

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a capacidade contributiva e sua relação com a graduação dos impostos.
- Conheça as limitações ao direito de tributar e a ordem econômica e financeira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.92", "page_number": 92, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da CF/88", "Súmula 773/TST"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T14:56:06.857356+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=92", "doc_key": "c7f78e5c5037802f2c6bfc6b6510c77a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8d5df52b5c1ded9d2869b21799902a94779659e606af80083023527c4a5022e5'),
  ('cpiuris2025::2d3b7ef5e5f65f416f7cf61e720307cc', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios do Direito Tributário', '## Princípios do Direito Tributário

A Constituição Federal estabelece limitações constitucionais ao poder de tributar, incluindo a irretroatividade, imunidade recíproca, capacidade contributiva, legalidade tributária e anterioridade nonagesimal.

### Conceitos
- **Irretroatividade**: Vedação de aplicar anistia a multas tributárias definitivamente constituídas.
- **Imunidade Recíproca**: Proíbe a cobrança de taxas e contribuições uns dos outros e impostos federais dos entes subnacionais.
- **Capacidade Contributiva**: Proíbe a cobrança de tributos não progressivos.
- **Legalidade Tributária**: Proíbe a cobrança de tributos com base em lei que contenha conceitos indeterminados.
- **Anterioridade Nonagesimal**: Vedação de cobrar tributos antes de decorridos noventa dias da data em que haja sido publicada a lei que os instituiu ou majorou.

### Referências legais
- Art. 100, § 4º da Constituição Federal
- Súmula 773 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Tributária e Limitações Constitucionais ao Poder de Tributar

### Dicas de prova
- Entenda a distinção entre irretroatividade e anterioridade nonagesimal.
- Conheça as limitações constitucionais ao poder de tributar, incluindo imunidade recíproca e capacidade contributiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Direito Tributário", "legal_refs": ["Art. 100, § 4º da Constituição Federal", "Súmula 773 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Tributária e Limitações Constitucionais ao Poder de Tributar"], "confidence": 0.8, "extracted_at": "2026-05-29T14:57:46.681530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=93", "doc_key": "2d3b7ef5e5f65f416f7cf61e720307cc"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '147ce4d922424903ba9327ad0bcef192adbba3b48faf4b7ca82821f46471e2e1'),
  ('cpiuris2025::be226557f0d918df9b08a415cad03e5f', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios tributários', '## Princípios tributários

Súmula Vinculante nº 50 do STF estabelece que norma legal que altera o prazo de recolhimento de obrigação tributária não se sujeita ao princípio da anterioridade.

### Conceitos
- **Princípio da Anterioridade**: Regra que obriga a aplicação de uma norma legal retroativamente, desde sua entrada em vigor.
- **Súmula Vinculante**: Decisão do STF que tem força de lei e não pode ser alterada por outra decisão do mesmo tribunal.
- **Norma Legal**: Disposição do código ou lei que regula um determinado assunto.
- **Prazo de Recolhimento**: Período estabelecido para o pagamento de uma obrigação tributária.
- **Obrigação Tributária**: Dever ou responsabilidade de um contribuinte diante do Estado.
- **IPTU**: Imposto sobre o Valor Adicionado, cobrado pelos municípios brasileiros.
- **Índice Oficial de Correção Monetária**: Prazo estabelecido pelo governo para a correção monetária.

### Referências legais
- Art. 109 da CF
- Súmula Vinculante nº 50 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo Súmula Vinculante

### Dicas de prova
- Entenda a aplicação do princípio da anterioridade e sua relação com as normas legais.
- Conheça as súmulas vinculantes do STF e suas implicações no direito tributário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Direito Tributário", "legal_refs": ["Art. 109 da CF", "Súmula Vinculante nº 50 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Súmula Vinculante"], "confidence": 0.8, "extracted_at": "2026-05-29T14:58:18.935957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=93", "doc_key": "be226557f0d918df9b08a415cad03e5f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3f0238e318b5a3fe4da2f28e5dc5084733c14d0858d82683b4f7ac69924471e1'),
  ('cpiuris2025::7292bdca5a6f46c303c5bad989e1d782', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais e Garantia da Seguridade Social', '## Contribuições Sociais e Garantia da Seguridade Social

A Constituição Federal de 1988 estabelece regras para a instituição de contribuições sociais e garantir a seguridade social, com prazos específicos para a instituição de novas fontes de financiamento.

### Conceitos
- **Contribuições Sociais**: São tributos obrigatórios destinados a financiar serviços públicos e garantir a seguridade social.
- **Garantia da Seguridade Social**: É o direito do contribuinte de ser protegido por um sistema de previdência social que lhe assegura uma renda mínima em caso de desemprego, doença ou morte.
- **Lei Complementar**: É uma lei que complementa a Constituição Federal e tem como objetivo específico regulamentar um assunto não previsto na Constituição.
- **Imposto de Transmissão Inter Vivos de Bens Imóveis (ITBI)**: É um imposto cobrado sobre a transmissão de bens imóveis, calculado com base no valor venal do imóvel.
- **Súmula n.º 656 do STF**: Declara inconstitucional a lei que estabelece alíquotas progressivas para o ITBI com base no valor venal do imóvel.

### Referências legais
- Art. 148 da CF/88
- Art. 150 da CF/88
- Art. 154 da CF/88
- Art. 195 da CF/88

### Jurisprudência
- Súmula n.º 656 do STF

### Dicas de prova
- Entenda a diferença entre contribuições sociais e impostos.
- Conheça as regras para a instituição de novas fontes de financiamento da seguridade social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Direito Tributário", "legal_refs": ["Art. 148 da CF/88", "Art. 150 da CF/88", "Art. 154 da CF/88", "Art. 195 da CF/88"], "jurisprudence": ["Súmula n.º 656 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T14:59:19.248547+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=94", "doc_key": "7292bdca5a6f46c303c5bad989e1d782"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2ce699a5fffa5eb40005fc078a0b446f235e6535147325999c05bd8857e9d3ef'),
  ('cpiuris2025::457bf5c1e32ed4261253e17211a784ad', 'doutrina', 'cp_iuris', 'Direito Tributário — Anterioridade Tributária', '## Anterioridade Tributária

A anterioridade tributária não se aplica a situações de favorecimento ao contribuinte, mas sim à criação ou aumento de tributos.

### Conceitos
- **anterioridade tributária**: direito que permite a aplicação de impostos sobre benefícios anteriores
- **criação ou incremento de tributos**: situações em que os tributos são criados ou aumentados
- **favorecimento ao contribuinte**: situações em que o contribuinte é beneficiado com a criação ou aumento de tributos

### Referências legais
- Art. 150, VI, c) da CF/88

### Dicas de prova
- Entenda a diferença entre anterioridade tributária e favorecimento ao contribuinte.
- Leia atentamente o artigo 150 da Constituição Federal de 1988', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, c) da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T14:59:35.285857+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=94", "doc_key": "457bf5c1e32ed4261253e17211a784ad"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b0f6f7840e614632ee83981b53faa26c80470fb5fd70b385377e4b02df412fd2'),
  ('cpiuris2025::00427ce931dec776b8a8ffa3f3fbdbad', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios do Direito Tributário', '## Princípios do Direito Tributário

Resumo do artigo: Discute os princípios do direito tributário, incluindo a isonomia tributária e a capacidade econômica do contribuinte.

### Conceitos
- **Isonomia Tributária**: Princípio que estabelece a igualdade material entre os contribuintes
- **Capacidade Econômica**: Característica do contribuinte que determina sua capacidade de pagar impostos

### Referências legais
- Art. 150, II da CF/88
- Art. 145, § 1º da CF/88
- Art. 170, IX da CF/88

### Dicas de prova
- Entenda a isonomia tributária e sua aplicação prática
- Identifique a capacidade econômica do contribuinte e seu impacto na tributação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, II da CF/88", "Art. 145, § 1º da CF/88", "Art. 170, IX da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:00:14.751762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=95", "doc_key": "00427ce931dec776b8a8ffa3f3fbdbad"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8f636ea41d27c1e3b763df04dbc19937b87d606d2f5a2ae698ffeb17e2d63c25'),
  ('cpiuris2025::af1a753ff8de38f4985a6820d84b59bf', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios do Direito Tributário', '## Princípios do Direito Tributário

A Constituição não permite o confisco sem desapropriação, mas há vedação constitucional para exigir ou aumentar tributos sem lei que os estabeleça.

### Conceitos
- **Desapropriação**: Sancionamento do descumprimento da função social do imóvel urbano
- **Confisco**: Violação ao princípio do não confisco
- **Competência Tributária**: Capacidade tributária delegável
- **Competência Tributária**: Diferente da capacidade tributária, é direito do Estado
- **Multa**: Superação de 100% do valor do tributo devido

### Referências legais
- Art. 150 da CF/88
- STF. 1ª Turma. RE 833.106/GO

### Jurisprudência
- RE 833.106/GO

### Dicas de prova
- Diferença entre competência tributária e capacidade tributária
- Exceções ao princípio de não confisco', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.96", "page_number": 96, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 da CF/88", "STF. 1ª Turma. RE 833.106/GO"], "jurisprudence": ["RE 833.106/GO"], "confidence": 0.8, "extracted_at": "2026-05-29T15:01:41.435259+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=96", "doc_key": "af1a753ff8de38f4985a6820d84b59bf"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'abf963561ce46d26221c54a61ba9a4dfbefb883a9b7332d896844629dab93006'),
  ('cpiuris2025::fbf595a9bd5e5d95e6213d0d4ac847b6', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípio da Anterioridade e Irretroatividade', '## Princípio da Anterioridade e Irretroatividade

O princípio da anterioridade da lei tributária é explícito na CF/88 (art. 150, III, ''a''). Além disso, a assertiva trata do princípio da irretroatividade.

### Conceitos
- **Princípio da Anterioridade**: Regra que proíbe a cobrança de tributos após a entrada em vigor de uma lei que os aumentou ou alterou.
- **Irretroatividade**: Princípio que impede a retroaplicação de leis tributárias ao passado, sem consentimento do contribuinte.
- **Princípio do Não Confisco**: Garantia constitucional que proíbe a cobrança de tributos sem justa causa ou sem consentimento do contribuinte.
- **Lei Tributária**: Leis que estabelecem os impostos e as taxas, bem como as regras para sua aplicação.

### Referências legais
- Art. 150 da CF/88

### Dicas de prova
- Entenda o princípio da anterioridade e sua relação com a irretroatividade.
- Identifique a garantia constitucional do não confisco e como ela se aplica à tributação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:01:53.867947+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=95", "doc_key": "fbf595a9bd5e5d95e6213d0d4ac847b6"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'bb8f39661f4994ba2b50897c757e5b4e4afd369246c443319efef13a44409aef'),
  ('cpiuris2025::605b07ade7153514b3847f7c7a3d55c0', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é um apreço constitucional que protege o exercício da competência tributária, representando um valor constitucional. É uma regra constitucional que proíbe a tributação de determinadas pessoas, operações ou objetos.

### Conceitos
- **Imunidade Tributária**: Aproço constitucional que protege o exercício da competência tributária
- **Competência Tributária**: O direito do Estado de exigir impostos e taxas
- **Valor Constitucional**: Um valor protegido pela Constituição Federal

### Referências legais
- Art. 150 da CF/88
- Art. 5º, inciso LXXIV da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Imunidade Tributária

### Dicas de prova
- Entenda a diferença entre imunidade e isenção
- Conheça as outras imunidades previstas na Constituição Federal além do art. 150, inciso VI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.98", "page_number": 98, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 da CF/88", "Art. 5º, inciso LXXIV da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Imunidade Tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T15:02:11.673551+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=98", "doc_key": "605b07ade7153514b3847f7c7a3d55c0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b08f693c190d99603055a82274db1f9c0b08b663a257045e8c52543381003f6f'),
  ('cpiuris2025::a309c91a4aa313e95c0755e50a1a43a6', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é uma norma que estabelece uma determinação de não fazer, ou uma norma de incompetência, estabelecida pelo mesmo texto constitucional que dá a ordem de tributação. A fonte é a Constituição Federal.

### Conceitos
- **Imunidade Tributária**: Norma que estabelece uma determinação de não fazer, ou uma norma de incompetência
- **Competência Tributária**: Poder do Estado para tributar
- **Fonte Normativa**: Constituição Federal

### Referências legais
- Art. 184 da CF
- Art. 195 da CF

### Dicas de prova
- Entenda a distinção entre imunidade, isenção, alíquota zero e não incidência
- Conheça a fonte normativa da imunidade tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Direito Tributário", "legal_refs": ["Art. 184 da CF", "Art. 195 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:02:34.816338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=99", "doc_key": "a309c91a4aa313e95c0755e50a1a43a6"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c51638de511807e5107493c294a6dcd482ef38fb039fa3f4b2a4e6736d1142dd'),
  ('cpiuris2025::2933950dd3013b19310c12eeebf108ad', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária', '## Competência Tributária

A competência tributária é a medida da tributação, resultante da competência aberta aos entes tributantes, subtraídas as imunidades. A outorga da competência para tributar não é um mandamento ''cego'', e os entes tributantes devem aferir a capacidade contributiva antes de criar um tributo.

### Conceitos
- **Competência Tributária**: A medida da tributação resultante da competência aberta aos entes tributantes
- **Imunidades**: Subtrações da competência tributária
- **Capacidade Contributiva**: Aferição necessária antes de criar um tributo

### Referências legais
- Art. 145, I, da CF/88
- Art. 153, III, da CF/88

### Dicas de prova
- Entenda a distinção entre competência tributária e imunidades.
- Aferir a capacidade contributiva é obrigatório antes de criar um tributo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Direito Tributário", "legal_refs": ["Art. 145, I, da CF/88", "Art. 153, III, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:04:42.811203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=99", "doc_key": "2933950dd3013b19310c12eeebf108ad"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9d28947cdc567574f36d8f3d59e836fb5785d10c8df8d73db7884d2e84b01173'),
  ('cpiuris2025::77c0c424b5e5cd1029147a0171607695', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária Recíproca', '## Imunidade Tributária Recíproca

A Constituição Federal estabelece uma imunidade tributária recíproca, proibindo a União de tributar a renda dos demais entes federativos. A competência para tributar é recebida em sua exata medida, mas apenas sobre a renda e proventos que representam capacidade contributiva.

### Conceitos
- **Imunidade Tributária Recíproca**: Proibição da União de tributar a renda dos demais entes federativos
- **Competência Tributária**: Recebimento da competência para tributar em sua exata medida
- **Renda Tributável**: Renda que representa a capacidade efetiva de contribuir
- **Capacidade Contributiva**: Exame da capacidade do ente tributante para tributar

### Referências legais
- Art. 150, VI, “a” da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre renda e renda tributável
- Conheça a competência tributária e sua relação com a imunidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, “a” da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T15:04:59.048531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=100", "doc_key": "77c0c424b5e5cd1029147a0171607695"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2ad738e914a01dde6854de032b75038547c48bb9f28ad42af02e2a79aa5705be'),
  ('cpiuris2025::0ae072c6b7a7239157c6438090cc565f', 'doutrina', 'cp_iuris', 'Direito Tributário — Isonência e Exclusão do Crédito Tributário', '## Isonência e Exclusão do Crédito Tributário

A isenção é a dispensa legal de um tributo devido, sendo causa de exclusão do crédito tributário. A isenção exige lei específica para sua instituição, diferente da imunidade que pode ser determinada genéricamente.

### Conceitos
- **Isonência**: Dispensa legal de um tributo devido
- **Exclusão do Crédito Tributário**: Causa de exclusão do crédito tributário, prevista no CTN (Código Tributário Nacional)
- **Imunidade**: Determinação genérica para a instituição do tributo
- **Lei Específica**: Requisito para a instituição da isenção
- **Crédito Tributário**: Direito do contribuinte de não pagar um tributo
- **Obrigação Acessória**: Obrigação que depende da obrigação principal

### Referências legais
- Art. 175 do CTN

### Dicas de prova
- Entenda a distinção entre isenção e imunidade
- Conheça o requisito de lei específica para a instituição da isenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.100 (2)", "page_number": 100, "discipline": "Direito Tributário", "legal_refs": ["Art. 175 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:05:08.110994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=100", "doc_key": "0ae072c6b7a7239157c6438090cc565f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a49dd8bc6b623fdd0a8fa6a43874daa856e322c2fe1c3c875327a91b8eec4bde'),
  ('cpiuris2025::2759b549864e482fd68b626de180b5b1', 'doutrina', 'cp_iuris', 'Direito Tributário — Diferenciação entre imunidade e isenção', '## Diferenciação entre imunidade e isenção

A imunidade é direito do contribuinte que decorre diretamente do texto constitucional, enquanto a isenção é benefício fiscal concedido pelo legislador ordinário. A não incidência é a constatação de que um fato da vida não se amolda ao tipo tributário.

### Conceitos
- **Imunidade**: Direito do contribuinte decorrente diretamente do texto constitucional
- **Isenção**: Benefício fiscal concedido pelo legislador ordinário
- **Não incidência**: Constatação de que um fato da vida não se amolda ao tipo tributário

### Referências legais
- Art. 156, III, da CF/88

### Jurisprudência
- RE 763/2014

### Dicas de prova
- Distinguir entre imunidade e isenção
- Entender a não incidência como constatação de incompatibilidade do fato com o tipo tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Direito Tributário", "legal_refs": ["Art. 156, III, da CF/88"], "jurisprudence": ["RE 763/2014"], "confidence": 0.8, "extracted_at": "2026-05-29T15:06:57.063466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=101", "doc_key": "2759b549864e482fd68b626de180b5b1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f9c5bb3dd9453d7f95d9be4575530c408c8f1e125e5d4194cfce6dd7718da863'),
  ('cpiuris2025::8c90f3c851c8979a84d74242492aea85', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é um direito do contribuinte que lhe impede a incidência de impostos, taxas e contribuições sobre certas operações ou situações. A lei específica é necessária para instituir uma isenção tributária.

### Conceitos
- **Imunidade Tributária**: Direito do contribuinte que lhe impede a incidência de impostos, taxas e contribuições sobre certas operações ou situações.
- **Isenção Tributária**: Instituição de uma redução ou exclusão parcial do valor do tributo, geralmente mediante lei específica.
- **Lei Específica**: Lei que regula exclusivamente uma determinada matéria ou tributo, sem prejuízo do disposto em outro artigo.

### Referências legais
- Art. 150, § 6º, da CF

### Jurisprudência
- ADI 4.976
- RE 773992/BA
- Repercussão Geral

### Dicas de prova
- Entenda a diferença entre imunidade e isenção tributárias.
- Conheça o conceito de lei específica e sua importância para a instituição de uma isenção tributária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, § 6º, da CF"], "jurisprudence": ["ADI 4.976", "RE 773992/BA", "Repercussão Geral"], "confidence": 0.8, "extracted_at": "2026-05-29T15:07:19.563073+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=101", "doc_key": "8c90f3c851c8979a84d74242492aea85"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6bef3b48bdd6f1ca0883786dffabe86c3956495fcd8b4cee7e9641cdbeef2a9a'),
  ('cpiuris2025::0cc75635b97ff7ac08e2365d3dea1644', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária e Incidência do Imposto de Renda', '## Imunidade Tributária e Incidência do Imposto de Renda

O artigo discute a imunidade tributária e a incidência do imposto de renda, destacando que a não incidência é um fato estranho à incidência tributária e que a isenção dispensa legalmente o pagamento de um tributo.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que afirma que um tributo não pode ser cobrado em determinadas situações.
- **Incidência do Imposto de Renda**: O acréscimo patrimonial que gera a base de cálculo do imposto de renda.
- **Não Incidência**: Fato estranho à incidência tributária, em que o tributo não é devido independentemente de imunidade ou isenção.
- **Isenção**: Dispensa legalmente o pagamento de um tributo.
- **Norma e Fato**: Exame da subsunção normativa entre a norma (hipótese de incidência do imposto de renda) e o fato (recebimento de auxílio condução).
- **Acréscimo Patrimonial**: Criação de riqueza nova que gera a base de cálculo do imposto de renda.
- **Renda**: Obtenção de renda ou proventos de qualquer natureza.

### Referências legais
- Art. 100 da Lei nº 5.172/1970
- Súmula 646 do STF

### Jurisprudência
- REsp 1096288/RS
- REsp 1152764/CE

### Dicas de prova
- Entenda a distinção entre imunidade tributária e não incidência.
- Conheça o conceito de acréscimo patrimonial e sua relação com a incidência do imposto de renda.
- Aprenda a aplicar a norma e fato no contexto da incidência do imposto de renda.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 da Lei nº 5.172/1970", "Súmula 646 do STF"], "jurisprudence": ["REsp 1096288/RS", "REsp 1152764/CE"], "confidence": 0.8, "extracted_at": "2026-05-29T15:08:35.735562+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=102", "doc_key": "0cc75635b97ff7ac08e2365d3dea1644"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '44670e381d5e2952ed55236876fbc27b8924a74623f00b43422f345f04d71e72'),
  ('cpiuris2025::f7363975066a867595d2f513899e654a', 'doutrina', 'cp_iuris', 'Direito Tributário — Não incidência tributária', '## Não incidência tributária

O Judiciário não dispensou o pagamento de um tributo devido, pois a Constituição Federal e a lei não prevêem imunidades ou isenção para o caso. A não incidência é o confronto negativo entre fato e norma quando o fato não se amolda à norma.

### Conceitos
- **Subsunção Normativa**: O princípio que determina a aplicação automática de uma lei sobre um fato
- **Tipicidade Penal**: A relação entre o fato e a norma penal para configurar um crime
- **Alíquota Zero**: O valor zero da alíquota do imposto de renda

### Referências legais
- Art. 100 da CF/88
- ...

### Jurisprudência
- RE 123456
- Súmula 343 STF

### Dicas de prova
- Entenda a diferença entre subsunção normativa e tipicidade penal
- Conheça o conceito de alíquota zero', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 da CF/88", "..."], "jurisprudence": ["RE 123456", "Súmula 343 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T15:08:53.834884+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=102", "doc_key": "f7363975066a867595d2f513899e654a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd034084cf588ff65fb33c454d2da25cab5dcea97c24c9a0f76fba16280dbde05'),
  ('cpiuris2025::7032df58946670a45338e0dde11cc1e3', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária e Benefícios Fiscais', '## Imunidade Tributária e Benefícios Fiscais

A isenção e a alíquota zero são benefícios fiscais que causam uma redução na incidência tributária, com a possibilidade de normalização da tributação. A Constituição Federal preveu diretamente uma situação de alíquota zero em 2023.

### Conceitos
- **Isenção**: Benefício fiscal que suprime uma parte da incidência normativa do tributo
- **Alíquota Zero**: Benefício fiscal que causa um resultado de valor zero a ser pago de tributo
- **Benefício Fiscal**: Ação ou medida tomada pelo Estado para reduzir o valor do tributo
- **Incidência Tributária**: O processo pelo qual o tributo é aplicado ao fato ou à pessoa jurídica

### Referências legais
- Art. 149-C da EC 132/2023

### Dicas de prova
- Entenda a diferença entre isenção e alíquota zero
- Conheça a previsão constitucional de alíquota zero em 2023
- Avalie a incidência tributária na situação de alíquota zero', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Direito Tributário", "legal_refs": ["Art. 149-C da EC 132/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:09:49.261148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=103", "doc_key": "7032df58946670a45338e0dde11cc1e3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '13552cc38f2e57177fa1f1a809747d3e6913787989c87d2bd850547a3fbc21b9'),
  ('cpiuris2025::952806b916025c99a62e3be1b7384f49', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidades e Exigibilidade de Tributos', '## Imunidades e Exigibilidade de Tributos

Regra sobre hipóteses em que não se aplica o disposto no caput e no § 1º da Lei Complementar, especialmente relacionada a aquisições internas da Administração Pública.

### Conceitos
- **Imunidades genéricas**: Leve em consideração todos os aspectos dos entes imunes
- **Art. 150, VI, ''a''**: Regra que define as imunidades genéricas

### Referências legais
- Art. 150, VI, ''a'' da CF/88

### Dicas de prova
- Entenda a diferença entre a administração pública e os demais entes tributantes
- Conheça as hipóteses em que não se aplica o disposto no caput e no § 1º da Lei Complementar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, ''a'' da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:10:29.095458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=103", "doc_key": "952806b916025c99a62e3be1b7384f49"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0dc3221daa61bdb3cc3ddd60cd9938189d3394890ed6c31ff61803f68ee30420'),
  ('cpiuris2025::9de536d52af089e2cea12b3b6a177d52', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidades Tributárias', '## Imunidades Tributárias

A imunidade tributária é um direito assegurado ao contribuinte que lhe impede a incidência de impostos sobre certas atividades ou bens, garantido pela Constituição Federal.

### Conceitos
- **Imunidade Tributária**: Direito do contribuinte que o protege contra a incidência de impostos
- **Autonomia Política**: Direito dos entes federativos de manter sua soberania e não ser subjugado por outro ente político
- **Pacto Federativo**: Acordo entre os estados brasileiros que estabelece a federação como forma de governo

### Referências legais
- Art. 150, VI da CF/88
- Art. 153, § 4º, I da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo sobre imunidades tributárias

### Dicas de prova
- Entenda a autonomia política dos entes federativos e como ela se relaciona com as imunidades tributárias
- Conheça os diferentes tipos de imunidade tributária (subjetiva, objetiva e recíproca)
- Avalie a importância do pacto federativo na garantia das imunidades tributárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.104", "page_number": 104, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI da CF/88", "Art. 153, § 4º, I da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre imunidades tributárias"], "confidence": 0.8, "extracted_at": "2026-05-29T15:11:19.228376+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=104", "doc_key": "9de536d52af089e2cea12b3b6a177d52"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '24d3424a308e832026c47e9a8d8af75b82be42babe13ea74deaf46ddcfada686'),
  ('cpiuris2025::8cc1dd06c3050ddc22f69c6d1be3620a', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Recíproca e Empresas Públicas', '## Imunidade Recíproca e Empresas Públicas

A imunidade recíproca prevalece em empresas públicas e sociedades de economia mista que prestam serviço público, como as empresas estatais. O STF estende essa imunidade às empresas públicas e sociedades de economia mista quando forem prestadoras de serviço público.

### Conceitos
- **Imunidade Recíproca**: prevalece em empresas públicas e sociedades de economia mista que prestam serviço público
- **Empresa Pública**: presta serviço público por determinação constitucional
- **Sociedade de Economia Mista**: composto por partes privadas e públicas
- **Serviço Público**: prestado por empresa pública ou sociedade de economia mista

### Referências legais
- Art. 96 da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre serviços essenciais e não essenciais
- Entendimento do conceito de serviço público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T15:12:26.978655+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=105", "doc_key": "8cc1dd06c3050ddc22f69c6d1be3620a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9577c27045719bef7963f20362bdc03c66eb295fdf05fffc4cbca8a11cc3acd2'),
  ('cpiuris2025::4dccb2273495dc1ee4f37d957ad9e5f3', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é restrita à União, aos Estados, ao Distrito Federal e aos Municípios, exceto em casos específicos, como a exploração de atividades econômicas regidas por normas aplicáveis a empreendimentos privados.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que afirma que certos entes públicos não são sujeitos à tributação.
- **Ente Público**: Organização do Estado que exerce atividades de interesse público.
- **Patrimônio**: Bens e direitos que compõem o patrimônio de uma entidade pública.
- **Renda**: Fonte de receita de uma entidade pública.
- **Serviços**: Atividades realizadas por uma entidade pública em benefício do público.
- **Exploração de Atividades Econômicas**: Realização de atividades econômicas reguladas por normas aplicáveis a empreendimentos privados.
- **Contraprestação**: Pagamento de preços ou tarifas pelo usuário em relação à exploração de atividades econômicas.
- **Imposto**: Contribuição pública destinada a financiar o poder público.

### Referências legais
- Art. 150 da CF/88
- Art. 130 do CTN

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a noção de imunidade tributária e seus limites.
- Conheça as regras para determinar se uma entidade pública é ou não sujeita à tributação.
- Aprenda a distinguir entre exploração de atividades econômicas regidas por normas aplicáveis a empreendimentos privados e outras atividades.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.105 (1)", "page_number": 105, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 da CF/88", "Art. 130 do CTN"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T15:13:14.121657+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=105", "doc_key": "4dccb2273495dc1ee4f37d957ad9e5f3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'dbd1c3f7ce7de60961f11f4a2788550f7cbb4e6512c69859f914d9309f43cde1'),
  ('cpiuris2025::f8b213b57ec4718396ccd6cbc3e27793', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária Recíproca', '## Imunidade Tributária Recíproca

A imunidade tributária recíproca beneficia sociedades de economia mista que prestam serviços públicos estatais essenciais e exclusivos, como o serviço de saneamento básico. A jurisprudência do STF entende que a sociedade de economia mista prestadora de serviço público de água e esgoto é abrangida pela imunidade tributária recíproca.

### Conceitos
- **Imunidade Tributária Recíproca**: Benefício concedido a sociedades de economia mista que prestam serviços públicos estatais essenciais e exclusivos
- **Sociedade de Economia Mista**: Entidade que combina elementos do público e do privado, com objetivo de prestar serviços públicos estatais
- **Serviço Público Estatal**: Atividade exercida pelo Estado para atender às necessidades da população
- **Imunidade Tributária**: Conceito jurídico que afirma que certas atividades ou entidades não estão sujeitas à tributação

### Referências legais
- Art. 150, VI, a da CF

### Jurisprudência
- RE 631.309 AgR
- RE 580.264
- Informativo 914-STF (13/09/2018)

### Dicas de prova
- Entenda a noção de imunidade tributária recíproca e suas implicações para as sociedades de economia mista
- Conheça os requisitos para que uma empresa seja considerada como uma sociedade de economia mista
- Aprenda a distinguir entre serviço público estatal e serviço público delegado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, a da CF"], "jurisprudence": ["RE 631.309 AgR", "RE 580.264", "Informativo 914-STF (13/09/2018)"], "confidence": 0.8, "extracted_at": "2026-05-29T15:14:24.891236+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=106", "doc_key": "f8b213b57ec4718396ccd6cbc3e27793"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9e025f2b9161978aba0eb036e95f29c1e66067af50fff6458a244ab767c7110b'),
  ('cpiuris2025::2d066b79a547ff5fc94b46f09bacb559', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Recíproca e Empresa Pública', '## Imunidade Recíproca e Empresa Pública

A imunidade recíproca prevista no artigo 150, VI, a, da Constituição alcança o IPTU que incidiria sobre os imóveis de propriedade da empresa pública e por ela utilizados. A empresa pública é considerada prestadora de serviços públicos de prestação obrigatória e exclusiva do Estado.

### Conceitos
- **Imunidade Recíproca**: Previsão no artigo 150, VI, a, da Constituição
- **Empresa Pública**: Prestadora de serviços públicos de prestação obrigatória e exclusiva do Estado
- **IPTU**: Imposto sobre os imóveis
- **Imunidade Tributária**: Exceção à incidência do imposto

### Referências legais
- Art. 150, VI, a, da CF

### Jurisprudência
- RE 405267/MG
- RE 773.992

### Dicas de prova
- Distinção entre serviços públicos e atividades econômicas
- Importância da imunidade recíproca para a empresa pública
- Consequências do afastamento da imunidade tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, a, da CF"], "jurisprudence": ["RE 405267/MG", "RE 773.992"], "confidence": 0.8, "extracted_at": "2026-05-29T15:14:49.678293+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=106", "doc_key": "2d066b79a547ff5fc94b46f09bacb559"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b04b99049224b7764a7c9fb0933762459d3e695aa5f38ebba01a6ab4af233613'),
  ('cpiuris2025::9c0c63564aed1e9a1847cc71dbf9e35a', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária Recíproca', '## Imunidade Tributária Recíproca

A questão suscitada neste recurso versa sobre a possibilidade de extensão da imunidade tributária recíproca à Empresa Brasileira de Infraestrutura Aeroportuária (INFRAERO), na qualidade de empresa pública prestadora de serviço público.

### Conceitos
- **Imunidade Tributária Recíproca**: direito que permite a empresa pública não ser tributada por atividades exercidas em regime de exclusividade ou concorrência com a iniciativa privada
- **Empresa Pública Prestadora de Serviço Público**: entidade estatal que exerce atividade essencial à segurança, saúde e bem-estar da população
- **Regime Constitucional de Monopólio**: regra constitucional que permite a União Federal exercer monopólio em determinada atividade

### Referências legais
- Art. 150, VI, a, da CF

### Jurisprudência
- RE 627.051
- RE 601.392
- ARE 638.315 RG

### Dicas de prova
- Distinção entre empresa pública e iniciativa privada
- Relevância da estatalidade do serviço público para a imunidade tributária recíproca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, a, da CF"], "jurisprudence": ["RE 627.051", "RE 601.392", "ARE 638.315 RG"], "confidence": 0.8, "extracted_at": "2026-05-29T15:15:23.672386+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=107", "doc_key": "9c0c63564aed1e9a1847cc71dbf9e35a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '512c8798b9068c2d74f186db35f4549b97ec5b48d4f6bcb46836635ab2528ea3'),
  ('cpiuris2025::cba6e35a027b133cb4b01f5621155fd0', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Recíproca e ICMS', '## Imunidade Recíproca e ICMS

A empresa pública tem direito à imunidade tributária recíproca, que não se aplica às autarquias e fundações do poder público, nem à empresa pública prestadora de serviço postal.

### Conceitos
- **Imunidade Recíproca**: Direito da empresa pública ao isenção de impostos
- **Contribuinte de Direito**: Pessoa que circula a mercadoria, fazendo nascer o fato gerador e incorrendo na hipótese de incidência
- **Contribuinte de Fato**: Pessoa que consome a mercadoria, incorrendo na hipótese de incidência do ICMS
- **Relação Jurídica Tributária**: Travada entre o Estado e o contribuinte de direito

### Referências legais
- Art. 150, VI, a da CF/88
- RE 610.517 AgR

### Jurisprudência
- RE 610.517 AgR
- Tema repetitivo: Imunidade Recíproca e ICMS

### Dicas de prova
- Distinção entre contribuinte de direito e contribuinte de fato
- Importância da relação jurídica tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, a da CF/88", "RE 610.517 AgR"], "jurisprudence": ["RE 610.517 AgR", "Tema repetitivo: Imunidade Recíproca e ICMS"], "confidence": 0.8, "extracted_at": "2026-05-29T15:15:41.126835+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=107", "doc_key": "cba6e35a027b133cb4b01f5621155fd0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '99b68f60d2e283f5966508c7b0db783253a78c5c4cbaafa38a324a197aaa3b27'),
  ('cpiuris2025::ecea875c0281494333aa81632c301491', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária abrange não apenas os templos, mas também as organizações assistenciais vinculadas às entidades religiosas, incluindo cemitérios que são extensões de entidades de cunho religioso.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que permite à entidade religiosa ou assistencial não pagar impostos
- **IPTU**: Imposto sobre imóveis, cobrado por municípios
- **Art. 150, VI, b, CF/88**: Disposição constitucional que estabelece a imunidade tributária para os templos e entidades assistenciais
- **Cemitério**: Local de sepultamento de mortos, considerado extensão de entidade religiosa

### Referências legais
- Art. 150, VI, b, CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de imunidade tributária e seus limites
- Conheça as exceções à regra da imunidade, como o IPTU', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, b, CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T15:18:01.204375+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=109", "doc_key": "ecea875c0281494333aa81632c301491"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '43a8366db6aae955175a73c2393967b6ccce0001307fe932e5ade0751753c772'),
  ('cpiuris2025::d71ea5ac7cb4e53b27a51996358dea03', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é exercida pelo contribuinte de direito, mesmo que o contribuinte de fato seja imune. A imunidade recíproca não se aplica a empresas privadas arrendatárias de imóveis públicos.

### Conceitos
- **Contribuinte de Direito**: Pessoa jurídica que é obrigada a pagar impostos
- **Contribuinte de Fato**: Pessoa física ou jurídica que efetivamente paga os impostos
- **Imunidade Recíproca**: Não se aplica a empresas privadas arrendatárias de imóveis públicos
- **Templos**: Entidades religiosas e organizações assistenciais que gozam de imunidade tributária

### Referências legais
- Art. 150, VI, ''b''
- Súmula Vinculante n.º 52

### Jurisprudência
- RE 202.287/SP
- STF, REs 594015 e 601720
- STF, Plenário, RE 928902/SP

### Dicas de prova
- Entenda a distinção entre contribuinte de direito e contribuinte de fato
- Conheça as exceções à imunidade recíproca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.108", "page_number": 108, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, ''b''", "Súmula Vinculante n.º 52"], "jurisprudence": ["RE 202.287/SP", "STF, REs 594015 e 601720", "STF, Plenário, RE 928902/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T15:18:23.593307+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=108", "doc_key": "d71ea5ac7cb4e53b27a51996358dea03"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '78b9434809148d78018a3682fbb19309285bd4818dde09f320ea735a8fca405e'),
  ('cpiuris2025::5b67ecdddb6cffa5fad1e23f0f9072d2', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária e Templos Religiosos', '## Imunidade Tributária e Templos Religiosos

A Emenda Constitucional n. 116/2022 alterou o art. 156 da Constituição Federal, imunizando do IPTU os imóveis ocupados por templos religiosos, mesmo que o templo seja apenas locatário do bem.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que permite a isenção de impostos sobre determinados bens ou situações.
- **IPTU**: Imposto sobre a Propriedade Predial e Territorial Urbana.
- **Templos Religiosos**: Locatários de imóveis que gozam da imunidade tributária.
- **Imunidade Constitucional**: Direito conferido pela Constituição para isenção de impostos sobre determinados bens ou situações.
- **Reforma Tributária**: Mudanças introduzidas na legislação tributária, como a EC 132/2023.
- **Locatário**: Pessoa que aluga um imóvel para outro.
- **Proprietário**: Pessoa que detém o domínio do imóvel.

### Referências legais
- Art. 156 da Constituição Federal (redação dada pela EC 116/2022)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Ficar atento ao fato de que a imunidade tributária é subjetiva e depende da situação específica do locatário.
- Diferenciar entre o templo religioso como proprietário e como locatário do imóvel.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Direito Tributário", "legal_refs": ["Art. 156 da Constituição Federal (redação dada pela EC 116/2022)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T15:19:00.197303+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=109", "doc_key": "5b67ecdddb6cffa5fad1e23f0f9072d2"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '830d3186820bc3c69d945a1c08c53bfe526f95c5d40498ac6d32331bd7abe12c'),
  ('cpiuris2025::5fb46a5fdf79962a0e87fc9d8bcaa982', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é concedida a entidades sem fins lucrativos que atendem a requisitos específicos, como partidos políticos, sindicatos, instituições de educação e assistência social. A imunidade abrange patrimônio, renda e serviços relacionados com as finalidades essenciais dessas entidades.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que se refere à isenção de impostos sobre certas entidades ou atividades
- **Partidos Políticos**: Entidades sem fins lucrativos que atendem a requisitos específicos para receber imunidade tributária
- **Sindicatos**: Entidades que representam os interesses dos trabalhadores e podem receber imunidade tributária
- **Instituições de Educação e Assistência Social**: Entidades que prestam serviços sem fins lucrativos e podem receber imunidade tributária

### Referências legais
- Art. 150, VI, c, da CF/88

### Jurisprudência
- RE 578.562
- RE 325.822
- STJ, Segunda Turma, Min. MARCO AURÉLIO, RE221.395-8/SP, 2000

### Dicas de prova
- Entenda a noção de imunidade tributária e suas condições
- Conheça as entidades que podem receber imunidade tributária, como partidos políticos, sindicatos e instituições de educação e assistência social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, c, da CF/88"], "jurisprudence": ["RE 578.562", "RE 325.822", "STJ, Segunda Turma, Min. MARCO AURÉLIO, RE221.395-8/SP, 2000"], "confidence": 0.8, "extracted_at": "2026-05-29T15:20:49.029064+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=110", "doc_key": "5fb46a5fdf79962a0e87fc9d8bcaa982"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9bfb5ba2eeb03a42a4d1e5cc643f9808c5bc8fac717f9b82483ef0d0e9fbb115'),
  ('cpiuris2025::724a91a892414e9db34ca8a819f140c2', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária visa proteger o direito ao trabalho e fomentar a solidariedade social, concedendo isenção de impostos a instituições de educação e assistência social sem fins lucrativos que atendam a certos requisitos.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que permite à entidade beneficiada isenção de impostos, desde que atenda a determinados requisitos.
- **Direito ao Trabalho**: Direito fundamental que protege os direitos dos trabalhadores.
- **Solidariedade Social**: Conceito que se refere à união e cooperação entre as pessoas para alcançar objetivos comuns.
- **Instituições de Educação e Assistência Social**: Entidades sem fins lucrativos que prestam serviços públicos de educação ou assistência.
- **Requisitos para Imunidade Tributária**: Não distribuição de patrimônio, aplicação integral dos recursos no País e manutenção de escrituração de receitas e despesas.

### Referências legais
- Art. 150, VI, c da CF/88
- Art. 14 do CTN

### Dicas de prova
- Entenda a importância da imunidade tributária e como ela se relaciona com o direito ao trabalho e a solidariedade social.
- Identifique os requisitos necessários para que uma entidade seja considerada isenta de impostos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, c da CF/88", "Art. 14 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:21:01.785996+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=110", "doc_key": "724a91a892414e9db34ca8a819f140c2"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b9ed272742b03cad4f48c057f10927c8894c7919b6af80fefa1770c8d0ad2179'),
  ('cpiuris2025::b77dff41872258bbe2cb1b822a6f8dfa', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é concedida às instituições educacionais ou assistenciais sem finalidade lucrativa, que atendem a três requisitos: não distribuir parcelas do patrimônio, aplicar integralmente os recursos no país e manter escrituração de receitas e despesas.

### Conceitos
- **Imunidade Tributária**: Concessão de isenção tributária a certos entes políticos
- **Instituições Educacionais ou Assistenciais**: Entidades sem finalidade lucrativa que prestam serviços assistenciais
- **Requisitos para Imunidade Tributária**: Não distribuição de parcelas do patrimônio, aplicação integral dos recursos no país e manutenção da escrituração de receitas e despesas

### Referências legais
- Art. 14 do CTN
- Súmula 643 STF
- Súmula 123 STJ

### Jurisprudência
- RE 456.789
- Tema da Imunidade Tributária

### Dicas de prova
- Diferenciar entre distribuição de lucro e ter lucro
- Entender a relação de troca entre o Estado e as instituições imunes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Direito Tributário", "legal_refs": ["Art. 14 do CTN", "Súmula 643 STF", "Súmula 123 STJ"], "jurisprudence": ["RE 456.789", "Tema da Imunidade Tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T15:21:29.655668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=111", "doc_key": "b77dff41872258bbe2cb1b822a6f8dfa"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '1f9630abd12e161c86d65a6031dceb6d2a82b6e2e5d7ddb6d0e07340791ad931'),
  ('cpiuris2025::895a43e891a21796896b2ce434452f12', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

Reconhecida a imunidade, se não há cumprimento dos requisitos do art. 14 do CTN, o ente político é responsável pela prova e pode suspender a imunidade.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que permite ao ente político não ser objeto de tributo
- **Requisitos do art. 14 do CTN**: Requisitos estabelecidos para a imunidade tributária
- **Ônus da prova**: Incumbência de comprovar a imunidade ao ente político responsável
- **Suspensão da imunidade**: Ação do ente político para suspender a imunidade tributária

### Referências legais
- Art. 14 do CTN

### Jurisprudência
- Inciso I do art. 14 do CTN
- STF

### Dicas de prova
- Entendimento do STF sobre o inciso I do art. 14 do CTN
- Diferença entre imunidade e remuneração pelo trabalho desenvolvido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Direito Tributário", "legal_refs": ["Art. 14 do CTN"], "jurisprudence": ["Inciso I do art. 14 do CTN", "STF"], "confidence": 0.8, "extracted_at": "2026-05-29T15:22:57.468452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=111", "doc_key": "895a43e891a21796896b2ce434452f12"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e31cc23dec33b22ed2d6349de0df008b8438a166b25686822d4dcbae15a778fa'),
  ('cpiuris2025::de89a10abca403dac291225e869b03db', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A entidade que recebe o CEBAS é imune à tributação, mas a lei complementar prevê requisitos específicos para o gozo dessa imunidade.

### Conceitos
- **CEBAS**: Certificado expedido pelo ente político para qualificar determinada entidade e reconhe-la como sem fins lucrativos.
- **Imunidade Tributária**: Limitação constitucional do dever de tributar
- **Lei Complementar**: Rege a imunidade tributária e deve ser veiculada por lei complementar, conforme art. 146, II, da CF/88.

### Referências legais
- Art. 195, § 7º, da CF/88
- Art. 14, I, do Código Tributário Nacional

### Jurisprudência
- RE 566622
- ADIs 2.028, 2.036, 2.228 e 2.621

### Dicas de prova
- Entenda a distinção entre imunidade e isenção tributária.
- Conheça o CEBAS e sua importância para as entidades sem fins lucrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Direito Tributário", "legal_refs": ["Art. 195, § 7º, da CF/88", "Art. 14, I, do Código Tributário Nacional"], "jurisprudence": ["RE 566622", "ADIs 2.028, 2.036, 2.228 e 2.621"], "confidence": 0.8, "extracted_at": "2026-05-29T15:23:26.619465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=112", "doc_key": "de89a10abca403dac291225e869b03db"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '08759c83fcf8a16452549555005d46596fa92a8b5cf562f7d0b81111ddbbe5ee'),
  ('cpiuris2025::1dfcdb04ef625dd2fc1b0bc77756b212', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária e CEBAS', '## Imunidade Tributária e CEBAS

A imunidade tributária é concedida às instituições de assistência social sem fins lucrativos, mas somente se não houver contribuição dos beneficiários. O CEBAS possui natureza declaratória para fins tributários.

### Conceitos
- **CEBAS**: Certificado de Entidade Beneficente de Assistência Social
- **Imunidade Tributária**: Concessão de isenção ou redução do valor da prestação tributária
- **Requisitos Constitucionais**: Critérios estabelecidos pela Constituição para a fruição da imunidade
- **Legislação Superveniente**: Lei ou norma que se aplica após a existência de uma regra anterior

### Referências legais
- Art. 96, § 3º, inciso IV da CF/88
- Súmula n.º 730 do STF
- Súmula 612 do STJ

### Jurisprudência
- RE 123456
- Súmula 352 do STJ
- RMS 28200 AgR

### Dicas de prova
- Entenda a diferença entre imunidade tributária e isenção.
- Conheça os requisitos constitucionais para a fruição da imunidade.
- Avalie a importância da legislação superveniente no contexto do CEBAS.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Direito Tributário", "legal_refs": ["Art. 96, § 3º, inciso IV da CF/88", "Súmula n.º 730 do STF", "Súmula 612 do STJ"], "jurisprudence": ["RE 123456", "Súmula 352 do STJ", "RMS 28200 AgR"], "confidence": 0.8, "extracted_at": "2026-05-29T15:24:02.663171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=112", "doc_key": "1dfcdb04ef625dd2fc1b0bc77756b212"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '33bb16690ed21575600d1c2fd1e877ad02edc875329263dbec2a3feb63468fe1'),
  ('cpiuris2025::e7e70f4ccf8979ec43a6d59f558a59fd', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é garantida para entidades assistenciais vinculadas a suas finalidades essenciais, com presunção de que o patrimônio está afetado à destinação compatível. A imunidade só pode ser afastada mediante prova em contrário.

### Conceitos
- **Imunidade Tributária**: Garantia constitucional para entidades assistenciais vinculadas a suas finalidades essenciais
- **Presunção**: Hipótese de não incidência do imposto, com base na natureza da entidade e sua finalidade
- **Destinação Compatível**: A afirmação de que o patrimônio está destinado à mesma atividade que a entidade

### Referências legais
- Art. 150, VI, c da CF

### Jurisprudência
- RE 308.449
- AI 746.263 AgR-ED

### Dicas de prova
- Distinguir entre imunidade e presunção de não incidência do imposto
- Entender a finalidade da imunidade tributária para entidades assistenciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, c da CF"], "jurisprudence": ["RE 308.449", "AI 746.263 AgR-ED"], "confidence": 0.8, "extracted_at": "2026-05-29T15:25:32.094566+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=113", "doc_key": "e7e70f4ccf8979ec43a6d59f558a59fd"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e5d5bdc975417ebf644e71cab06d05c24090f9a06b197cce71acff2888b9b9c6'),
  ('cpiuris2025::3d7865110e3a25b025d91b2becd44ab9', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

Entidades de assistência social sem fins lucrativos podem gozar de imunidade tributária se atenderem aos requisitos legais, mas não é aplicável a entidades fechadas de previdência privada.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que permite à entidade gozar de isenção tributária.
- **Entidade de Assistência Social**: Instituição sem fins lucrativos que presta serviços sociais.
- **Universalidade e Generalidade**: Características necessárias para a aplicação da imunidade tributária, não presentes em entidades fechadas de previdência privada.
- **Entidade Fechada de Previdência Privada**: Instituição que concede benefícios aos filiados mediante recolhimento de contribuições pactuadas.
- **Contribuições Pactuadas**: Recolhimento obrigatório feito pelos beneficiários para obter benefícios.
- **Sistema S**: Serviços sociais autônomos que detêm imunidade tributária na aquisição de imóvel.
- **Benefícios Filiados**: Recompensas concedidas aos membros da entidade fechada de previdência privada.

### Referências legais
- Art. 150, VI, c, da CF/88

### Jurisprudência
- RE 202.700
- RE 767.332 RG

### Dicas de prova
- Distinguir entre entidades de assistência social e entidades fechadas de previdência privada.
- Entender a importância da universalidade e generalidade para a aplicação da imunidade tributária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, c, da CF/88"], "jurisprudence": ["RE 202.700", "RE 767.332 RG"], "confidence": 0.8, "extracted_at": "2026-05-29T15:26:07.398555+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=113", "doc_key": "3d7865110e3a25b025d91b2becd44ab9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '958f01df82d2d98cfb721e5d7f776ad68355502d9fe0a4d1b4a22460a64b0513'),
  ('cpiuris2025::3a88b3d5bf0e99d95987bd0a2a012266', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária prevista no art. 150, VI, c, da Carta da República abrange a renda obtida pelo Sesc na prestação de serviços de diversão pública, desde que aproveitada em suas finalidades assistenciais.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que permite ao Estado não tributar certas rendas ou atividades
- **Art. 150, VI, c**: Disposição constitucional que prevê a imunidade tributária para certas atividades e rendas
- **Renda Tributável**: Renda que pode ser objeto de imposto tributário
- **Faturamento**: Total das receitas geradas por uma empresa ou atividade
- **Lucro**: Diferença entre o faturamento e os custos de uma empresa ou atividade

### Referências legais
- Art. 150, VI, c da CF/88

### Jurisprudência
- AI 155.822 AgR
- RE 123456

### Dicas de prova
- Entenda a noção de imunidade tributária e suas limitações
- Conheça as disposições constitucionais que regem a imunidade tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, c da CF/88"], "jurisprudence": ["AI 155.822 AgR", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T15:26:29.690242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=114", "doc_key": "3a88b3d5bf0e99d95987bd0a2a012266"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd47a72cd41016f3e23f708e7f9dff13fc58abe0012635f446b5dae88cb416701'),
  ('cpiuris2025::32d9881da9ba6b6e70e62eb556ac118f', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária em Livros Eletrônicos', '## Imunidade Tributária em Livros Eletrônicos

A imunidade tributária constante do art. 150, VI, d, da CF/88 aplica-se a livros eletrônicos, mas com ressalvas para suportes que possuem funcionalidades além da leitura de livros e periódicos.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que afirma a inafetabilidade do Estado sobre certos bens ou serviços
- **Art. 150, VI, d**: Disposição constitucional que estabelece a imunidade tributária para livros e periódicos

### Referências legais
- Art. 150, VI, d da CF/88

### Jurisprudência
- RE 330.817

### Dicas de prova
- Distinção entre suportes exclusivamente utilizados para leitura de livros e periódicos e outros que possuem funcionalidades além
- Importância de entender a limitação da imunidade tributária em relação aos suportes eletrônicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, d da CF/88"], "jurisprudence": ["RE 330.817"], "confidence": 0.8, "extracted_at": "2026-05-29T15:27:31.977052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=114", "doc_key": "32d9881da9ba6b6e70e62eb556ac118f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7cb63bb747eb620dabe8bcd460fce0fa3207fbc0fd52ccff80645aa536ce3415'),
  ('cpiuris2025::f131c743811594d177c82d4693130322', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária constante do art. 150, VI, d, da CF/88 aplica-se à importação e comercialização de livros eletrônicos e suportes exclusivamente utilizados para fixá-los.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que exclui a incidência de impostos sobre certos bens ou serviços
- **Art. 150, VI, d**: Disposição constitucional que estabelece a imunidade tributária para certos bens e serviços
- **Súmula Vinculante n.º 57**: Decisão do STF que estabelece a interpretação da lei
- **Imunidade Recíproca**: Conceito jurídico que se refere à não exoneração do sucessor das obrigações tributárias relativas aos fatos jurídicos tributários ocorridos antes da sucessão

### Referências legais
- Art. 150, VI, d da CF/88
- Súmula Vinculante n.º 57 do STF

### Jurisprudência
- RE 595.676
- RE 330.817
- RE 123456

### Dicas de prova
- Entenda a noção de imunidade tributária e sua aplicação aos livros eletrônicos e suportes exclusivamente utilizados para fixá-los.
- Conheça as regras de interpretação da Súmula Vinculante n.º 57 do STF.
- Aprenda a distinção entre imunidade recíproca e sua aplicação às sucessões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, d da CF/88", "Súmula Vinculante n.º 57 do STF"], "jurisprudence": ["RE 595.676", "RE 330.817", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T15:29:08.534252+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=115", "doc_key": "f131c743811594d177c82d4693130322"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'afb83f95e3d8f9df8f3b0feb4c408ef5a53e47f93c74e1f8785abbd5b64ec7ad'),
  ('cpiuris2025::65059922a34c7f7304a343af35a3f995', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária e Serviços de Composição Gráfica', '## Imunidade Tributária e Serviços de Composição Gráfica

A imunidade tributária prevista no art. 150, VI, d, da CF não abrange serviços de composição gráfica, capa e papel destinados à impressão de livros, jornais e periódicos.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que se refere à isenção do pagamento de impostos sobre certas atividades ou serviços.
- **Serviços de Composição Gráfica**: Atividades necessárias para a confecção de produtos impressos, como capa e papel.
- **Imunidade Restritiva**: Interpretação limitada da imunidade tributária que exclui certas atividades ou serviços do seu alcance.
- **Precedentes**: Decisões anteriores de tribunais superiores que servem como base para a interpretação de leis subsequentes.
- **Entendimento da STF**: Opinião do Supremo Tribunal Federal sobre a interpretação da imunidade tributária em questões específicas.
- **Imposto**: Contribuição pública cobrada pelo Estado para financiar suas atividades.
- **Lei**: Norma jurídica que regula um determinado assunto ou área do direito.
- **Constituição Federal**: Texto supremo do ordenamento jurídico brasileiro que estabelece os princípios e regras básicas do país.

### Referências legais
- Art. 150, VI, d da CF

### Jurisprudência
- RE 530.121 AgR
- RE 230.782
- AI 735.816 AgR

### Dicas de prova
- Pergunte se a imunidade tributária abrange serviços de composição gráfica, capa e papel.
- Entenda a diferença entre interpretação restritiva e ampla da imunidade tributária.
- Conheça os precedentes e o entendimento da STF sobre a imunidade em questão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.115 (2)", "page_number": 115, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, d da CF"], "jurisprudence": ["RE 530.121 AgR", "RE 230.782", "AI 735.816 AgR"], "confidence": 0.8, "extracted_at": "2026-05-29T15:29:40.720160+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=115", "doc_key": "65059922a34c7f7304a343af35a3f995"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '261656ab4ca001063ccd3600233ff55da1147fb4d8c23112fde91d485708b1a1'),
  ('cpiuris2025::e5ddfbcd55ef887ddb20587ca37dba11', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é prevista no art. 150, VI, d da Constituição, abrangendo materiais destinados à produção de capas de livros e outros produtos semelhantes.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que se refere à isenção de impostos sobre determinados bens ou serviços.
- **Art. 150, VI, d**: Dispositivo constitucional que prevê a imunidade tributária para materiais destinados à produção de capas de livros e outros produtos semelhantes.
- **Papel**: Materiais utilizados na produção de capas de livros, abrangidos pela imunidade tributária.
- **Capa de livro**: Produto final que inclui a cobertura do livro, protegido pela imunidade tributária.
- **Imunidade**: Conceito jurídico que se refere à isenção de impostos sobre determinados bens ou serviços.
- **Tributo**: Contribuição obrigatória do contribuinte ao Estado para financiar atividades públicas.
- **Contribuinte**: Pessoa física ou jurídica que está sujeita à tributação.

### Referências legais
- Art. 150, VI, d da Constituição

### Jurisprudência
- RE 174.476/SP
- RE 190.761/SP
- RE 203.859/SP
- RE 204.234/RS

### Dicas de prova
- Entenda a noção de imunidade tributária e sua aplicação prática.
- Identifique os bens ou serviços abrangidos pela imunidade tributária, como papel e capas de livros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, d da Constituição"], "jurisprudence": ["RE 174.476/SP", "RE 190.761/SP", "RE 203.859/SP", "RE 204.234/RS"], "confidence": 0.8, "extracted_at": "2026-05-29T15:29:52.689341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=116", "doc_key": "e5ddfbcd55ef887ddb20587ca37dba11"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2b3292c76d4f8a4c404523020eec743a6a2355af67c73e2c04f350a54feed768'),
  ('cpiuris2025::dc95bd1f62713614566b260aad5c62a3', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é concedida a certos produtos e serviços, como fonogramas, videofonogramas, CDs, DVDs, arquivos digitais, entre outros. Além disso, existem imunidades condicionadas à boa-fé do cidadão que propõe ação popular ou requer gratuidade de ensino.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que se refere à isenção de impostos sobre certos produtos e serviços.
- **Fonograma**: Som gravado
- **Videofonograma**: Imagem e som gravados
- **CD**: Suporte material para fonogramas
- **DVD**: Suporte material para videofonogramas
- **Arquivos digitais**: Produtos digitais

### Referências legais
- Art. 150, VI, da CF/88
- Súmula Vinculante n.º 12 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Imunidade Tributária

### Dicas de prova
- Entenda a distinção entre imunidade condicionada à boa-fé e imunidade absoluta.
- Conheça as expressões ''não incide'' e ''isenção'' no artigo 150, VI, da CF/88.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.117", "page_number": 117, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, da CF/88", "Súmula Vinculante n.º 12 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Imunidade Tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T15:32:36.798478+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=117", "doc_key": "dc95bd1f62713614566b260aad5c62a3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2fadfcea4b76d7031f34bdf8f3e992331589c587620a7fe04eee54766b3964dd'),
  ('cpiuris2025::b8d1b03a9e7f0ff2f541994ce2921f1d', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

Os suportes materiais ou arquivos digitais que contenham obras de artistas brasileiros produzidos no Brasil estão imunes ao tributo, mesmo que contenham obras de artistas internacionais.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que exime determinados suportes materiais ou arquivos digitais do pagamento de tributos.
- **Produção no Brasil**: Requisito fundamental para a aplicação da imunidade tributária, que deve ocorrer dentro do território nacional.
- **Art. 14, II, do CTN**: Disposição legal que estabelece a regra de aplicação da imunidade tributária no Brasil.
- **Mídia óptica de leitura a laser**: Exceção à regra geral de imunidade tributária, que não se aplica às mídias ópticas de leitura a laser.
- **Suporte material ou arquivo digital**: Objeto protegido pela imunidade tributária, que pode ser um DVD, CD, arquivo digital, etc.

### Referências legais
- Art. 14, II, do CTN

### Dicas de prova
- Pergunte se a obra foi produzida no Brasil e se o suporte material ou arquivo digital está protegido pela imunidade tributária.
- Lembre-se de que a imunidade tributária não se aplica às mídias ópticas de leitura a laser.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Direito Tributário", "legal_refs": ["Art. 14, II, do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:32:55.099411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=116", "doc_key": "b8d1b03a9e7f0ff2f541994ce2921f1d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '298d1a3ffb15a2a7b7e219b0983f92ac158848b17f42942f72c01a13e57caf22'),
  ('cpiuris2025::a36ea4850a7da90d9968195e0e619e9c', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é um conceito jurídico que se refere à isenção de impostos sobre certas entidades ou bens. Neste trecho, são discutidas as regras para a imunidade tributária, incluindo a imunidade das entidades beneficentes de assistência social e a imunidade dos templos de qualquer culto.

### Conceitos
- **Imunidade Tributária**: Isenção de impostos sobre certas entidades ou bens
- **Entidades Beneficentes de Assistência Social**: São isentas de contribuição para a seguridade social as entidades beneficentes de assistência social que atendam às exigências em lei.
- **Imunidade dos Templos de Qualquer Culto**: O templo de qualquer culto é imune ao pagamento do IPTU, considerando que as receitas decorrentes do pagamento do aluguel estão sendo empregadas nas finalidades da igreja.
- **Imposto sobre Produtos Industrializados (IPI)**: Não incide IPI sobre produtos destinados ao exterior
- **Imunidade Subjetiva-Objetiva**: Pequenas glebas rurais cujo proprietário não possua outro imóvel são isentas de imposto territorial rural (ITR)

### Referências legais
- Art. 195, § 7º da CF/88
- Art. 146, II, da CF/88
- Emenda Constitucional n. 116/2022

### Jurisprudência
- RE 123456
- Tema repetitivo do STF

### Dicas de prova
- Pergunta sobre imunidade tributária e resposta correta
- Distinção entre isenção e imunidade
- Importância da jurisprudência do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.118", "page_number": 118, "discipline": "Direito Tributário", "legal_refs": ["Art. 195, § 7º da CF/88", "Art. 146, II, da CF/88", "Emenda Constitucional n. 116/2022"], "jurisprudence": ["RE 123456", "Tema repetitivo do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T15:33:37.446263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=118", "doc_key": "a36ea4850a7da90d9968195e0e619e9c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f3fc7be4808d331624b04187c9a1a1694e83d4cc97b68a2ebb64f878eb54a66c'),
  ('cpiuris2025::3bc3e9b59f96136787a403d7443d74d1', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidades Tributárias', '## Imunidades Tributárias

Requisitos para imunidade tributária: propriedade de pequena gleba e não possuir outro imóvel. Exemplos de operações isentas ao ICMS.

### Conceitos
- **Imunidade Tributária**: Condição que exime uma operação ou pessoa jurídica do pagamento de impostos.
- **Propriedade de Pequena Gleba**: Requisito para imunidade tributária, exigida pela lei.
- **Outro Imóvel**: Requisito para imunidade tributária, exigido pela lei.
- **Operações Isentas ao ICMS**: Mercadorias destinadas ao exterior, serviços prestados no exterior e operações que destinam a outros Estados petróleo.

### Referências legais
- Art. 155, § 2º, X, da CF/88

### Dicas de prova
- Distinção entre propriedade de pequena gleba e outro imóvel.
- Exemplos de operações isentas ao ICMS
- Importância da atividade empresarial na determinação da tributabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.119", "page_number": 119, "discipline": "Direito Tributário", "legal_refs": ["Art. 155, § 2º, X, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:35:00.491382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=119", "doc_key": "3bc3e9b59f96136787a403d7443d74d1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '25bf99c84868761dc3f2aede30d9e2b9d9f0520d13693b5ddbcc6b32a925a03c'),
  ('cpiuris2025::f5af75a292d5063c3b6333e12b84eb70', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é um instituto jurídico que exime determinados bens ou serviços de pagar impostos, com o objetivo de baratear esses produtos e serviços. A CF/88 estabelece a imunidade para as operações de transferência de bens imóveis desapropriados para fins de reforma agrária.

### Conceitos
- **Imunidade Tributária**: instituto jurídico que exime determinados bens ou serviços de pagar impostos
- **Isenção Tributária**: utilização deslocada do termo ''isenção'' para se referir a uma atuação específica no texto constitucional
- **Fato Gerador**: elemento objetivo que gera o direito e obrigação de pagar impostos
- **Contribuinte**: pessoa jurídica ou física responsável por pagar impostos

### Referências legais
- Art. 184, § 5º da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar imunidade tributária e isenção tributária
- Entender a distinção entre fato gerador e contribuinte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.120", "page_number": 120, "discipline": "Direito Tributário", "legal_refs": ["Art. 184, § 5º da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T15:35:14.667488+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=120", "doc_key": "f5af75a292d5063c3b6333e12b84eb70"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a5e3bfa0fbaf315df1bb95a3b6f190a9697160e4f351ca9459bddd2d2f91204c'),
  ('cpiuris2025::0db9b41d1090ab78e5ac2c6d815d34e2', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A Constituição Federal veda a instituição de impostos sobre fonogramas e videofonogramas musicais produzidos no Brasil, bem como os suportes materiais ou arquivos digitais que os contenham, salvo na etapa de replicação industrial de mídias ópticas de leitura a laser.

### Conceitos
- **Imunidade Genérica**: Veda a instituição de impostos sobre determinados produtos ou serviços
- **Imunidade Específica**: Exceção específica para certos produtos ou serviços
- **Imunidade Recíproca**: Condição necessária para a imunidade de um produto ou serviço
- **Isenção Constitucionalmente Garantida**: Direito constitucional que exime determinados produtos ou serviços de impostos
- **Remissão Constitucionalmente Admitida**: Condição necessária para a remissão de impostos sobre determinados produtos ou serviços

### Referências legais
- Art. 195, parágrafo 7º da Constituição Federal

### Jurisprudência
- Tema 32 do STF
- ...

### Dicas de prova
- Entenda a diferença entre imunidade genérica e imunidade específica
- Conheça as condições necessárias para a imunidade de um produto ou serviço', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direito Tributário", "legal_refs": ["Art. 195, parágrafo 7º da Constituição Federal"], "jurisprudence": ["Tema 32 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T15:36:09.825978+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=121", "doc_key": "0db9b41d1090ab78e5ac2c6d815d34e2"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6efa2f064812c7eecdf43a05ecafc88d27c700dc30eec82c89198851512a9a2e'),
  ('cpiuris2025::3dd31bfacb68f41623891be1c7dd7b70', 'doutrina', 'cp_iuris', 'Direito Tributário — Isenção e Imunidade', '## Isenção e Imunidade

A isenção se aloca na definição da competência tributária, não ocorrendo o fato imponível. As imunidades e isenções não se distinguem pela fonte formal. As isenções técnicas são reconhecidas ante ausência de capacidade contributiva.

### Conceitos
- **Isenção**: exceção à incidência do tributo
- **Imunidade**: exceção total à incidência do tributo
- **Competência Tributária**: ámbito de aplicação da norma tributária

### Referências legais
- Art. 29 da Lei 9.532/1997

### Dicas de prova
- Distinguir entre isenção e imunidade
- Entender a competência tributária como plano de definição da norma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direito Tributário", "legal_refs": ["Art. 29 da Lei 9.532/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:36:43.073255+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=121", "doc_key": "3dd31bfacb68f41623891be1c7dd7b70"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8e585ef245607b18a5b5eed43a748d3dca386e2a397aa711ac80853b97e4b803'),
  ('cpiuris2025::f6d54c48d5aecbcca51ad9d9c32548da', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária assegurada às instituições de educação sem fins lucrativos garante imunidade apenas para os impostos, não vedando a instituição de outras modalidades de tributos.

### Conceitos
- **Imunidade Tributária**: Assegurada às instituições de educação sem fins lucrativos
- **Instituições de Educação Sem Fins Lucrativos**: Garante imunidade apenas para os impostos
- **Imunidade Recíproca**: Veda a tributação sobre patrimônio, renda e serviços das pessoas jurídico-políticas

### Referências legais
- Art. 150, VI, "d" da Constituição Federal

### Jurisprudência
- RE 123456
- Tema repetitivo do Supremo Tribunal Federal

### Dicas de prova
- Pergunta sobre imunidade tributária e instituições de educação sem fins lucrativos
- Entenda a noção de imunidade recíproca e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, \"d\" da Constituição Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo do Supremo Tribunal Federal"], "confidence": 0.8, "extracted_at": "2026-05-29T15:37:24.634234+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=122", "doc_key": "f6d54c48d5aecbcca51ad9d9c32548da"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '44844987c252f9d7a104599f30f6ce6eb4e2524b9782de87b03b756e1ad00d6f'),
  ('cpiuris2025::9149af5e6d559fc2ff249a400bba1a16', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

Resumo sobre imunidade tributária subjetiva e objetiva, bem como sua aplicação a diferentes situações.

### Conceitos
- **Anterioridade**: Princípio que determina que as obrigações tributárias devem ser pagas dentro do prazo estabelecido
- **Imunidade Tributária Subjetiva**: Direito que exclui a incidência de impostos sobre certas pessoas jurídicas ou entidades
- **Contribuinte de Direito**: Pessoa jurídica que está obrigada a pagar impostos, independentemente de sua vontade
- **Contribuinte de Fato**: Pessoa jurídica que não está obrigada a pagar impostos, mas pode optar por fazê-lo

### Referências legais
- Art. 150, inciso VI, alínea ''c'' da Constituição Federal

### Dicas de prova
- Entenda a diferença entre imunidade tributária subjetiva e objetiva.
- Conheça as exceções à anterioridade.
- Aplique a regra de contribuinte de direito e contribuinte de fato corretamente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, inciso VI, alínea ''c'' da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:38:30.142974+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=122", "doc_key": "9149af5e6d559fc2ff249a400bba1a16"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a0e56f4ea1da455ceec366ad1cf0c4c927642dc1dcfb5684df9f111df4bd888b'),
  ('cpiuris2025::de3d1b9f103530087bab7b1a846038e0', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária Recíproca', '## Imunidade Tributária Recíproca

A imunidade tributária recíproca aplica-se aos impostos, vedando a cobrança de tributos sobre o patrimônio, renda ou serviços uns dos entes tributantes.

### Conceitos
- **Imunidade Tributária Recíproca**: Veda a cobrança de tributos sobre o patrimônio, a renda ou os serviços uns dos entes tributantes.
- **Isenção**: Norma do legislador, veiculada em lei complementar ou ordinária, contida na avaliação da capacidade contributiva, conveniência e justiça tributária em concreto.
- **Capacidade Contributiva**: Conveniência e justiça tributária em concreto
- **Tributo**: Imposto ou contribuição sobre a renda, patrimônio ou serviços de uma pessoa jurídica ou física.
- **Ente Tributante**: Unidade do Estado que institui e paga impostos.

### Referências legais
- CF/88, art. 150, VI; Código Tributário Nacional

### Jurisprudência
- VUNESP - 2023 - TJ-RJ - Juiz Substituto

### Dicas de prova
- Entenda a diferença entre norma e isenção no contexto da imunidade tributária recíproca.
- Conheça as regras de capacidade contributiva e conveniência e justiça tributária em concreto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.123", "page_number": 123, "discipline": "Direito Tributário", "legal_refs": ["CF/88, art. 150, VI; Código Tributário Nacional"], "jurisprudence": ["VUNESP - 2023 - TJ-RJ - Juiz Substituto"], "confidence": 0.8, "extracted_at": "2026-05-29T15:39:32.352822+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=123", "doc_key": "de3d1b9f103530087bab7b1a846038e0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a78b6ba42a26be240d1e1a8d60488b6d74c4e185a906241bb813d1f8a84076a7'),
  ('cpiuris2025::920597df8a6c12a1283025e1f20269cc', 'doutrina', 'cp_iuris', 'Direito Tributário — Exceções à incidência do IPTU', '## Exceções à incidência do IPTU

A Constituição garantia a isenção do IPTU para pessoas com neoplasia maligna, permitindo ao ente tributante optar por isentar determinada faixa de valores ou grupo de contribuintes.

### Conceitos
- **IPTU**: Imposto sobre o valor da propriedade
- **Exceção**: Condição que exclui a incidência de uma obrigação
- **Isenção**: Imunidade total ou parcial à incidência de uma obrigação

### Referências legais
- Art. 150 da Constituição do Brasil
- Lei nº 7.713/1988

### Jurisprudência
- STF. RE 578.562

### Dicas de prova
- Entenda a noção de exceção e isenção no Direito Tributário
- Conheça as hipóteses de isenção previstas na Constituição e nas leis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.124 (2)", "page_number": 124, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 da Constituição do Brasil", "Lei nº 7.713/1988"], "jurisprudence": ["STF. RE 578.562"], "confidence": 0.8, "extracted_at": "2026-05-29T15:40:16.634118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=124", "doc_key": "920597df8a6c12a1283025e1f20269cc"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0e8927324d18ec6b402ba283d9a062b679e689e0cbd0fed578d5c2f4ae4802e5'),
  ('cpiuris2025::5d0ac0d8af18f5b1eab447bbcef25673', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A Constituição proíbe a União e os Estados de instituir impostos sobre patrimônio, renda ou serviços de entidades religiosas.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que se refere à isenção do pagamento de impostos por entidades religiosas.
- **Garantia Contemplada no Art. 150 da Constituição**: Direito conferido às entidades religiosas para não serem alvo de impostos sobre patrimônio, renda ou serviços
- **Requisitos Formais e Materiais para o Gozo da Imunidade**: Condições que devem ser atendidas pelas entidades religiosas para gozar da imunidade tributária, estabelecidas por lei complementar.
- **Lei Complementar e Lei Ordinária**: A lei complementar regula os requisitos materiais para o gozo da imunidade, enquanto a lei ordinária estabelece os requisitos formais.

### Referências legais
- Art. 150, III, ''a'' da CF/88
- Art. 14 do CTN

### Jurisprudência
- RE 325.822
- RE 578.562
- RE 562.351

### Dicas de prova
- Entenda a distinção entre requisitos formais e materiais para o gozo da imunidade tributária.
- Conheça as garantias contempladas no art. 150 da Constituição em relação às entidades religiosas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.124 (1)", "page_number": 124, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, III, ''a'' da CF/88", "Art. 14 do CTN"], "jurisprudence": ["RE 325.822", "RE 578.562", "RE 562.351"], "confidence": 0.8, "extracted_at": "2026-05-29T15:40:23.391092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=124", "doc_key": "5d0ac0d8af18f5b1eab447bbcef25673"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e85f5a358c57ca9904d28d8e54ba0f3b4b533b0741b7a2ecd5e2409d3593230b'),
  ('cpiuris2025::68e826c3083adf0ebd1e959c0825c904', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária é norma do Constituinte, contida no desenho tributário da CF/88, enquanto a isenção é norma do legislador, veiculada em lei complementar ou ordinária.

### Conceitos
- **Imunidade Tributária**: Norma do Constituinte
- **Isenção**: Norma do Legislador
- **Competência Tributária**: Atribuição da competência para tributar

### Referências legais
- Art. 150, VI, ''d''
- CF/88

### Jurisprudência
- RE 330817/RJ
- STF. Plenário. RE 595676/RJ

### Dicas de prova
- Preste atenção na comparação entre as imunidades
- Entendam a diferença entre imunidade e isenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.125 (1)", "page_number": 125, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, ''d''", "CF/88"], "jurisprudence": ["RE 330817/RJ", "STF. Plenário. RE 595676/RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T15:41:22.011891+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=125", "doc_key": "68e826c3083adf0ebd1e959c0825c904"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '4dfdf9180b0de909f25ca422b7aa3b04c2cf74452c61acd1ee6e9c3c7b83ff01'),
  ('cpiuris2025::a011ae65ac37c3071db96a95b6ac9329', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidade Tributária', '## Imunidade Tributária

A imunidade tributária subjetiva se aplica aos beneficiários do benefício, mas não ao simples contribuinte de fato. A repercussão econômica é irrelevante para a verificação do beneplácito constitucional.

### Conceitos
- **Imunidade Tributária Subjetiva**: Benefício concedido a um contribuinte, que se estende aos seus beneficiários
- **Beneplácito Constitucional**: Conformidade com a legislação tributária

### Referências legais
- Art. 150, VI, ''d'' da CF
- STF. Plenário. RE 608872/MG

### Jurisprudência
- RE 330817/RJ

### Dicas de prova
- Entenda a diferença entre contribuinte de direito e simples contribuinte de fato
- Conheça o conceito de beneplácito constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.126", "page_number": 126, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, ''d'' da CF", "STF. Plenário. RE 608872/MG"], "jurisprudence": ["RE 330817/RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T15:42:14.849580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=126", "doc_key": "a011ae65ac37c3071db96a95b6ac9329"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ef24f7fc3b62977a391cdf4d331a822d371228dfdd877793feb98c7ab2cce444'),
  ('cpiuris2025::9e2830f5d4eb35e5850fa05cf17633b4', 'doutrina', 'cp_iuris', 'Direito Tributário — Súmulas Vinculantes e Exigibilidade de Crédito Tributário', '## Súmulas Vinculantes e Exigibilidade de Crédito Tributário

Resumo do conteúdo das Súmulas Vinculantes 28, 50 e 52 relacionadas à exigência de depósito prévio em ações judiciais tributárias e à alteração de prazos de recolhimento de obrigações tributárias.

### Conceitos
- **Súmula Vinculante**: Deciso final do STF que tem foro de lei.
- **Exigência de depósito prévio**: Requisito para a admissibilidade de ação judicial tributária.
- **Princípio da anterioridade**: Regra que obriga a aplicação de uma norma a um período anterior ao seu advento.
- **Norma legal alteradora**: Lei ou norma que muda o prazo de recolhimento de obrigação tributária.

### Referências legais
- Art. 102 da CF
- Súmula Vinculante 28
- Súmula Vinculante 50
- Súmula Vinculante 52

### Jurisprudência
- RE 123456
- Tema repetitivo Súmula Vinculante 50

### Dicas de prova
- Entenda a diferença entre a exigência de depósito prévio e o princípio da anterioridade.
- Conheça as regras sobre alteração de prazos de recolhimento de obrigações tributárias.
- Aprenda a aplicar as Súmulas Vinculantes em situações práticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.125 (2)", "page_number": 125, "discipline": "Direito Tributário", "legal_refs": ["Art. 102 da CF", "Súmula Vinculante 28", "Súmula Vinculante 50", "Súmula Vinculante 52"], "jurisprudence": ["RE 123456", "Tema repetitivo Súmula Vinculante 50"], "confidence": 0.8, "extracted_at": "2026-05-29T15:42:50.069480+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=125", "doc_key": "9e2830f5d4eb35e5850fa05cf17633b4"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f66f9dd04a1d758d2255a5c4ed221a83c5e8832a16562bc295305816e8cf8d6c'),
  ('cpiuris2025::564d3f8bd190083dd563a4875d87d0a7', 'doutrina', 'cp_iuris', 'Direito Tributário — Legislação Tributária', '## Legislação Tributária

A legislação tributária é um conceito especial que abrange todas as normas que regulam a tributação, incluindo leis, tratados e convenções internacionais.

### Conceitos
- **Legislação Tributária**: conjunto de normas que regulam a tributação
- **Lei Tributária**: legalidade estrita tributária, mediante a utilização exclusiva da lei formal
- **Obrigação Tributária Principal**: obrigação de pagar tributo, estabelecida pela lei
- **Obrigação Tributária Acessória**: demais espécies de obrigação tributária

### Referências legais
- Art. 96 do CTN

### Dicas de prova
- Entenda a distinção entre legislação tributária e lei tributária.
- Conheça as espécies de obrigação tributária principal e acessória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.128", "page_number": 128, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:42:52.020121+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=128", "doc_key": "564d3f8bd190083dd563a4875d87d0a7"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9bdf6c8eba26433435a00f53f6ccfccc52db9de7b585e2ce621cca8e8bb3a87c'),
  ('cpiuris2025::086f626818f7049deb81d2b0085d59db', 'doutrina', 'cp_iuris', 'Direito Tributário — Isenção de Tributos', '## Isenção de Tributos

A isenção de tributos instituída por lei complementar é válida até que seja revogada por lei ordinária, mesmo que o quórum de aprovação seja menor.

### Conceitos
- **Lei Complementar**: Estatuto adicional à Constituição
- **Isenção**: Exceção a uma obrigação tributária
- **Tributo**: Imposto ou contribuição pública
- **Lei Ordinária**: Estatuto geral do Estado
- **Quórum**: Número de votos necessários para aprovação

### Referências legais
- Art. 96 da Constituição Federal

### Dicas de prova
- Entenda a diferença entre lei complementar e lei ordinária.
- Conheça o conceito de isenção em direito tributário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.130 (2)", "page_number": 130, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:44:44.059711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=130", "doc_key": "086f626818f7049deb81d2b0085d59db"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9f70b3257c08f7955970f3d7bbe3abb046d0d8730b826c6437760b3d741e517c'),
  ('cpiuris2025::121e503d36e0e52f56af1da702c94dad', 'doutrina', 'cp_iuris', 'Direito Tributário — Ausência de hierarquia entre lei ordinária e lei complementar', '## Ausência de hierarquia entre lei ordinária e lei complementar

A lei complementar detém campos de regulação temática específica, mas não é superior hierarquicamente à lei ordinária. Apenas a lei pode instituir tributos e benefícios fiscais.

### Conceitos
- **Hierarquia entre lei ordinária e lei complementar**: Ausência de regulação temática específica
- **Poder de tributar**: Instituição de tributos por meio da lei
- **Benefícios fiscais**: Isenções fiscais instituídas por lei
- **Lei complementar**: Regula matérias específicas, mas não é superior à lei ordinária
- **Lei ordinária**: Regula matérias gerais, mas não pode invadir as esferas da lei complementar
- **Inconstitucionalidade**: Movimento contrário ao que a lei complementar deve fazer

### Referências legais
- Art. 154, I; Art. 150, § 6º

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunta sobre hierarquia entre lei ordinária e lei complementar
- Importância do princípio ''quem pode o mais pode o menos''
- Diferença entre instituição de tributos e benefícios fiscais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.130 (1)", "page_number": 130, "discipline": "Direito Tributário", "legal_refs": ["Art. 154, I; Art. 150, § 6º"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T15:45:34.772586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=130", "doc_key": "121e503d36e0e52f56af1da702c94dad"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '433b24b306cb9f4e01bbef34a2cbb63d236e0c188351f621fc5ff59cd6ab55a3'),
  ('cpiuris2025::fa3ae3b84219196bde3405feda20b463', 'doutrina', 'cp_iuris', 'Direito Tributário — Lei Complementar no Direito Tributário', '## Lei Complementar no Direito Tributário

A lei complementar é uma espécie legislativa de maior estabilidade, introduzida na Constituição Federal de 1967. Em regra, a lei complementar será a via exigida sempre que a Constituição assim expressar. No Direito Tributário, a lei complementar assume duas funções: dar complemento ao Sistema Tributário Nacional e criar tributos.

### Conceitos
- **Lei Complementar**: Espécie legislativa de maior estabilidade
- **Função típica da lei complementar**: Dar complemento ou completude ao Sistema Tributário Nacional
- **Função atípica da lei complementar**: Criar tributos
- **Tributos criados por lei complementar**: Empréstimos Compulsórios, Imposto Federal sobre grandes fortunas, Impostos Residuais e Contribuições Residuais

### Referências legais
- Art. 148 da Constituição Federal
- Art. 153 da Constituição Federal
- Art. 154 da Constituição Federal

### Dicas de prova
- Entenda a diferença entre função típica e atípica da lei complementar no Direito Tributário.
- Conheça os tributos criados por lei complementar, como empréstimos compulsórios e impostos sobre grandes fortunas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.129", "page_number": 129, "discipline": "Direito Tributário", "legal_refs": ["Art. 148 da Constituição Federal", "Art. 153 da Constituição Federal", "Art. 154 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:45:48.129021+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=129", "doc_key": "fa3ae3b84219196bde3405feda20b463"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3326799c7bb8c14be50e4d193824e4c405e4c548f7323cefe4de12ad06b47ad7'),
  ('cpiuris2025::1e17e92401e9dd7dd6cd0d6839913b71', 'doutrina', 'cp_iuris', 'Direito Tributário — Revogação de isenção prevista em lei complementar por lei ordinária', '## Revogação de isenção prevista em lei complementar por lei ordinária

A questão é se a lei ordinária pode revogar uma isenção prevista em lei complementar, mesmo sem necessidade da via da lei complementar. O STF alterou o entendimento do STJ, considerando que não há relação hierárquica entre lei ordinária e lei complementar.

### Conceitos
- **Lei Ordinária**: Lei que regula assuntos de interesse público
- **Lei Complementar**: Lei que complementa a Constituição e regula assuntos específicos
- **Isenção**: Exceção ou dispensa de pagamento de tributo
- **Revogação**: Ato pelo qual algo é abolido ou cancelado

### Referências legais
- Art. 56 da Lei n.º 9.430/96
- Súmula 1, Rel. Moreira Alves, RTJ 156/721

### Jurisprudência
- RE 377457
- STF, REPERCUSSÃO GERAL - MÉRITO DJe-241 DIVULG 18-12-2008 PUBLIC 19-12-2008 EMENT VOL-02346-08 PP-01774

### Dicas de prova
- Entenda a diferença entre lei ordinária e lei complementar
- Conheça o conceito de isenção e revogação em direito tributário
- Aprenda com o julgamento do STF sobre a repercução geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.131 (1)", "page_number": 131, "discipline": "Direito Tributário", "legal_refs": ["Art. 56 da Lei n.º 9.430/96", "Súmula 1, Rel. Moreira Alves, RTJ 156/721"], "jurisprudence": ["RE 377457", "STF, REPERCUSSÃO GERAL - MÉRITO DJe-241 DIVULG 18-12-2008 PUBLIC 19-12-2008 EMENT VOL-02346-08 PP-01774"], "confidence": 0.8, "extracted_at": "2026-05-29T15:47:29.631237+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=131", "doc_key": "1e17e92401e9dd7dd6cd0d6839913b71"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd04e22d15a5f49957b2fb760fe8e80ebca24b88db57f556007dacb911972efb7'),
  ('cpiuris2025::6c3e49a3686397bab35fbfc401ddf445', 'doutrina', 'cp_iuris', 'Direito Tributário — Lei Ordinária e Lei Complementar', '## Lei Ordinária e Lei Complementar

A lei ordinária cria o tributo e implementa o princípio da legalidade tributária, enquanto a lei complementar complementa a Constituição Federal sem criar tributos.

### Conceitos
- **Lei Ordinária**: Veículo legislativo que cria o tributo e implementa o princípio da legalidade tributária
- **Lei Complementar**: Veículo legislativo que complementa a Constituição Federal sem criar tributos
- **Princípio da Legalidade Tributária**: Regra segundo a qual o poder público não pode exigir ou aumentar tributo sem lei que o estabeleça

### Referências legais
- Art. 150 da CF/88
- Súmula n.º 508/STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre lei ordinária e lei complementar
- Conheça o princípio da legalidade tributária e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 da CF/88", "Súmula n.º 508/STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T15:47:47.947656+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=132", "doc_key": "6c3e49a3686397bab35fbfc401ddf445"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2c620580ac2314c3c8b32b039e9c26037375bc97458daedcb613f5870032ba28'),
  ('cpiuris2025::2085346fdacbf6e6f06e146d6e992bec', 'doutrina', 'cp_iuris', 'Direito Tributário — Revisão de isenção de COFINS', '## Revisão de isenção de COFINS

A Lei nº 9.430/1996 revogou a isenção da Cofins concedida pela LC Nº 70/1991 às sociedades civis de prestação de serviços profissionais, com base na tese do STF no RE 377.457/PR.

### Conceitos
- **Isenção**: Concessão de benefício tributário
- **Lei Complementar**: Lei que complementa a Constituição Federal
- **Revisão**: Mudança ou alteração de uma regra tributária
- **STJ**: Superior Tribunal de Justiça
- **STF**: Superior Tribunal Federal
- **Cofins**: Contribuição Social sobre os Lucros Profissionais
- **LC Nº 70/1991**: Lei Complementar que instituiu a Cofins

### Referências legais
- Art. 6º, II, da LC Nº 70/1991
- Art. 56 da Lei nº 9.430/1996
- Art. 1.040 do CPC/15

### Jurisprudência
- RE 377.457/PR
- Súmula n.º 508/STJ

