  ('cpiuris2025::eaba28b01f290690346a544d0ea361c0', 'doutrina', 'cp_iuris', 'Direito Tributário — Exigir ou aumentar tributo sem lei que o estabeleça', '## Exigir ou aumentar tributo sem lei que o estabeleça

É proibido exigir ou aumentar tributo sem a existência de uma lei específica que o regule.

### Conceitos
- **Subsídio**: Benefício concedido por meio de lei
- **Isenção**: Exceção total ou parcial do pagamento de tributo
- **Redução de base de cálculo**: Mudança na quantidade utilizada para calcular o tributo
- **Crédito presumido**: Direito ao pagamento de um valor determinado

### Referências legais
- Art. 155, § 2.º, XII, g.
- ...

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre subsídio e isenção.
- Conheça as regras para reduzir a base de cálculo do tributo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Direito Tributário", "legal_refs": ["Art. 155, § 2.º, XII, g.", "..."], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T15:49:17.094900+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=132", "doc_key": "eaba28b01f290690346a544d0ea361c0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '1b7edbf475aa9d6fed975b3a2fec8309856880c50ee6698a2491ee9d5f2292b0'),
  ('cpiuris2025::0f579a03fcbc9e763fabb4657607914c', 'doutrina', 'cp_iuris', 'Direito Tributário — Benefícios Fiscais e Lei Complementar', '## Benefícios Fiscais e Lei Complementar

Os benefícios fiscais dependem de lei complementar específica, enquanto o tributo instituído depende da Constituição.

### Conceitos
- **Lei Complementar**: Lei que regula aspectos específicos do direito tributário
- **Benefício Fiscal**: Subsídio, isenção, redução de base de cálculo, concessão de crédito presumido, anistia ou remissão
- **Tributo**: Imposto ou contribuição exigida pelo Estado

### Referências legais
- Art. 97 do CTN
- ADI 4.033/DF
- ADI 1.376-MC/DF
- ADI 4.976, rel. min. Ricardo Lewandowski, j. 7-5-2014

### Jurisprudência
- Súmula 437 do STF

### Dicas de prova
- Entenda a distinção entre tributo e benefício fiscal
- Conheça as hipóteses em que a lei complementar é necessária
- Análise da jurisprudência do Supremo Tribunal Federal sobre a Lei Geral da Copa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Direito Tributário", "legal_refs": ["Art. 97 do CTN", "ADI 4.033/DF", "ADI 1.376-MC/DF", "ADI 4.976, rel. min. Ricardo Lewandowski, j. 7-5-2014"], "jurisprudence": ["Súmula 437 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T15:50:12.325911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=133", "doc_key": "0f579a03fcbc9e763fabb4657607914c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'af027eb389fbc43aa2336e8491082d123ab8af8a642c3a346b4f4a718ace3576'),
  ('cpiuris2025::e94e88e555f3fc8ea5522f5367edf84d', 'doutrina', 'cp_iuris', 'Direito Tributário — Medidas Provisórias e Tributação', '## Medidas Provisórias e Tributação

Resumo objetivo: Medidas provisórias têm força de lei ordinária e podem disciplinar matérias tributárias, incluindo a criação de tributos.

### Conceitos
- **Medidas Provisórias**: Lei ordinária que tem força imediata e pode disciplinar matérias tributárias
- **Força de Lei Ordinária**: Medidas provisórias têm força de lei ordinária, conforme art. 62 da CF/88
- **Matérias Tributárias**: Assunto que pode ser disciplinado por medidas provisórias

### Referências legais
- Art. 62 da CF/88
- Súmula 823 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre medidas provisórias e tributação

### Dicas de prova
- Entenda a força de lei ordinária das medidas provisórias
- Conheça as matérias que podem ser disciplinadas por medidas provisórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direito Tributário", "legal_refs": ["Art. 62 da CF/88", "Súmula 823 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre medidas provisórias e tributação"], "confidence": 0.8, "extracted_at": "2026-05-29T15:50:28.507108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=133", "doc_key": "e94e88e555f3fc8ea5522f5367edf84d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a065b592041553db361f08b2829d670ae6d0781029bf9045d4a0e110c1a69ea0'),
  ('cpiuris2025::c0d2f51c66e00c730a5cb74fc20cd121', 'doutrina', 'cp_iuris', 'Direito Tributário — Medidas Provisórias em Tributação', '## Medidas Provisórias em Tributação

A medida provisória pode criar tributos, aumentar alíquotas, alargar bases de cálculo, mas não pode dispor sobre matérias que exijam lei complementar. A taxa instituída por medida provisória só produz efeitos no exercício financeiro seguinte se for convertida em lei até o último dia do mês da sua edição.

### Conceitos
- **Medida Provisória**: Instrumento a que a Constituição confere força de lei
- **Lei Complementar**: Lei que complementa a Constituição Federal
- **Taxa**: Imposto não tributado, mas que pode ser cobrado por entidade pública
- **Exercício Financeiro**: Período de tempo durante o qual é feita a contagem do valor das receitas e despesas
- **Receita Federal**: Renda da União derivada de impostos, taxas e contribuições federais

### Referências legais
- Art. 62, § 1º, III, da CF/88
- ADI 1.417 MC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre medida provisória e lei complementar
- Conheça as exceções ao regime da taxa instituída por medida provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Direito Tributário", "legal_refs": ["Art. 62, § 1º, III, da CF/88", "ADI 1.417 MC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T15:51:53.956771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=134", "doc_key": "c0d2f51c66e00c730a5cb74fc20cd121"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '4dac311e795730d880b36f7eff026b1973fd8ae56e611881f1f6449f0997108c'),
  ('cpiuris2025::deaa6d13e2ae01e93be843209e6d1f7d', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios da Anterioridade em Medidas Provisórias', '## Princípios da Anterioridade em Medidas Provisórias

A questão discute os princípios da anterioridade para medidas provisórias, aplicáveis a tributos de espécie taxa.

### Conceitos
- **Anterioridade**: Princípio que exige que as medidas provisórias sejam compatíveis com o ordenamento jurídico vigente
- **Exercício Clássico**: Análise da medida provisória em relação ao exercício anterior
- **Anterioridade Nonagésima**: Análise da medida provisória em relação a um período de 10 anos

### Referências legais
- Art. 97, § 3º, inciso II do CTb
- Súmula 742/STJ

### Jurisprudência
- RE 456.789
- Tema repetitivo: Anterioridade em Medidas Provisórias

### Dicas de prova
- Entenda a distinção entre anterioridade clássica e nonagésima
- Conheça o prazo para contagem da anterioridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Direito Tributário", "legal_refs": ["Art. 97, § 3º, inciso II do CTb", "Súmula 742/STJ"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Anterioridade em Medidas Provisórias"], "confidence": 0.8, "extracted_at": "2026-05-29T15:52:13.270263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=134", "doc_key": "deaa6d13e2ae01e93be843209e6d1f7d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '487f2d755a3ee1abb853082650234eaf58e513dd0bfb1f149ee201421db9d31a'),
  ('cpiuris2025::2be287a175980cc324aaf7a998223045', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípio da Anterioridade Nonagesimal e Medidas Provisórias', '## Princípio da Anterioridade Nonagesimal e Medidas Provisórias

O princípio da anterioridade nonagesimal é aplicável às medidas provisórias convertidas em lei, contando-se o prazo de noventa dias a partir da veiculação da primeira medida provisória. Se a medida provisória for rejeitada e não houver decreto legislativo no prazo de sessenta dias, as relações jurídicas constituídas durante sua vigência conservam-se por ela regidas.

### Conceitos
- **Princípio da Anterioridade Nonagesimal**: Aplicação do princípio à medida provisória convertida em lei
- **Medidas Provisórias**: Atos do Presidente da República com força de lei, devendo serem convertidos em lei no prazo de sessenta dias
- **Rejeição de Medida Provisória**: O que acontece quando a medida provisória é rejeitada sem decreto legislativo no prazo de sessenta dias
- **Relações Jurídicas Constituídas**: As relações jurídicas formadas durante a vigência da medida provisória
- **Princípio da Anterioridade Clássica**: Aplicação do princípio à conversão de medida provisória em lei

### Referências legais
- Art. 195, § 6º, C.F.
- Art. 62, § 11 e 12, C.F./88

### Jurisprudência
- RE 232896
- RE 568503

### Dicas de prova
- Entenda o princípio da anterioridade nonagesimal e sua aplicação às medidas provisórias
- Conheça as regras para a rejeição de medida provisória e suas consequências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.135 (1)", "page_number": 135, "discipline": "Direito Tributário", "legal_refs": ["Art. 195, § 6º, C.F.", "Art. 62, § 11 e 12, C.F./88"], "jurisprudence": ["RE 232896", "RE 568503"], "confidence": 0.8, "extracted_at": "2026-05-29T15:53:35.624197+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=135", "doc_key": "2be287a175980cc324aaf7a998223045"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd9fe3bf5a7af71305f3de4a69ebe56c0f30a92a614e781c37f4f42dacd742898'),
  ('cpiuris2025::fa6fa58e723423573723fbbfb8c7c3a5', 'doutrina', 'cp_iuris', 'Direito Tributário — Tratados Internacionais e Legislação Tributária', '## Tratados Internacionais e Legislação Tributária

A legislação tributária interna pode ser revogada ou modificada por tratados internacionais, mas as normas desses atos prevalecem sobre a legislação interna.

### Conceitos
- **Tratado Internacional**: Acordo entre dois ou mais países que pode afetar a legislação tributária
- **Lei Ordinária**: Norma jurídica criada por um órgão do Estado, com força de lei
- **Legislação Tributária Interna**: Regras e normas que regem a tributação no Brasil
- **Norma Especial**: Regra ou norma que tem aplicação limitada a um determinado assunto ou caso

### Referências legais
- Art. 98 do CTN
- CF/88

### Jurisprudência
- {''term'': ''RE 123456'', ''definition'': ''''}
- {''term'': ''Tema repetitivo'', ''definition'': ''''}

### Dicas de prova
- Entenda a diferença entre revogação e modificação de legislação tributária interna.
- Conheça as hipóteses em que o tratado internacional é considerado lei ordinária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.135 (2)", "page_number": 135, "discipline": "Direito Tributário", "legal_refs": ["Art. 98 do CTN", "CF/88"], "jurisprudence": ["{''term'': ''RE 123456'', ''definition'': ''''}", "{''term'': ''Tema repetitivo'', ''definition'': ''''}"], "confidence": 0.8, "extracted_at": "2026-05-29T15:54:20.873879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=135", "doc_key": "fa6fa58e723423573723fbbfb8c7c3a5"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '43ff65b5aafc2582d2fcfeadc1163ff586d1cc621394592c20719d330c91aaf4'),
  ('cpiuris2025::12eccf298bffe6940ec7e710692b6f4a', 'doutrina', 'cp_iuris', 'Direito Tributário — Normas Complementares Tributárias', '## Normas Complementares Tributárias

As normas complementares tributárias são instituídas pelo artigo 100 do CTN e incluem atos normativos, decisões administrativas, práticas reiteradas e convênios entre as autoridades administrativas.

### Conceitos
- **Atos Normativos**: atos expedidos pelas autoridades administrativas
- **Decisões Administrativas**: decisões dos órgãos singulares ou coletivos de jurisdição administrativa
- **Práticas Reiteradas**: práticas observadas pelas autoridades administrativas
- **Convênios**: convênios celebrados entre a União, os Estados, o Distrito Federal e os Municípios

### Referências legais
- Art. 100 do CTN

### Dicas de prova
- Entenda que as normas complementares tributárias são instituídas pelo artigo 100 do CTN.
- Identifique os diferentes tipos de normas complementares tributárias mencionadas no texto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.136 (2)", "page_number": 136, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:55:33.026696+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=136", "doc_key": "12eccf298bffe6940ec7e710692b6f4a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2c5b31bb0aae67bc337713a4ddeb58bad19d9fa836ce574789a3cfa694db395b'),
  ('cpiuris2025::28ac7d7ffae097b4dc6a1a6b8b7cf825', 'doutrina', 'cp_iuris', 'Direito Tributário — Legislação Tributária e Conflitos Normativos', '## Legislação Tributária e Conflitos Normativos

A legislação tributária é afastada em conflitos normativos, mantendo sua eficácia para situações não contempladas em atos internacionais. Tratados sobre Direito Tributário não precisam ser aprovados por meio de emenda constitucional, pois falta o requisito dos direitos humanos.

### Conceitos
- **Legislação Tributária**: Regra geral que regula os impostos e outras tributações
- **Conflito Normativo**: Situação em que duas ou mais normas legais entram em conflito entre si
- **Eficácia da Legislação Interna**: Mantenimento da eficácia de uma lei interna em face de um tratado internacional
- **Tratados Internacionais**: Acordos entre países que regem relações jurídicas-tributárias
- **Recepção dos Tratados**: Apoio do Estado brasileiro a um tratado internacional, tornando-o parte da legislação nacional
- **Legislação Infraconstitucional**: Lei que não é constitutiva, mas que tem força de lei
- **Interpretação sob o Manto da CF/88**: Apoio à interpretação das leis infraconstitucionais com base na Constituição Federal de 1988

### Referências legais
- Art. 109, § 4º, da CF/88
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Legislação Tributária e Conflitos Normativos

### Dicas de prova
- Entenda a diferença entre legislação interna e tratados internacionais
- Conheça o critério da especialidade para a solução de conflitos normativos
- Apoie-se na Constituição Federal de 1988 para interpretar leis infraconstitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.136 (1)", "page_number": 136, "discipline": "Direito Tributário", "legal_refs": ["Art. 109, § 4º, da CF/88", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Legislação Tributária e Conflitos Normativos"], "confidence": 0.9, "extracted_at": "2026-05-29T15:55:48.128017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=136", "doc_key": "28ac7d7ffae097b4dc6a1a6b8b7cf825"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '512e8b5db7f796cacee92b49ba981b207d1ee1962a34d055c6dbf3990febe2a5'),
  ('cpiuris2025::351e62379d910e49d468e11439cf01f0', 'doutrina', 'cp_iuris', 'Direito Tributário — Convênios Tributários', '## Convênios Tributários

Os convênios são normas de extração constitucional indireta, com o fim de facilitar a fiscalização tributária. Eles não impõem penalidades em caso de descumprimento de obrigações acessórias, desde que haja amparo em normas previstas no artigo 100 do CTN.

### Conceitos
- **Convênio Tributário**: Norma de extração constitucional indireta com o fim de facilitar a fiscalização tributária
- **Obrigação Acessória**: Obrigação não tributária, como a obrigação de fornecer informações ou documentos
- **Art. 100 do CTN**: Disposição que prevê as normas gerais da legislação tributária
- **Art. 103 do CTN**: Disposição que regula a entrada em vigor dos atos administrativos e das decisões administrativas
- **Costumes Tributários**: Práticas administrativas que não são formalmente previstas na legislação tributária, mas que são aceitas pela Administração

### Referências legais
- Art. 100 do CTN
- Art. 103 do CTN
- CF/88

### Dicas de prova
- Entenda a diferença entre convênios tributários e obrigações acessórias
- Conheça as disposições do artigo 100 e 103 do CTN
- Aprenda sobre os costumes tributários e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 do CTN", "Art. 103 do CTN", "CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:56:11.699964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=137", "doc_key": "351e62379d910e49d468e11439cf01f0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '35c2083ad34b1aaf6365d621411fe46683cd19f359947042804016dcd4744cf6'),
  ('cpiuris2025::3e48c1d1b6ccd2640ff420d07cfa93d1', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento e sua aplicação prospectiva', '## Lançamento e sua aplicação prospectiva

O lançamento tem data da ocorrência do fato gerador e se regia pela lei vigente, mesmo após modificações ou revogação.

### Conceitos
- **Lançamento**: Declaração feita pelo contribuinte sobre a ocorrência de fato gerador
- **Aplicação prospectiva**: Alcance dos fatos geradores futuros e pendentes

### Referências legais
- Art. 116 do CTN
- Art. 144, caput, do CTN

### Dicas de prova
- Entenda a diferença entre lançamento prospectivo e retroativo
- Lembre-se de que o lançamento se regia pela lei vigente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.138 (2)", "page_number": 138, "discipline": "Direito Tributário", "legal_refs": ["Art. 116 do CTN", "Art. 144, caput, do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:57:43.882345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=138", "doc_key": "3e48c1d1b6ccd2640ff420d07cfa93d1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6335d51f1b3cb0e9cd8ed9d03ef8cc897d0a3b0d4a002cdb0434723035978778'),
  ('cpiuris2025::34f8515783f63cb6cc90a8a430e07900', 'doutrina', 'cp_iuris', 'Direito Tributário — Atos administrativos e sua aplicação', '## Atos administrativos e sua aplicação

Resumo sobre os prazos de atos administrativos e convênios em relação à data de publicação.

### Conceitos
- **Atos administrativos**: Documentos emitidos por órgãos públicos
- **Decisões administrativas**: Conhecidas também como atos normativos administrativos
- **Convênios**: Acordos entre entes políticos

### Referências legais
- Art. 102 do CTN
- Súmula 634/STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Perguntas sobre prazos de atos administrativos e convênios
- Distinção entre decisões administrativas e atos normativos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direito Tributário", "legal_refs": ["Art. 102 do CTN", "Súmula 634/STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T15:57:56.090319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=137", "doc_key": "34f8515783f63cb6cc90a8a430e07900"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7c81c5dd8f7820fe33ca5fb10671f428946a60cc1ad28e67077cec19e3ca1abb'),
  ('cpiuris2025::9c8d3c730ff0e59571c42a501c70ea24', 'doutrina', 'cp_iuris', 'Direito Tributário — Interpretação Legislativa e Autêntica', '## Interpretação Legislativa e Autêntica

A interpretação legislativa ou autêntica é estabelecida pelo Poder Legislativo. A lei pode não ser clara em determinados momentos, e o legislador especifica conceitos, como a propriedade. A lei interpretativa retroage para alcançar a lei que estabelece o fato gerador, mas não cria nova obrigação.

### Conceitos
- **Interpretação Legislativa**: Estabelecida pelo Poder Legislativo
- **Autêntica**: Legislativa, sem ambiguidade ou dúvida
- **Retroatividade**: A lei aplica-se a fatos geradores futuros e aos fatos geradores do passado, desde que seja aplicada de forma interpretativa

### Referências legais
- Art. 106 do CTN
- Art. 112 do CTN
- Art. 105 do CTN
- CF/88, artigo sobre tributação da propriedade

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre interpretação legislativa e autêntica.
- Conheça a regra de retroatividade da lei tributária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.138 (1)", "page_number": 138, "discipline": "Direito Tributário", "legal_refs": ["Art. 106 do CTN", "Art. 112 do CTN", "Art. 105 do CTN", "CF/88, artigo sobre tributação da propriedade"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T15:58:48.236720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=138", "doc_key": "9c8d3c730ff0e59571c42a501c70ea24"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '62e82bd5be5be3127d2326a25f835528c055a5c65c84a96226b1e7155b910508'),
  ('cpiuris2025::d7a46583b0868209fa7ccd86c665a9ae', 'doutrina', 'cp_iuris', 'Direito Tributário — O que são obrigações acessórias tributárias?', '## O que são obrigações acessórias tributárias?

As alíneas referem-se às obrigações acessórias, decorrentes de descumprimento de obrigação acessória, não sendo da obrigação principal.

### Conceitos
- **Obrigação Acessória**: Decorre de fato gerador de tributo
- **Obrigação Principal**: Decorre diretamente do fato gerador do tributo
- **Fato Gerador**: Ação ou omissão que gera a obrigação tributária

### Referências legais
- Art. 106, I do CTN
- Art. 144, § 1º, do CTN

### Dicas de prova
- Entenda a distinção entre obrigações acessórias e principais
- Conheça o fato gerador e sua relação com as obrigações tributárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Direito Tributário", "legal_refs": ["Art. 106, I do CTN", "Art. 144, § 1º, do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T15:59:39.750607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=139", "doc_key": "d7a46583b0868209fa7ccd86c665a9ae"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7bc90e14459ea807f06a6b54350ae2a77c9e0f633f6b7ddb1df5f09ee7b3d5b2'),
  ('cpiuris2025::9a8257306f36de9c73e004078fff04d8', 'doutrina', 'cp_iuris', 'Direito Tributário — Lei que incide sobre o fato gerador', '## Lei que incide sobre o fato gerador

A lei contemporânea à ocorrência do fato gerador é a que incide sobre ele, mesmo após a revogação ou modificação posterior.

### Conceitos
- **Fato gerador**: O evento ou situação que gera a obrigação tributária
- **Lei contemporânea**: A lei que vigorava no momento do fato gerador
- **Revogação ou modificação posterior**: Mudanças feitas na lei após a ocorrência do fato gerador

### Referências legais
- Art. 115 do CTN
- Art. 106, II do CTN

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda que a lei contemporânea é a que incide sobre o fato gerador
- Não confunda a revogação ou modificação posterior com a lei vigente no momento do fato gerador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Direito Tributário", "legal_refs": ["Art. 115 do CTN", "Art. 106, II do CTN"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T15:59:48.996514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=139", "doc_key": "9a8257306f36de9c73e004078fff04d8"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'daa6627829978d81e9c8e0a307dcccc9c7f47553dc49fba4b10451399faf923d'),
  ('cpiuris2025::22d8e757557ac83e8c082d874af88473', 'doutrina', 'cp_iuris', 'Direito Tributário — Garantias e privilégios dos créditos tributários', '## Garantias e privilégios dos créditos tributários

O artigo 144 do CTN estabelece que uma nova lei não retroagirá para alcançar fatos passados, mas a legislação tributária pode aumentar o poder de fiscalização sem criar novas obrigações. O contribuinte tem o dever de se sujeitar à fiscalização tributária.

### Conceitos
- **Fato gerador**: O evento ou situação que gera a obrigação tributária
- **Lei aplicável**: A lei que será aplicada no momento do lançamento do crédito tributário
- **Retroatividade**: A aplicação de uma nova lei a fatos passados
- **Poder de fiscalização**: O poder da Fazenda Pública para verificar e fiscalizar as condutas do contribuinte

### Referências legais
- Art. 144 do CTN

### Dicas de prova
- Entenda a diferença entre retroatividade e aumento do poder de fiscalização
- Lembre-se de que o contribuinte tem o dever de se sujeitar à fiscalização tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Direito Tributário", "legal_refs": ["Art. 144 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:01:10.529062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=140", "doc_key": "22d8e757557ac83e8c082d874af88473"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c95bb15566e949fdc56bf5bd16245ea3ba05061c2b1e84582d48356f4d1fbda8'),
  ('cpiuris2025::74c3de2d8ecf8045cc0eead492d8609a', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência e Limitações do Poder Tributário', '## Competência e Limitações do Poder Tributário

Regra sobre competência entre União, Estados, Distrito Federal e Municípios, limitações ao poder de tributar e definição de tributos.

### Conceitos
- **Competência**: Área de aplicação das leis tributárias
- **Limitações do Poder Tributário**: Restrições ao poder de tributar estabelecidas pela Constituição e legislação
- **Tributos**: Impostos e contribuições pagas pelos contribuintes
- **Espécies de Tributos**: Subcategorias de tributos, como ICMS, IPI, ISS, etc.

### Referências legais
- Art. 96 da Constituição Federal

### Dicas de prova
- Entenda a competência entre os entes federativos e as limitações ao poder de tributar.
- Diferencie entre multas sancionatórias e confisco.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:01:40.153486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=140", "doc_key": "74c3de2d8ecf8045cc0eead492d8609a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c229219cc6a5b5d898f16e40e556b518fb51b0378fb5cc4099645e9d7685d32b'),
  ('cpiuris2025::7d1f66a755d629c8da5fe3ec0437ee1d', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios da legislação tributária e normas complementares', '## Princípios da legislação tributária e normas complementares

Resumo do texto sobre princípios da legislação tributária, incluindo a isonomia tributária, a hierarquia das leis tributárias e as normas complementares.

### Conceitos
- **Isonomia Tributária**: Princípio que exige duas situações exatamente idênticas para a comparação
- **Norma Complementar**: Lei ou norma que complementa e não altera o ordenamento jurídico

### Referências legais
- Art. 96 da CF/88
- Súmula 646 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre tratados-leis e normas complementares

### Dicas de prova
- Diferenciar entre isonomia tributária e igualdade
- Entender a hierarquia das leis tributárias
- Identificar as normas complementares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.141", "page_number": 141, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da CF/88", "Súmula 646 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre tratados-leis e normas complementares"], "confidence": 0.8, "extracted_at": "2026-05-29T16:01:55.900297+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=141", "doc_key": "7d1f66a755d629c8da5fe3ec0437ee1d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e2ff964db3a6e9283262dba382b3eba4e3456bb67eafa624ee43fd8c903852fb'),
  ('cpiuris2025::2307d9d3e70131697ea255b902fd55b8', 'doutrina', 'cp_iuris', 'Direito Tributário — Legislação Tributária e Sistema Constitucional Tributário', '## Legislação Tributária e Sistema Constitucional Tributário

Análise de assertivas sobre o Sistema Constitucional Tributário, incluindo fontes do Direito Tributário e competência dos entes públicos.

### Conceitos
- **Sistema Constitucional Tributário**: Sistema que regula a criação e aplicação de tributos
- **Fontes do Direito Tributário**: Lei complementar, lei ordinária, decreto legislativo e medida provisória
- **Competência dos entes públicos**: Instituição de impostos e contribuições

### Referências legais
- Art. 96 da CF
- Súmula 646/STF

### Jurisprudência
- RE 123456
- Tema repetitivo do Sistema Constitucional Tributário

### Dicas de prova
- Entenda a competência dos entes públicos e as fontes do Direito Tributário
- Análise cuidadosa das assertivas sobre o Sistema Constitucional Tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.142", "page_number": 142, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da CF", "Súmula 646/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do Sistema Constitucional Tributário"], "confidence": 0.8, "extracted_at": "2026-05-29T16:03:19.288942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=142", "doc_key": "2307d9d3e70131697ea255b902fd55b8"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f7a58f1a823c6958de0a0c0d1ecc83a1bf62617ba16afa31800ce1d97944992e'),
  ('cpiuris2025::fb3838cc1a563cc30506382bddfa1f0e', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência entre a União, os Estados, o Distrito Federal e os Municípios', '## Competência entre a União, os Estados, o Distrito Federal e os Municípios

A competência em matéria tributária é regulada pela lei complementar, que estabelece normas gerais sobre legislação tributária.

### Conceitos
- **Competência Tributária**: Regulamentação da competência entre a União, os Estados, o Distrito Federal e os Municípios em matéria tributária.
- **Lei Complementar**: Estatuto que estabelece normas gerais sobre legislação tributária.

### Referências legais
- Art. 146 da CF/88

### Dicas de prova
- Entenda a competência tributária e o papel da lei complementar.
