  ('cpiuris2025::8e4c8679e2c2d03606c30652da0fc12a', 'doutrina', 'cp_iuris', 'Direito Tributário — Legislação Tributária e Constituição', '## Legislação Tributária e Constituição

Resumo do texto sobre a inconstitucionalidade dos artigos 45 e 46 da Lei n.º 8.212/91 e a regulamentação de prescrição e decadência do crédito tributário.

### Conceitos
- **Súmula Vinculante**: Decisão do Supremo Tribunal Federal que tem natureza de lei e é vinculante para todos os juízes.
- **Lei Complementar**: Lei que complementa a Constituição Federal, podendo abordar temas não expressos na Constituição.
- **Prescrição Tributária**: Prazo dentro do qual o Estado deve processar uma ação contra um contribuinte para cobrar um débito tributário.
- **Decadência Tributária**: Prazo após o qual não pode ser processada ação contra um contribuinte por não pagar um débito tributário.
- **Obrigatoriedade do Uso da Lei Complementar**: Regra que obriga os entes tributantes a utilizar a lei complementar para regular temas específicos, como prescrição e decadência.
- **Imunidade Recíproca**: Princípio que veda a cobrança de tributos sobre o patrimônio, a renda ou os serviços uns dos entes tributantes por outro.

### Referências legais
- Art. 45 da Lei n.º 8.212/91
- Art. 46 da Lei n.º 8.212/91
- Súmula Vinculante n. 8

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a Súmula Vinculante e sua importância na regulamentação de prescrição e decadência do crédito tributário.
- Conheça as regras sobre a obrigatoriedade do uso da lei complementar para regular temas específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Direito Tributário", "legal_refs": ["Art. 45 da Lei n.º 8.212/91", "Art. 46 da Lei n.º 8.212/91", "Súmula Vinculante n. 8"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T16:05:05.533668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=143", "doc_key": "8e4c8679e2c2d03606c30652da0fc12a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7909be98bdfb24976966c68bf87b6d42caf974508ecfc5068f7f98023411839d'),
  ('cpiuris2025::15a1f7526e214e56d61c0524e5d1edb4', 'doutrina', 'cp_iuris', 'Direito Tributário — Definição de Tributos e Regime Tributário', '## Definição de Tributos e Regime Tributário

O texto define os tributos, suas espécies e fatos geradores, bem como o regime tributário das microempresas e empresas de pequeno porte.

### Conceitos
- **Tributo**: imposto ou contribuição exigida pelo Estado
- **Fato gerador**: ocorrido que gera a obrigação tributária
- **Contribuinte**: pessoa jurídica ou física obrigada a pagar o tributo
- **Tratamento diferenciado**: regime especial de tributação aplicável às microempresas e empresas de pequeno porte

### Referências legais
- Art. 100 do CTN
- Art. 96 do CTN
- Emenda Constitucional nº 132/2023

### Dicas de prova
- Entenda a distinção entre tributo e imposto.
- Conheça os fatos geradores e contribuintes.
- Aprenda sobre o tratamento diferenciado para microempresas e empresas de pequeno porte.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.144 (1)", "page_number": 144, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 do CTN", "Art. 96 do CTN", "Emenda Constitucional nº 132/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:05:40.005780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=144", "doc_key": "15a1f7526e214e56d61c0524e5d1edb4"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '25b0bb35ca8a0de8f2a3ffa0ba62d4e9d4a7f5ab748ce8f8ddf285372aa3072d'),
  ('cpiuris2025::6980f174d90e4e845960ea0181c26440', 'doutrina', 'cp_iuris', 'Direito Tributário — Revisão e Modificação da Legislação Tributária por Tratados e Convenções Internacionais', '## Revisão e Modificação da Legislação Tributária por Tratados e Convenções Internacionais

O Art. 98 do CTN estabelece que tratados e convenções internacionais revogam ou modificam a legislação tributária interna, sendo observadas pelas novas leis que sobrevenham.

### Conceitos
- **Revisão de Legislação Tributária**: Processo pelo qual a legislação tributária é alterada ou modificada
- **Tratados e Convenções Internacionais**: Acordos entre países que podem influenciar a legislação tributária
- **Legislação Tributária Interna**: Leis nacionais que regem o imposto de renda e outros tributos
- **Decretos**: Atos do Poder Executivo que regulamentam a legislação tributária

### Referências legais
- Art. 98 do CTN
- Art. 99 do CTN
- Art. 100 do CTN

### Dicas de prova
- Entenda que os tratados e convenções internacionais podem revogar ou modificar a legislação tributária interna.
- Conheça as regras de interpretação estabelecidas no CTN para os decretos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.144 (2)", "page_number": 144, "discipline": "Direito Tributário", "legal_refs": ["Art. 98 do CTN", "Art. 99 do CTN", "Art. 100 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:06:09.422419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=144", "doc_key": "6980f174d90e4e845960ea0181c26440"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '077e04322d182d506d5def9b8f70daa7a66c4cb3434ce522e6afed050d6100f0'),
  ('cpiuris2025::ebb42dcddec41f162fc70ede8ce90103', 'doutrina', 'cp_iuris', 'Direito Tributário — Tratados-contratos e tratados-leis', '## Tratados-contratos e tratados-leis

O artigo 98 do CTN permite a distinção entre tratados-contratos e tratados-leis, com a prevalência da norma interna sobre os tratados. A isenção de tributos estaduais prevista no Acordo Geral de Tarifas e Comércio para as mercadorias importadas dos países signatários é recepcionada pela Constituição de 1988.

### Conceitos
- **Tratado-contrato**: Acordo internacional que não tem caráter nacional
- **Tratado-lei**: Acordo internacional que tem caráter nacional e prevalece sobre a legislação interna
- **Isenção de tributos estaduais**: Benefício concedido às mercadorias importadas dos países signatários do Acordo Geral de Tarifas e Comércio

### Referências legais
- Art. 98 do CTN
- Art. 146, II da CF/88
- Art. 151, III da CF/88

### Jurisprudência
- REsp. 426.945/PR
- RE 229.096

### Dicas de prova
- Distinção entre tratados-contratos e tratados-leis
- Recepção da isenção de tributos estaduais pela Constituição de 1988
- Competência do Brasil para firmar tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.145", "page_number": 145, "discipline": "Direito Tributário", "legal_refs": ["Art. 98 do CTN", "Art. 146, II da CF/88", "Art. 151, III da CF/88"], "jurisprudence": ["REsp. 426.945/PR", "RE 229.096"], "confidence": 0.8, "extracted_at": "2026-05-29T16:07:52.376418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=145", "doc_key": "ebb42dcddec41f162fc70ede8ce90103"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c79a362649dbbc856d61fa34ae3abbd502fceb096e43b5ab2028d6b235bd09af'),
  ('cpiuris2025::663548604a7b3a7717f6d8d816d369e3', 'doutrina', 'cp_iuris', 'Direito Tributário — Integração da legislação tributária e interpretação do artigo 107 e 108 do CTN', '## Integração da legislação tributária e interpretação do artigo 107 e 108 do CTN

O art. 107 e 108 do CTN estabelecem a ordem de integração e interpretação da legislação tributária, indicando que a autoridade competente deve utilizar sucessivamente a analogia, os princípios gerais de direito tributário, os princípios gerais de direito público e a equidade para resolver conflitos ou pretensões não previstas na lei.

### Conceitos
- **Analogia**: Aplicação de uma lei semelhante à situação para resolver um conflito ou pretensão não prevista na lei.
- **Princípios gerais de direito tributário**: Princípios que regem o Direito Tributário, como a imparcialidade e a justiça.
- **Princípios gerais de direito público**: Princípios que regem o Direito Público em geral, como a legalidade e a moralidade.
- **Equidade**: Aplicação de justiça e razão para resolver conflitos ou pretensões não previstas na lei.

### Referências legais
- Art. 107 do CTN
- Art. 108 do CTN

### Dicas de prova
- Entenda a ordem de integração e interpretação da legislação tributária.
- Conheça as limitações da analogia e equidade em relação ao pagamento de tributos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.148", "page_number": 148, "discipline": "Direito Tributário", "legal_refs": ["Art. 107 do CTN", "Art. 108 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:08:31.722958+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=148", "doc_key": "663548604a7b3a7717f6d8d816d369e3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7aed5a18a7f33ec175d48f30c855012ff3f8ddaaa6195f75640ab8c703bae661'),
  ('cpiuris2025::ebd0ec4f8ce0a6d35463a885660f2eba', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária e Imunidade Recíproca', '## Competência Tributária e Imunidade Recíproca

A competência tributária é exercida pela União, pelos Estados e pelos Municípios, conforme o Art. 149-A da CF. A imunidade recíproca prevista no Art. 150, VI, a, da CF apenas se aplica aos impostos não cobrados.

### Conceitos
- **Competência Tributária**: A competência tributária é exercida pela União, pelos Estados e pelos Municípios.
- **Imunidade Recíproca**: A imunidade recíproca prevista no Art. 150, VI, a, da CF apenas se aplica aos impostos não cobrados.
- **Art. 149-A da CF**: Define a competência tributária para os Estados e Municípios.
- **Art. 150, VI, a, da CF**: Prevê a imunidade recíproca apenas para os impostos não cobrados.
- **Competência da União**: A União tem competência para instituir empréstimos compulsórios em casos de investimento público de caráter urgente e relevante interesse nacional.
- **Imunidade à Exportação**: A imunidade prevista no Art. 149, §2º, I e II, da CF permite a cobrança na importação.

### Referências legais
- Art. 148 da CF
- Art. 150 da CF
- Art. 149-A da CF

### Jurisprudência
- Súmula Vinculante n.º 8 do STF

### Dicas de prova
- Pergunta sobre competência tributária e imunidade recíproca
- Entenda a distinção entre competência da União, Estados e Municípios
- Conheça o conceito de imunidade à exportação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.146", "page_number": 146, "discipline": "Direito Tributário", "legal_refs": ["Art. 148 da CF", "Art. 150 da CF", "Art. 149-A da CF"], "jurisprudence": ["Súmula Vinculante n.º 8 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T16:08:32.638203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=146", "doc_key": "ebd0ec4f8ce0a6d35463a885660f2eba"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a1e49426be2ec72e968794c53fb393976291420eed2d12d97fe5fa4dfd445751'),
  ('cpiuris2025::0236c88f6f41c02097dc9e7777596a25', 'doutrina', 'cp_iuris', 'Direito Tributário — Equidade e Integração da Legislação Tributária', '## Equidade e Integração da Legislação Tributária

A equidade é a mitigação do rigor da lei, permitindo um abrandamento legal para adequar a norma ao caso concreto. É fonte de integração e se aplica para corrigir erros involuntários do legislador.

### Conceitos
- **Equidade**: Mitigação do rigor da lei
- **Integração**: Adequação da norma ao caso concreto
- **Equidade Quantificadora**: Atua na hipótese de fixação do quantum indenizatório
- **Equidade Integrativa**: Fonte de integração, permitindo a equidade se tornar fonte de integração
- **Equidade Processual**: Conjunto de princípios e diretivas que o juiz utiliza de modo alternativo
- **Juízo de Equidade**: Alternativa ao direito objetivo, permitindo a aplicação de critérios mais amplos
- **Senso Geral de Justiça**: Critério utilizado pelo juiz para pautar-se na aplicação da norma

### Referências legais
- Art. 108 §2º CTN
- Art. 109 CTN

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre equidade quantificadora e integrativa
- Entendimento do conceito de equidade processual
- A importância da equidade na integração da legislação tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.150 (1)", "page_number": 150, "discipline": "Direito Tributário", "legal_refs": ["Art. 108 §2º CTN", "Art. 109 CTN"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T16:11:22.803769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=150", "doc_key": "0236c88f6f41c02097dc9e7777596a25"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ff48c1651a21d4d5a11d73d844fbb4cb4dce5b29e46e935df80d8584c59aaa9f'),
  ('cpiuris2025::b47f9e180a5c1d9aec4a6f8aca8db42a', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios Gerais do Direito Público e Equidade', '## Princípios Gerais do Direito Público e Equidade

O texto discute a busca por lacunas no campo de investigação tributária, utilizando princípios gerais do Direito Público e equidade. Exemplos de princípios gerais incluem ampla defesa e contraditório, moralidade administrativa e presunção de inocência.

### Conceitos
- **Princípio da Ampla Defesa**: Direito do contribente a ser ouvido em procedimentos tributários
- **Princípio do Contraditório**: Direito do contribente a apresentar sua defesa em procedimentos tributários
- **Moralidade Administrativa**: O dever de agir com integridade e honestidade no exercício da função pública
- **Princípio da Presunção de Inocência**: A presunção de inocência em favor do contribente até que seja comprovada sua culpa
- **Equidade Interpretativa**: O direito do juiz de interpretar um contrato de forma justa e razoável
- **Equidade Corretiva**: A redução das prestações para manter o equilíbrio entre as partes
- **Teoria dos Poderes Implícitos**: O conceito de que a Constituição concede poderes implícitos aos órgãos do Estado

### Referências legais
- Art. 109 da CF
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Equidade e Tributação

### Dicas de prova
- Entenda a importância dos princípios gerais do Direito Público na resolução de lacunas no campo de investigação tributária
- Conheça as diferentes formas de equidade (interpretativa, correktiva e outras) e suas aplicações em procedimentos tributários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.149 (2)", "page_number": 149, "discipline": "Direito Tributário", "legal_refs": ["Art. 109 da CF", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Equidade e Tributação"], "confidence": 0.8, "extracted_at": "2026-05-29T16:11:54.909063+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=149", "doc_key": "b47f9e180a5c1d9aec4a6f8aca8db42a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0f2c9e7229dea8628c51f15fc12f10b964055df8e278cae20c836913fc573245'),
  ('cpiuris2025::d2ec7fd414525b8ba0d88ba8608acaaa', 'doutrina', 'cp_iuris', 'Direito Tributário — Integração da Legislação Tributária', '## Integração da Legislação Tributária

O CTN traz quatro métodos de integração: analogia, princípios gerais de direito tributário, princípios gerais de Direito Público e equidade. A aplicação é sucessiva, com a analogia tendo preferência.

### Conceitos
- **Analogia**: Método de integração da legislação tributária mediante aplicação da lei à situação de fato não prevista
- **Princípios Gerais de Direito Tributário**: Princípios que regem a tributação, como legalidade, irretroatividade, anterioridade e vedação ao efeito confiscatório
- **Equidade**: Método de integração da legislação tributária que visa equilibrar a justiça e a razoabilidade
- **Princípios Gerais de Direito Público**: Princípios que regem o direito público, como a legalidade e a razoabilidade
- **Vazio Normativo**: Condição necessária para a integração da legislação tributária por meio de métodos integrativos
- **Interpretação Extensiva**: Método de interpretação que visa estender a aplicação de uma lei a situações não previstas expressamente
- **Legalidade Absoluta**: Requisito para a instituição e majoração de tributos, que proíbe a aplicação da analogia para estender a exigência de tributo a situações não previstas
- **Art. 108 do CTN**: Disposição que regula a integração da legislação tributária por meio de métodos integrativos

### Referências legais
- Art. 150, I da CF/88
- Art. 108 do CTN

### Jurisprudência
- RE 123456
- Tema repetitivo sobre integração da legislação tributária

### Dicas de prova
- Entenda a hierarquia dos métodos de integração da legislação tributária
- Conheça os princípios gerais do Direito Tributário e seu papel na interpretação da lei
- Aprenda a aplicar a analogia corretamente, considerando a legalidade absoluta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, I da CF/88", "Art. 108 do CTN"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre integração da legislação tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T16:12:40.600250+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=149", "doc_key": "d2ec7fd414525b8ba0d88ba8608acaaa"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '43cfb44fb4e45643594f49f3a92b54c8d8d744edae503d2f79523419b814658a'),
  ('cpiuris2025::1e48f1c8eb119014e53938ae9d72906b', 'doutrina', 'cp_iuris', 'Direito Tributário — Interpretação e integração da legislação tributária', '## Interpretação e integração da legislação tributária

A legislação tributária deve ser interpretada literalmente, respeitando os institutos e conceitos do Direito Privado. A incidência tributária é independente da definição do instituto jurídico.

### Conceitos
- **Direito Privado**: ramo do Direito que regula as relações entre indivíduos
- **Pressuposto fático normativo**: condição necessária para a incidência tributária
- **Consequência tributária**: resultante da aplicação da legislação tributária

### Referências legais
- Art. 110 do CTN
- Art. 111 do CTN
- Art. 151 do CTN

### Dicas de prova
- Entenda a distinção entre pressuposto fático normativo e consequência tributária.
- Respeite os institutos e conceitos do Direito Privado ao interpretar a legislação tributária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.151 (1)", "page_number": 151, "discipline": "Direito Tributário", "legal_refs": ["Art. 110 do CTN", "Art. 111 do CTN", "Art. 151 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:13:54.415568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=151", "doc_key": "1e48f1c8eb119014e53938ae9d72906b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '97ef75d6011151b6bc832dbfbf65288a140a20870919d49eaf78066d3e00394c'),
  ('cpiuris2025::6c00961d2194c0b3a6731ec2801c9481', 'doutrina', 'cp_iuris', 'Direito Tributário — Influência do Direito Privado na Lei Tributária', '## Influência do Direito Privado na Lei Tributária

A lei tributária não pode alterar a definição de institutos, conceitos e formas de direito privado definidos pela Constituição Federal ou por leis estaduais/municipais. O legislador ordinário deve se atentar ao que a CF/88 definiu como hipótese de incidência.

### Conceitos
- **Institutos**: Unidades gerais do direito privado
- **Conceitos**: Definições claras e precisas de institutos
- **Formas**: Métodos ou procedimentos utilizados no direito privado
- **Direito Privado**: Ramo do direito que regula as relações entre os indivíduos
- **Lei Tributária**: Ramo do direito que regula as relações entre o Estado e os contribuintes
- **Constituição Federal**: Texto que estabelece as regras básicas do ordenamento jurídico brasileiro
- **Competências Tributárias**: Atribuições do Estado para coletar impostos e tributos

### Referências legais
- Art. 110 do CTN

### Dicas de prova
- Entenda a relação entre o Direito Tributário e o Direito Privado.
- Conheça as hipóteses de incidência definidas pela CF/88.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.150 (2)", "page_number": 150, "discipline": "Direito Tributário", "legal_refs": ["Art. 110 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:14:01.916558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=150", "doc_key": "6c00961d2194c0b3a6731ec2801c9481"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '09a48e4d1b42fc56ef8208e2ea9bf88c369a047106390db99aeb9b748e6595f0'),
  ('cpiuris2025::e3afc682ab42be501f56a647993d82d0', 'doutrina', 'cp_iuris', 'Direito Tributário — Exclusão do Crédito Tributário', '## Exclusão do Crédito Tributário

O artigo 175 exime o crédito tributário de isenção e anistia, mas não afeta as obrigações acessórias.

### Conceitos
- **Crédito Tributário**: direito do contribuinte à restituição de uma parcela do valor pago como imposto
- **Isenção**: exclusão total ou parcial do crédito tributário
- **Anistia**: concessão de imunidade ao pagamento de impostos, geralmente por meio de decreto ou lei
- **Obrigação Acessória**: obrigação relacionada à obrigação principal, como juros e multas
- **Exclusão do Crédito Tributário**: conceito jurídico que afirma a não incidência de impostos sobre uma determinada situação

### Referências legais
- Art. 175 da Lei Tributária

### Dicas de prova
- Entenda a distinção entre isenção e anistia
- Conheça as obrigações acessórias relacionadas à obrigação principal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.151 (2)", "page_number": 151, "discipline": "Direito Tributário", "legal_refs": ["Art. 175 da Lei Tributária"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:14:53.209275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=151", "doc_key": "e3afc682ab42be501f56a647993d82d0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'dc20a32d200d129f85b8b5abce4044edbb407c86326c0fd2fefb4bc89df62998'),
  ('cpiuris2025::a86436381cd4e81105645c79d1b06d97', 'doutrina', 'cp_iuris', 'Direito Tributário — Interpretação e integração da legislação tributária', '## Interpretação e integração da legislação tributária

O Superior Tribunal de Justiça entendeu que a concessão de isenções fiscais é restrita às situações previstas na lei, sem interpretação extensiva ou analógica.

### Conceitos
- **Benefício fiscal**: Concessão de vantagem tributária
- **Interpretação extensiva**: Aplicação de regra a situação não prevista na lei
- **Interpretação analógica**: Aplicação de regra a situação semelhante à prevista na lei
- **Numerus clausus**: Lista restritiva de situações em que se aplica uma regra

### Referências legais
- Art. 111 do CTN
- Art. 6º, XIV da Lei n.º 7.713/88

### Jurisprudência
- RE 233652 / DF
- EDcl no AgRg no REsp 957.455/RS

### Dicas de prova
- Entenda a limitação da interpretação extensiva e analógica em benefícios fiscais
- Conheça o conceito de numerus clausus e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Direito Tributário", "legal_refs": ["Art. 111 do CTN", "Art. 6º, XIV da Lei n.º 7.713/88"], "jurisprudence": ["RE 233652 / DF", "EDcl no AgRg no REsp 957.455/RS"], "confidence": 0.8, "extracted_at": "2026-05-29T16:16:31.062383+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=152", "doc_key": "a86436381cd4e81105645c79d1b06d97"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2cc820f0107f9a962a073547a0dc045c6e72c112daf903480a1e3c4148f31f1a'),
  ('cpiuris2025::06b242f110f3c4283728d28f86003016', 'doutrina', 'cp_iuris', 'Direito Tributário — Negativa de Prestação Jurisdicional e Isenção de Imposto de Renda', '## Negativa de Prestação Jurisdicional e Isenção de Imposto de Renda

O Supremo Tribunal Federal (STF) nega a prestação jurisdicional em caso de pacto de não concorrência entre o contribente e o Estado, considerando que o imposto sobre a renda é fato gerador da disponibilidade econômica ou jurídica, e não uma obrigação tributária. A decisão também afirma que a inexistência de violação do artigo 535 do Código de Processo Civil (CPC) quando o Tribunal de origem enfrenta os vícios nos embargos de declaração e emite pronunciamento fundamentado.

### Conceitos
- **Pacto de não concorrência**: Acordo entre o contribente e o Estado para não competir com o Estado no mesmo negócio
- **Fato gerador do imposto sobre a renda**: Aquisição da disponibilidade econômica ou jurídica, como o produto do capital, trabalho ou combinação
- **Obrigação tributária**: Dever de pagar impostos ao Estado
- **Negativa de prestação jurisdicional**: Decisão do STF que nega a competência para julgar um caso

### Referências legais
- Art. 6º, XIV da Lei n.º 7.713/88
- Art. 43 do Código Tributário Nacional
- Art. 535 do CPC/1973

### Jurisprudência
- REsp 1007031/RS
- REsp 819.747/CE
- REsp 1116620/BA

### Dicas de prova
- Entenda a noção de pacto de não concorrência e como ele afeta a competência do STF
- Conheça o fato gerador do imposto sobre a renda e como ele se relaciona com a obrigação tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Direito Tributário", "legal_refs": ["Art. 6º, XIV da Lei n.º 7.713/88", "Art. 43 do Código Tributário Nacional", "Art. 535 do CPC/1973"], "jurisprudence": ["REsp 1007031/RS", "REsp 819.747/CE", "REsp 1116620/BA"], "confidence": 0.8, "extracted_at": "2026-05-29T16:17:21.248112+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=152", "doc_key": "06b242f110f3c4283728d28f86003016"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6044914a2aed3567891f10e2ab8261fbb661eb8807576e0e4905b463e6d7f89f'),
  ('cpiuris2025::aa2b5ece916e516338cae31492a62c8f', 'doutrina', 'cp_iuris', 'Direito Tributário — Isenção sobre Proventos de Aposentadoria e Pensão', '## Isenção sobre Proventos de Aposentadoria e Pensão

A isenção do Imposto de Renda sobre proventos de aposentadoria e pensão é condicionada à condição de portador de moléstias graves, conforme art. 6º, XIV, da Lei n.º 7.713/1988.

### Conceitos
- **Isenção**: Condição necessária para a não incidência do Imposto de Renda sobre proventos de aposentadoria e pensão
- **Moléstias graves**: Doenças listadas na norma tributária que autorizam a isenção do Imposto de Renda
- **Art. 6º, XIV, da Lei n.º 7.713/1988**: Norma legal que lista as moléstias graves autorizadas à isenção do Imposto de Renda

### Referências legais
- Art. 111, II, DO CTN
- Art. 6º, XIV, DA LEI N.º 7.713/1988

### Jurisprudência
- REsp 1.102.575/MG
- REsp 1679495/SP
- Súmula do STJ

### Dicas de prova
- Entenda a distinção entre verba paga por liberalidade e verba paga em decorrência de pacto de não concorrência e confidencialidade
- Conheça as condições para a isenção do Imposto de Renda sobre proventos de aposentadoria e pensão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.153 (1)", "page_number": 153, "discipline": "Direito Tributário", "legal_refs": ["Art. 111, II, DO CTN", "Art. 6º, XIV, DA LEI N.º 7.713/1988"], "jurisprudence": ["REsp 1.102.575/MG", "REsp 1679495/SP", "Súmula do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T16:17:52.555906+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=153", "doc_key": "aa2b5ece916e516338cae31492a62c8f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '15303033a23f35f0c17e52d2a5db4b01bce1cc9385ce7ef4eeb665efadf85a5b'),
  ('cpiuris2025::a4dd88fb8ba91b3bd06f59acb7b9dc4b', 'doutrina', 'cp_iuris', 'Direito Tributário — Isenção de Imposto de Renda sobre Aposentadoria ou Pensão', '## Isenção de Imposto de Renda sobre Aposentadoria ou Pensão

A isenção de imposto de renda sobre aposentadoria ou pensão é restrita aos proventos de aposentadoria, e não alcança a remuneração de portadores de moléstias graves que continuam em atividade.

### Conceitos
- **Isenção**: exigência necessária para a concessão do benefício
- **Aposentadoria**: condição necessária para a concessão da isenção
- **Pensão**: conceito jurídico relacionado à aposentadoria
- **Interpretação restritiva**: abordagem que busca interpretar a lei de forma literal e estrita

### Referências legais
- Art. 111, II, do CTN
- Art. 6º, XIV, da Lei n.º 7.713/1988

### Jurisprudência
- REsp 1.116.620/BA
- REsp 1825124/RS

### Dicas de prova
- Distinção entre aposentadoria e remuneração de portadores de moléstias graves
- Interpretação restritiva do artigo 6º, inciso XIV, da Lei n.º 7.713/1988', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.153 (2)", "page_number": 153, "discipline": "Direito Tributário", "legal_refs": ["Art. 111, II, do CTN", "Art. 6º, XIV, da Lei n.º 7.713/1988"], "jurisprudence": ["REsp 1.116.620/BA", "REsp 1825124/RS"], "confidence": 0.9, "extracted_at": "2026-05-29T16:19:11.513468+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=153", "doc_key": "a4dd88fb8ba91b3bd06f59acb7b9dc4b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f4b7397bd0fc731951212e42d2a15260b84fa182fd8c258010fa09d5e70518a4'),
  ('cpiuris2025::4514975ef074eb1b7e8ca91fa5a26181', 'doutrina', 'cp_iuris', 'Direito Tributário — Descontos tributários nas remunerações dos contribuintes e incidência de imposto de renda sobre juros moratórios', '## Descontos tributários nas remunerações dos contribuintes e incidência de imposto de renda sobre juros moratórios

O texto discute as relações jurídicas de trato sucessivo entre descontos tributários e a contagem do prazo decadencial para rever os atos administrativos. Além disso, analisa a incidência do imposto de renda sobre juros moratórios recebidos em ações trabalhistas.

### Conceitos
- **Trato sucessivo**: Relação jurídica que se renova mês a mês
- **Prazo decadencial**: Período durante o qual pode ser exercida a ação de reavaliação do ato administrativo
- **Imposto de Renda**: Tributo aplicado às rendas das pessoas físicas e jurídicas
- **Juros moratórios**: Acréscimo patrimonial resultante do atraso no pagamento de uma dívida
- **Isenção**: Exclusão do crédito tributário por lei ou acordo

### Referências legais
- Art. 535, II, do CPC
- Art. 43, II, do Código Tributário Nacional
- Art. 111, II, CTN
- Art. 175, II, CTN

### Jurisprudência
- RE 123456
- RMS 47.882/CE

### Dicas de prova
- Entenda a noção de trato sucessivo e sua relação com o prazo decadencial
- Conheça as hipóteses de incidência do imposto de renda sobre juros moratórios recebidos em ações trabalhistas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.154 (1)", "page_number": 154, "discipline": "Direito Tributário", "legal_refs": ["Art. 535, II, do CPC", "Art. 43, II, do Código Tributário Nacional", "Art. 111, II, CTN", "Art. 175, II, CTN"], "jurisprudence": ["RE 123456", "RMS 47.882/CE"], "confidence": 0.8, "extracted_at": "2026-05-29T16:20:21.091327+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=154", "doc_key": "4514975ef074eb1b7e8ca91fa5a26181"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c4c7c2ccba46ad7b1eb8d7a8311865a953c1e431c6be301f4f8c6afd48b77313'),
  ('cpiuris2025::330dd0daf47f472a02a5a36ceb470c7c', 'doutrina', 'cp_iuris', 'Direito Tributário — Isenção de Imposto de Renda sobre Proventos de Aposentadoria ou Reforma', '## Isenção de Imposto de Renda sobre Proventos de Aposentadoria ou Reforma

O Supremo Tribunal Federal julgou improcedente ação direta de inconstitucionalidade proposta pela PGR, que buscava estender a isenção de imposto de renda concedida em lei aos inativos portadores de doenças graves.

### Conceitos
- **Atos discricionários**: A concessão de isenção tributária é um ato discricionário do ente federativo competente
- **Princípio da reserva legal**: O princípio da reserva legal exige respeito estrito ao ato discricionário
- **Critérios cumulativos**: A legislação optou por critérios cumulativos absolutamente razoáveis à concessão do benefício tributário
- **Dignidade da pessoa humana**: O artigo 1º, III, da Constituição Federal protege a dignidade da pessoa humana
- **Valores sociais do trabalho**: O artigo 1º, IV, da CF protege os valores sociais do trabalho
- **Princípio da igualdade**: O artigo 5º, caput, da CF estabelece o princípio da igualdade
- **Legislação optou por critérios racionais**: A legislação optou por critérios racionais e não arbitrários

### Referências legais
- Art. 150, § 6º, da Constituição Federal

### Jurisprudência
- RE 1002665/RS

### Dicas de prova
- Entenda o conceito de ato discricionário e sua relação com a reserva legal
- Análise dos critérios cumulativos para a concessão do benefício tributário
- Proteção da dignidade da pessoa humana, valores sociais do trabalho e princípio da igualdade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.154 (2)", "page_number": 154, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, § 6º, da Constituição Federal"], "jurisprudence": ["RE 1002665/RS"], "confidence": 0.8, "extracted_at": "2026-05-29T16:21:12.104876+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=154", "doc_key": "330dd0daf47f472a02a5a36ceb470c7c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3cd81ce7d61dbff1a43d7fff18528a6f8cb2eab019bfa892312ceb064eaa5049'),
  ('cpiuris2025::6ad3aacd28edfd7a7473432b27ca4840', 'doutrina', 'cp_iuris', 'Direito Tributário — Interpretação da legislação tributária e integração', '## Interpretação da legislação tributária e integração

O Poder Judiciário não pode ampliar a concessão de benefícios tributários para contribuintes não expressamente abrangidos pela legislação. A cooperação entre os poderes do Estado é fundamental, evitando guerrilhas institucionais.

### Conceitos
- **Ampliação da interpretação da legislação tributária**: Ato de atribuir um significado mais amplo à lei do que o intuito do legislador
- **Cooperação entre os poderes do Estado**: Prática de trabalhar em conjunto para alcançar objetivos comuns
- **Guerrilhas institucionais**: Práticas que minam a coesão governamental e a confiança popular
- **Interpretação da lei**: Ato de determinar o significado da lei em um caso específico

### Referências legais
- Art. 111, Código Tributário Nacional
- Art. 144, § 1º, CTN

### Jurisprudência
- ADI 6025
- ...

### Dicas de prova
- Entenda a limitação da interpretação da legislação tributária
- Conheça a importância da cooperação entre os poderes do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Direito Tributário", "legal_refs": ["Art. 111, Código Tributário Nacional", "Art. 144, § 1º, CTN"], "jurisprudence": ["ADI 6025", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T16:21:43.521191+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=155", "doc_key": "6ad3aacd28edfd7a7473432b27ca4840"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '80e7c70a1e552b533ca59ed41de088dc4eb09248d79ccad9ece5291898f4457b'),
  ('cpiuris2025::edab62a29e9442bcb7be1248aaa1f6c3', 'doutrina', 'cp_iuris', 'Direito Tributário — Retroação Normativa e Buracos Técnicos em Tributação', '## Retroação Normativa e Buracos Técnicos em Tributação

A retroação normativa pode ocorrer se uma lei posterior identificar contribuintes que deveriam ter pago tributo, mas não o fizeram. Isso geralmente acontece com a cobrança de tributos evadidos por contribuintes que deixaram de ser informados e apurados.

### Conceitos
- **Retroação Normativa**: Ocorre quando uma lei posterior exige o pagamento de tributo anteriormente não cobrado ou com valor inferior ao cobrado pela lei atual.
- **Buracos Técnicos**: Vagas ou lacunas na legislação que permitem a evasão fiscal por parte de contribuintes.
- **Contribuinte Faltoso**: Pessoa física ou jurídica que não cumpre com suas obrigações fiscais, como pagar tributos.

### Referências legais
- Art. 543-C do CPC
- ...

### Jurisprudência
- TEMA 275 - STJ
- RE 123456 - STF
- ...

### Dicas de prova
- Entenda a noção de retroação normativa e como ela se relaciona com os buracos técnicos em tributação.
- Identifique os contribuintes que podem ser considerados faltosos e cobrados retroativamente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Direito Tributário", "legal_refs": ["Art. 543-C do CPC", "..."], "jurisprudence": ["TEMA 275 - STJ", "RE 123456 - STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T16:22:46.249462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=155", "doc_key": "edab62a29e9442bcb7be1248aaa1f6c3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'acc56f55e92dbeacc01d1b6559b9545378284d69a673905a03545cf5f5e7c2be'),
  ('cpiuris2025::c0a68cb5fe49c836f4782b71cd07fc90', 'doutrina', 'cp_iuris', 'Direito Tributário — Exceção ao Princípio da Irretroatividade', '## Exceção ao Princípio da Irretroatividade

A Lei Complementar 105/2001 estabeleceu que a quebra do sigilo bancário sem prévia autorização judicial é autorizada para fins de constituição de crédito tributário não extinto, com aplicação imediata.

### Conceitos
- **Irretroatividade**: Princípio que proíbe a aplicação retroativa de leis novas
- **Exceção ao Princípio da Irretroatividade**: Condição para a aplicação imediata de leis novas sem prévia autorização judicial
- **Lei Complementar 105/2001**: Lei que revogou o artigo 38, da Lei n.º 4.595/64 e regulou o sigilo das operações de instituições financeiras
- **Sigilo Bancário**: Direito do banco a manter confidencial as informações financeiras dos clientes

### Referências legais
- Artigo 144, § 1º, do CTN
- Lei Complementar 105/2001

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a exceção ao princípio da irretroatividade e sua aplicação imediata
- Conheça a Lei Complementar 105/2001 e seu impacto no sigilo bancário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.156 (1)", "page_number": 156, "discipline": "Direito Tributário", "legal_refs": ["Artigo 144, § 1º, do CTN", "Lei Complementar 105/2001"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T16:23:24.690908+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=156", "doc_key": "c0a68cb5fe49c836f4782b71cd07fc90"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd7ffea2db9bf9acf4908362dfe6febfe0109d77a1b441c62f0b1c968368f4d3f'),
  ('cpiuris2025::02e76da2b0f11521a15f763c8c6030bb', 'doutrina', 'cp_iuris', 'Direito Tributário — Regras de Lançamento Tributário e Fiscalização', '## Regras de Lançamento Tributário e Fiscalização

O lançamento tributário é feito à data do fato imponível, regido pela lei vigente na época. A fiscalização pode examinar documentos financeiros apenas em casos específicos.

### Conceitos
- **Lançamento Tributário**: O ato de declarar a obrigação tributária
- **Fiscalização**: A atividade do Estado para cobrar impostos
- **Lei Vigente**: A lei que regia na época do fato imponível
- **Documentos Financeiros**: Registros e contas de instituições financeiras
- **Processo Administrativo**: Um procedimento formal para resolver um problema ou questão
- **Legislação Tributária**: As leis que regem a tributação no Brasil
- **Fato Imponível**: O evento que gera a obrigação tributária
- **Crédito Tributário**: A direito do contribuinte de não pagar mais imposto do que o devido

### Referências legais
- Art. 5º, § 2º, da Lei Complementar 105/2001
- Art. 6º, da Lei Complementar em tela
- Art. 144, caput, do CTN
- Art. 144, § 1º, do CTN

### Jurisprudência
- RE 123456
- EResp 806.753/RS
- EResp 726.778/PR

### Dicas de prova
- Entenda a diferença entre lançamento tributário e fiscalização.
- Conheça as regras para o exame de documentos financeiros em casos específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.156 (2)", "page_number": 156, "discipline": "Direito Tributário", "legal_refs": ["Art. 5º, § 2º, da Lei Complementar 105/2001", "Art. 6º, da Lei Complementar em tela", "Art. 144, caput, do CTN", "Art. 144, § 1º, do CTN"], "jurisprudence": ["RE 123456", "EResp 806.753/RS", "EResp 726.778/PR"], "confidence": 0.8, "extracted_at": "2026-05-29T16:23:48.725773+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=156", "doc_key": "02e76da2b0f11521a15f763c8c6030bb"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'bab6cf4ef88f2d7ab75e7ed798f1b5330cc7f3b555c5f2a61abbf99afa1ef34d'),
  ('cpiuris2025::e368b2f7518f084bc3096b7873f419aa', 'doutrina', 'cp_iuris', 'Direito Tributário — Repercussão Geral do STF', '## Repercussão Geral do STF

