  ('cpiuris2025::8aeb5e2edb08ea057d6c3f439ea4efe1', 'doutrina', 'cp_iuris', 'Direito Tributário — Interpretação e integração da legislação tributária', '## Interpretação e integração da legislação tributária

A Administração Tributária tem a faculdade de criar instrumentos para identificar o patrimônio, rendimentos e atividades econômicas do contribuinte, respeitados os direitos individuais. O sigilo bancário não é absoluto e deve ser mitigado em casos de ilicitude.

### Conceitos
- **Pessoalidade**: A capacidade contributiva do contribuinte
- **Capacidade Contributiva**: O direito do Estado de exigir contribuições de quem tem patrimônio e rendimentos
- **Moralidade**: O princípio que obriga a Administração Tributária a agir com integridade e justiça
- **Intimidade das Pessoas**: O direito do indivíduo à privacidade e segurança pessoal
- **Fiscalização Tributária**: A ação da Administração Tributária para exigir contribuições

### Referências legais
- Art. 145, § 1º da Constituição Federal
- Art. 6º da Lei Complementar 105/2001

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre o sigilo absoluto e o sigilo relativizado
- Entender a noção de moralidade na legislação tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.157 (1)", "page_number": 157, "discipline": "Direito Tributário", "legal_refs": ["Art. 145, § 1º da Constituição Federal", "Art. 6º da Lei Complementar 105/2001"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T16:26:42.528261+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=157", "doc_key": "8aeb5e2edb08ea057d6c3f439ea4efe1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '17ca9499878ca8f95a11466747e59cff67acac4a6fa7a6e6340adeb4bd5730b6'),
  ('cpiuris2025::cd73d1714f9f6db47a8532dd037cbe94', 'doutrina', 'cp_iuris', 'Direito Tributário — Interpretação e integração da legislação tributária', '## Interpretação e integração da legislação tributária

O texto discute a interpretação do direito ao sigilo bancário em relação à exigência de pagamento de tributos, destacando a igualdade, autonomia individual e autogoverno coletivo.

### Conceitos
- **Direito ao sigilo bancário**: O direito do cidadão de ter suas atividades e informações bancárias livres de ingerências ou ofensas
- **Autonomia individual**: O direito do cidadão de ter liberdade para tomar decisões sobre suas atividades e informações
- **Igualdade**: A satisfação das necessidades coletivas do Povo, garantida pelo pagamento de tributos
- **Autogoverno coletivo**: O poder do Estado soberano para governar seu próprio território e tomar decisões sobre suas necessidades
- **Requisitos objetivos**: Regras estabelecidas pela legislação tributária para a requisição de informação pela Administração Tributária

### Referências legais
- Art. 6º da Lei Complementar 105/01
- Art. 144, §1º, do Código Tributário Nacional

### Dicas de prova
- Entenda a relação entre o direito ao sigilo bancário e o pagamento de tributos.
- Destaque a igualdade como um princípio fundamental da legislação tributária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.158 (1)", "page_number": 158, "discipline": "Direito Tributário", "legal_refs": ["Art. 6º da Lei Complementar 105/01", "Art. 144, §1º, do Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:27:04.836487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=158", "doc_key": "cd73d1714f9f6db47a8532dd037cbe94"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '39f4bb793c9ceae48bb8efa4ae4349ea2badf1ad499c2bb7fc6412c4455ba822'),
  ('cpiuris2025::ff9628a26a9feeab845d693769647a5d', 'doutrina', 'cp_iuris', 'Direito Tributário — Integração e interpretação da legislação tributária', '## Integração e interpretação da legislação tributária

Questões de concursos sobre integração e interpretação da legislação tributária

### Conceitos
- **interpretação literal**: interpreta-se literalmente a legislação tributária
- **interpretação sistemática**: é sistemática a interpretação no que se refere à exclusão do crédito tributário
- **analogia**: poderá o Fisco valer-se da analogia para exigir tributo por fato semelhante não descrito na hipótese de incidência
- **equidade**: o emprego da equidade pode resultar na dispensa de pagamento de tributo devido quando da integração da legislação tributária
- **alteração de conceitos**: na interpretação da lei tributária é permitida a alteração de conceitos e institutos de direito privado utilizados para definir o fato gerador, desde que a alteração se faça por lei e que resulte em maior arrecadação tributária

### Referências legais
- Art. 144, §1º, do CTN
- Lei n.º 10.174/01

### Jurisprudência
- RE 601314
- Súmula N STF

### Dicas de prova
- Pegar a distinção entre interpretação literal e sistemática
- Entender o conceito de analogia no contexto tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.158 (2)", "page_number": 158, "discipline": "Direito Tributário", "legal_refs": ["Art. 144, §1º, do CTN", "Lei n.º 10.174/01"], "jurisprudence": ["RE 601314", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T16:29:06.038512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=158", "doc_key": "ff9628a26a9feeab845d693769647a5d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c6f1d183d2016567e78a3426d7c03167729da2ac2b47a84157a3b4ac01d66bfd'),
  ('cpiuris2025::c124039a9674985ce786071706f8962b', 'doutrina', 'cp_iuris', 'Direito Tributário — Interpretação e integração da legislação tributária', '## Interpretação e integração da legislação tributária

A equidade pode resultar na dispensa do tributo devido em casos de integração da legislação tributária.

### Conceitos
- **Equidade**: Uso da justiça e da razão para corrigir distorções tributárias
- **Analogia**: Aplicação de regras semelhantes a casos não previstos em lei
- **Moratória**: Prazo concedido para o pagamento de dívidas
- **Anistia**: Concessão de imunidade tributária por decisão do Poder Executivo
- **Parcelamento**: Divisão de uma obrigação em partes menores
- **Dispensa do cumprimento de obrigações acessórias**: Exceção ao pagamento de tributos não previstos em lei

### Referências legais
- Art. 109, § 4º, do Código Tributário Nacional

### Dicas de prova
- Entenda a diferença entre equidade e analogia
- Conheça as hipóteses de moratória, anistia, parcelamento e dispensa do cumprimento de obrigações acessórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.160", "page_number": 160, "discipline": "Direito Tributário", "legal_refs": ["Art. 109, § 4º, do Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:29:30.732569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=160", "doc_key": "c124039a9674985ce786071706f8962b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7470178cfef6ba36b65e65d912846cf5308872ce3f271b92ed2ff602f07118d6'),
  ('cpiuris2025::7db6a4508d7321b59a0d4b1f5102d203', 'doutrina', 'cp_iuris', 'Direito Tributário — Interpretação e integração da legislação tributária', '## Interpretação e integração da legislação tributária

Resumo do texto sobre interpretação das leis tributárias, incluindo analogia, equidade, aplicação de lei a atos pretéritos e definição de infrações.

### Conceitos
- **Analogia**: Não pode resultar na exigência de tributo não previsto em lei
- **Equidade**: Não pode resultar na dispensa do pagamento de tributo devido
- **Aplicação de lei a atos pretéritos**: A lei aplica-se a ato ou fato pretérito, salvo quando se tratar de ato não definitivamente julgado que deixe de defini-lo como infração
- **Definição de infrações**: A lei tributária define infrações, ou lhe comina penalidades, interpreta-se da maneira mais favorável ao acusado em caso de dúvida quanto à capitulação legal do fato
- **Outorga de isenção**: Interpreta-se literalmente a legislação tributária que disponha sobre outorga de isenção

### Referências legais
- Art. 109 do Código Tributário Nacional

### Dicas de prova
- Perguntas que envolvem interpretação das leis tributárias podem ser resolvidas com base nas regras de analogia e equidade.
- A aplicação de lei a atos pretéritos é feita com base na interpretação literal da legislação tributária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.159", "page_number": 159, "discipline": "Direito Tributário", "legal_refs": ["Art. 109 do Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:29:56.844616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=159", "doc_key": "7db6a4508d7321b59a0d4b1f5102d203"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6874ea182f9906f7c3447f603840c5b6254a203f31535f6b308a1d8ecd0c6ce8'),
  ('cpiuris2025::c58b0e496382fa9b3ca024d6deb1d621', 'doutrina', 'cp_iuris', 'Direito Tributário — Interpretação e integração da legislação tributária', '## Interpretação e integração da legislação tributária

A legislação tributária deve ser interpretada literalmente, exceto em casos de isenção ou suspensão do crédito tributário. A equidade não pode resultar na dispensa do pagamento de tributo devido.

### Conceitos
- **Analogia**: Método utilizado para aplicar a lei a situações não previstas
- **Equidade**: Princípio que visa justiça e equilíbrio em casos de dúvida interpretativa
- **Interpretação literal**: Método utilizado para aplicar a lei sem interpretação excessiva ou flexível

### Referências legais
- Art. 108 § 1º do CTN
- Art. 108 § 2º do CTN
- Art. 111 do CTN

### Dicas de prova
- Entenda a diferença entre analogia e equidade
- Conheça os artigos 108 e 111 do CTN
- Interprete a legislação tributária de forma literal, exceto em casos de isenção ou suspensão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.162", "page_number": 162, "discipline": "Direito Tributário", "legal_refs": ["Art. 108 § 1º do CTN", "Art. 108 § 2º do CTN", "Art. 111 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:31:49.637987+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=162", "doc_key": "c58b0e496382fa9b3ca024d6deb1d621"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '1f92c7bd5a407e68819bc09d84337e43f9ecc11a197ade07dc90602497d23488'),
  ('cpiuris2025::d2b23fd05034517b70f9f94d7c1e551f', 'doutrina', 'cp_iuris', 'Direito Tributário — Dispensa do cumprimento de obrigações tributárias acessórias', '## Dispensa do cumprimento de obrigações tributárias acessórias

O art. 151 do CTN suspende a exigibilidade do crédito tributário, incluindo o parcelamento como uma das causas.

### Conceitos
- **Parcelamento**: Método pelo qual o sujeito passivo divide o valor devido em parcelas menores
- **Impugnação**: Ação do sujeito passivo para contestar a notificação do lançamento tributário
- **Recurso de ofício**: Ação da autoridade administrativa para revisar o lançamento tributário
- **Iniciativa de ofício**: Ação da autoridade administrativa para alterar o lançamento tributário sem a necessidade de impugnação ou recurso

### Referências legais
- Art. 151 do CTN

### Dicas de prova
- Entenda a diferença entre vigência e eficácia das leis tributárias
- Conheça as causas que suspendem a exigibilidade do crédito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.163 (1)", "page_number": 163, "discipline": "Direito Tributário", "legal_refs": ["Art. 151 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:31:58.647699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=163", "doc_key": "d2b23fd05034517b70f9f94d7c1e551f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '5bd1b383f2a0323efc122c967f5e97f7956535df1b5f5dd81f0b1bfeb7090a18'),
  ('cpiuris2025::ced5744c88b13c1adc7515c3082cb11b', 'doutrina', 'cp_iuris', 'Direito Tributário — Interpretação e integração da legislação tributária', '## Interpretação e integração da legislação tributária

A interpretação da legislação tributária deve ser feita literalmente, salvo em casos de analogia ou equidade. A lei não pode alterar conceitos de direito privado definidos pela Constituição Federal.

### Conceitos
- **Analogia**: Uso da semelhança para aplicar a legislação tributária a casos não previstos
- **Equidade**: Uso de critérios justos e razoáveis para resolver dúvidas na interpretação da lei
- **Interpretação literal**: Aplicação estrita e não interpretativa da legislação tributária

### Referências legais
- Art. 111 do CTN
- Art. 108, § 1º do CTN
- Art. 108, § 2º do CTN
- Art. 106 do CTN
- Art. 112 do CTN

### Jurisprudência
- RE 123456
- Tema repetitivo sobre interpretação da legislação tributária

### Dicas de prova
- Perguntas que exigem a aplicação da analogia ou equidade devem ser resolvidas com base nos princípios gerais de direito tributário
- A interpretação literal é a regra geral, mas a analogia e equidade podem ser usadas em casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.161", "page_number": 161, "discipline": "Direito Tributário", "legal_refs": ["Art. 111 do CTN", "Art. 108, § 1º do CTN", "Art. 108, § 2º do CTN", "Art. 106 do CTN", "Art. 112 do CTN"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre interpretação da legislação tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T16:32:05.183270+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=161", "doc_key": "ced5744c88b13c1adc7515c3082cb11b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f8c03752463562caf0041018160458f9da4a804fc995f39c5ef9344314b8b797'),
  ('cpiuris2025::f397d61c848bef4841dcfbc55c3676c0', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento por Homologação e Lançamento Reporte', '## Lançamento por Homologação e Lançamento Reporte

O lançamento por homologação ocorre com a expressa homologação da autoridade administrativa, enquanto o lançamento reporte-se à data do fato gerador e se regem pela lei vigente.

### Conceitos
- **Lançamento por Homologação**: Ocorre com a expressa homologação da autoridade administrativa
- **Lançamento Reporte**: Se regem pela lei vigente à data do fato gerador

### Referências legais
- Art. 150 do CTN
- Art. 144 do CTN

### Dicas de prova
- Entenda a diferença entre lançamento por homologação e lançamento reporte.
- Conheça o prazo de homologação e as hipóteses de extinção do crédito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.163 (2)", "page_number": 163, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 do CTN", "Art. 144 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:33:39.423355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=163", "doc_key": "f397d61c848bef4841dcfbc55c3676c0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7ca38f754d19e034756d6f2bf0e1e343eae81713995a8b18e66b1d306d662187'),
  ('cpiuris2025::0432671d29d3f14d792e83026babbc6b', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento e Responsabilidade Tributária', '## Lançamento e Responsabilidade Tributária

O lançamento administrativo é vinculada e obrigatória, sob pena de responsabilidade funcional. O sujeito passivo pode impugnar a notificação do crédito tributário.

### Conceitos
- **Lançamento Administrativo**: Procedimento administrativo para verificar o fato gerador da obrigação correspondente
- **Responsabilidade Funcional**: Sob pena de responsabilidade funcional, a atividade administrativa de lançamento é vinculada e obrigatória
- **Sujeito Passivo**: Pessoa física ou jurídica que deve pagar o tributo
- **Impugnação**: Reclamação apresentada pelo sujeito passivo contra a notificação do crédito tributário

### Referências legais
- Art. 142 do CTN
- Art. 145 do CTN

### Dicas de prova
- Entenda o conceito de lançamento administrativo e sua vinculação obrigatória
- Conheça a responsabilidade funcional e as consequências de não cumprir com ela', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.164", "page_number": 164, "discipline": "Direito Tributário", "legal_refs": ["Art. 142 do CTN", "Art. 145 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:34:03.026420+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=164", "doc_key": "0432671d29d3f14d792e83026babbc6b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '54eee4a4f841f4ff64e5acabc298fe97d37732d701d3654c5c1d460fa30fac75'),
  ('cpiuris2025::c41ea71af932bfd4da24503cf30c7547', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Tributária Principal e Acessória', '## Obrigação Tributária Principal e Acessória

A obrigação tributária é gerada pelo fato da vida de auferir renda, que se subsome a uma norma jurídica. O contribuinte tem o dever fundamental de pagar o imposto, enquanto a pessoa jurídica ou física que não tem esse dever pode ser considerada como denunciante e contribuir com as informações.

### Conceitos
- **Fato Gerador**: O fato da vida que gera uma obrigação tributária
- **Dever Fundamental de Pagamento**: O dever do contribuinte de pagar o imposto sobre a renda auferida
- **Dever de Contribuir com a Tributação**: A capacidade de colaborar com as informações tributárias, não confundido com o dever fundamental de pagamento

### Referências legais
- Art. 110 da Lei 10.865/2004

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre o dever fundamental de pagar tributo e o dever de contribuir com a tributação
- Conheça o fato gerador da obrigação tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.165 (1)", "page_number": 165, "discipline": "Direito Tributário", "legal_refs": ["Art. 110 da Lei 10.865/2004"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T16:34:21.946484+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=165", "doc_key": "c41ea71af932bfd4da24503cf30c7547"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'cfdc1bbb7ccded1d38308bfd48504c3d8837607f5c2c7a1a03cd64538ee78302'),
  ('cpiuris2025::d881cf653898d4d28269d53025eb1ba9', 'doutrina', 'cp_iuris', 'Direito Tributário — Dever de Contribuição e Política Tributária', '## Dever de Contribuição e Política Tributária

O dever de contribuir é considerado em conta na política tributária, com ênfase na justiça e isonomia. O Estado de direito democrático fornece o fundamento constitucional para os deveres de colaboração e pagamento de tributos.

### Conceitos
- **Dever de Contribuição**: O dever de contribuir é considerado em conta na política tributária
- **Política Tributária**: A política tributária deve ser justa e isônoma
- **Estado de Direito Democrático**: Fornece o fundamento constitucional para os deveres de colaboração e pagamento de tributos
- **Dever Fundamental de Pagamento de Tributos**: Baseado no Estado de direito democrático
- **Colaboração com a Administração Tributária**: Obrigação de contribuir para a viabilização, facilitar e simplificar a tributação

### Referências legais
- Art. 195 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de dever de contribuição e sua importância na política tributária
- Destaque a justiça e isonomia na política tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.165 (2)", "page_number": 165, "discipline": "Direito Tributário", "legal_refs": ["Art. 195 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T16:35:58.978119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=165", "doc_key": "d881cf653898d4d28269d53025eb1ba9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a1221937c0ab72f61556acc6f18f7c79126232551b4f3d7aedab67402471b29f'),
  ('cpiuris2025::783f96f045ee04b2406f6fdb4437fb09', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Acessória e Legislação Tributária', '## Obrigação Acessória e Legislação Tributária

As obrigações acessórias são autônomas em relação às principais, podendo ser instituídas por atos infralegais. Sua fonte normativa é a legislação tributária.

### Conceitos
- **Obrigação Acessória**: Prestação que não faz parte do fato gerador do tributo, mas decorre da legislação tributária
- **Legislação Tributária**: Normas que regem a criação e cobrança dos tributos
- **Atos Infralegais**: Ato administrativo que não tem valor de lei, mas pode instituir obrigações acessórias

### Referências legais
- Art. 113, § 2º do CTN

### Dicas de prova
- Entenda a distinção entre obrigação principal e acessória
- Conheça a fonte normativa das obrigações acessórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.166 (2)", "page_number": 166, "discipline": "Direito Tributário", "legal_refs": ["Art. 113, § 2º do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:36:13.950619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=166", "doc_key": "783f96f045ee04b2406f6fdb4437fb09"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0fa2db3fbe5090da3fb97ca3cf0846ce5434813bd7a28656a8c8cba8d72c8e2d'),
  ('cpiuris2025::f4e0f51f6441834b0e0b4a6b297fe030', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Tributária Acessória', '## Obrigação Tributária Acessória

A legislação tributária pode criar deveres autônomos para pessoas jurídicas ou naturais em posições estratégicas para a arrecadação e fiscalização dos tributos, que são obrigações acessórias autônomas relativamente ao dever de pagar tributos.

### Conceitos
- **Obrigação Tributária Acessória**: Dever autônomo criado pela legislação tributária para pessoas jurídicas ou naturais em posições estratégicas para a arrecadação e fiscalização dos tributos.
- **Obrigação Tributária Principal**: Paga-se ao cofre público, seja a título de tributo, seja a título de sancionamento por uma conduta infratora
- **Multidestinatário**: Pessoa jurídica ou natural que pode ser obrigada a pagar multas tributárias sem estar necessariamente contribuinte

### Referências legais
- Art. 96 do CTN

### Dicas de prova
- Entenda a distinção entre obrigação tributária principal e acessória
- Conheça o conceito de multidestinatário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.166 (1)", "page_number": 166, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:36:21.258424+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=166", "doc_key": "f4e0f51f6441834b0e0b4a6b297fe030"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b702db05d8a6e252637c35c83f0cfc4216c0d26daf4e780fc8e36fb1ab801744'),
  ('cpiuris2025::0a3e21565514a9cbcac8c4b8660402a1', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Tributária Principal e Acessória', '## Obrigação Tributária Principal e Acessória

A obrigação tributária divide-se em principal e acessória. A principal surge com o fato gerador, tem por objeto o pagamento de tributo ou penalidade pecuniária e extingue-se juntamente com o crédito dela decorrente. A acessória decorre da legislação tributária, tem por objeto as prestações positivas ou negativas previstas no interesse da arrecadação ou da fiscalização dos tributos.

### Conceitos
- **Obrigação Tributária Principal**: Decorre da lei, tem por objeto o pagamento de tributo ou penalidade pecuniária
- **Obrigação Tributária Acessória**: Decorre da legislação, trata-se de obrigações de fazer ou não fazer, convertível em obrigação principal
- **Fato Gerador**: O evento que gera a obrigação tributária principal
- **Lei Tributária**: A legislação que regula os tributos e as penalidades pecuniárias

### Referências legais
- Art. 113 do CTN

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre obrigação principal e acessória
- Conheça o fato gerador e sua relação com a obrigação tributária principal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.167 (1)", "page_number": 167, "discipline": "Direito Tributário", "legal_refs": ["Art. 113 do CTN"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T16:36:57.717133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=167", "doc_key": "0a3e21565514a9cbcac8c4b8660402a1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0aa48b939ea5a35bc9d26272aa38dfb344e80235d490b58c30565e9affd2bd27'),
  ('cpiuris2025::f64252c988b19c24ef3fda2df51e4789', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Tributária Acessória e Principal', '## Obrigação Tributária Acessória e Principal

A obrigação acessória tributária se transforma em principal por meio de autuação do auto de infração, que prevê uma multa a ser paga. Exemplos incluem emitir nota fiscal e tolerar fiscalização.

### Conceitos
- **Obrigação Tributária Acessória**: obrigação tributária que se transforma em principal por meio de autuação do auto de infração
- **Auto de Infração**: documento que autoriza o Poder Público a autuar o contribuinte
- **Multa**: quantidade a ser paga como sanção por não cumprimento da obrigação tributária

### Referências legais
- Art. 136 da Lei 9.532/1997

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre obrigação principal e acessória
- Conheça o auto de infração e sua importância na transformação da obrigação acessória em principal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.167 (2)", "page_number": 167, "discipline": "Direito Tributário", "legal_refs": ["Art. 136 da Lei 9.532/1997"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T16:39:01.637519+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=167", "doc_key": "f64252c988b19c24ef3fda2df51e4789"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e307c8ceb2ac51db2611dee227add688ef0bb7d322e6d7127a8f280f910d5edd'),
  ('cpiuris2025::1f9f847c5c6e62bbaf3d32a4f7f0c882', 'doutrina', 'cp_iuris', 'Direito Tributário — Sujeito passivo da obrigação principal', '## Sujeito passivo da obrigação principal

A pessoa obrigada ao pagamento de um tributo ou de uma penalidade pecuniária é o sujeito passivo da obrigação principal. O sujeito passivo pode ser contribuinte, quando tem relação pessoal e direta com a situação que constitui o fato gerador, ou responsável, quando sua obrigação decorre de disposição expressa de lei.

### Conceitos
- **Contribuinte**: Pessoa obrigada ao pagamento de tributo ou penalidade pecuniária, com relação pessoal e direta à situação que constitui o fato gerador.
- **Responsável**: Pessoa obrigada a pagar tributo ou penalidade pecuniária, sem ter relação pessoal e direta com a situação que constitui o fato gerador, mas cuja obrigação decorre de disposição expressa de lei.
- **Obrigação principal**: Obrigação tributária que decorre do fato gerador, que é devida diretamente pelo sujeito passivo

### Referências legais
- Art. 121 do CTN
- Art. 128 do CTN

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre contribuinte e responsável tributário
- Entender a relação entre o sujeito passivo e o fato gerador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.169 (1)", "page_number": 169, "discipline": "Direito Tributário", "legal_refs": ["Art. 121 do CTN", "Art. 128 do CTN"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T16:39:35.921803+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=169", "doc_key": "1f9f847c5c6e62bbaf3d32a4f7f0c882"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '1599c50ea8c7281584f840d56dd8f029a9f1150efd37a3cf10f15082a258fa99'),
  ('cpiuris2025::dde151427de842b92166f5200f160886', 'doutrina', 'cp_iuris', 'Direito Tributário — Sujeitos da relação jurídico-tributária', '## Sujeitos da relação jurídico-tributária

A obrigação tributária é contraída entre um sujeito ativo e um sujeito passivo. O sujeito ativo é a pessoa jurídica de direito público que tem a competência para exigir o cumprimento da obrigação, enquanto o sujeito passivo é a pessoa jurídica de direito público ou física que deve cumprir a obrigação.

### Conceitos
- **Sujeito ativo**: Pessoa jurídica de direito público que tem a competência para exigir o cumprimento da obrigação tributária
- **Sujeito passivo**: Pessoa jurídica de direito público ou física que deve cumprir a obrigação tributária
- **Capacidade tributária**: A capacidade de um ente político para exigir o cumprimento de uma obrigação tributária

### Referências legais
- Art. 113, § 1º, CTN
- Art. 119, CTN
- Art. 120, CTN

### Dicas de prova
- Entenda a distinção entre sujeito ativo e sujeito passivo na relação jurídico-tributária
- Conheça a capacidade tributária e como ela é exercida pelos entes políticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.168", "page_number": 168, "discipline": "Direito Tributário", "legal_refs": ["Art. 113, § 1º, CTN", "Art. 119, CTN", "Art. 120, CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:39:35.924149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=168", "doc_key": "dde151427de842b92166f5200f160886"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ad0098b119487630aff58f6e849d433e2cf45c8336814cfe50f9263fdf8a798c'),
  ('cpiuris2025::cf587d76c6423bf319b71b8ec14e4c26', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária', '## Responsabilidade Tributária

O responsável tributário é o que será acionado em execução fiscal, sendo ele o próprio ou terceiro responsável pela obrigação tributária.

### Conceitos
- **Responsável Tributário**: Pessoa física ou jurídica que é acionada em execução fiscal
- **Obrigação Acessória**: Obligação relacionada à obrigação principal, devida junto com o tributo

### Referências legais
- Art. 128 do CTN

### Dicas de prova
- Distinção entre responsável tributário e terceiro responsável pela obrigação
- Importância da atuação do art. 128 do CTN', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.169 (2)", "page_number": 169, "discipline": "Direito Tributário", "legal_refs": ["Art. 128 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:40:39.870982+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=169", "doc_key": "cf587d76c6423bf319b71b8ec14e4c26"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '617d502de62e148bb265e07b9dbd0e86b46944062f7220150369ef8e6b0023e8'),
  ('cpiuris2025::b087797c8f6978d8d8e9d876634d9a91', 'doutrina', 'cp_iuris', 'Direito Tributário — domicílio tributário e situação dos bens', '## domicílio tributário e situação dos bens

A regra para definir o domicílio tributário é o lugar da situação dos bens, não a residência do contribente.

### Conceitos
- **Domicílio Tributário**: O local onde o contribente deve pagar impostos
- **Situação dos Bens**: A situação jurídica dos bens do contribente
- **Residência**: O lugar onde o contribente vive permanentemente

### Referências legais
- Art. 113 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre residência e domicílio tributário
- A situação dos bens é o fator determinante para definir o domicílio tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.171 (2)", "page_number": 171, "discipline": "Direito Tributário", "legal_refs": ["Art. 113 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T16:42:08.427003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=171", "doc_key": "b087797c8f6978d8d8e9d876634d9a91"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '73f894ec412fefd1aa11913a51be874050bf27e40a7aec6f4b1e84fccf769ea4'),
  ('cpiuris2025::1f5caf25cf91d3c526f20f69f96e72f6', 'doutrina', 'cp_iuris', 'Direito Tributário — Domicílio Tributário', '## Domicílio Tributário

O contribuinte ou responsável tributário eleita o seu domicílio tributário, mas na falta de eleição, as regras do art. 127 do CTN são aplicadas.

### Conceitos
- **Domicílio Tributário**: o local onde se considera que o contribuinte ou responsável tributário tem sua sede ou residência
- **Residência Habitual**: o lugar onde a pessoa física habita regularmente
- **Sede de Pessoa Jurídica**: o local onde a pessoa jurídica tem sua sede ou principal atividade
- **Domicílio Tributário da Pessoa Física**: o lugar onde a pessoa física tem sua residência habitual, ou se considera que está situada
- **Dificuldade na Arrecadação**: se o domicílio eleito pelo contribuinte dificulta a arrecadação do tributo

### Referências legais
- Art. 127 do CTN

### Dicas de prova
- Lembre-se de que o domicílio tributário é eleito pelo contribuinte ou responsável, mas na falta de eleição, as regras do art. 127 do CTN são aplicadas.
- Diferencie entre residência e domicílio, pois estas são conceitos diferentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direito Tributário", "legal_refs": ["Art. 127 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:42:27.827315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=171", "doc_key": "1f5caf25cf91d3c526f20f69f96e72f6"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f014502cd61ac79628db5408143b53d9b256e9bd06a43286b3331c43260c340c'),
  ('cpiuris2025::633776e0cb071ff15b4fce348a6327ca', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Tributária e Solidariedade', '## Obrigação Tributária e Solidariedade

Discute-se a obrigação tributária e a solidariedade, destacando que as pessoas com interesse comum na situação que constitui o fato gerador da obrigação principal são solidariamente obrigadas. Além disso, é explicado o entendimento do STJ sobre a não possibilidade de impugnar o lançamento de IPTU por parte do locatário.

### Conceitos
- **Sujeito passivo**: A pessoa obrigada às prestações que constituem o seu objeto
- **Solidariedade passiva**: Obrigação tributária compartida por pessoas com interesse comum na situação que constitui o fato gerador da obrigação principal
- **Interesse comum**: Condição necessária para a solidariedade passiva
- **Benefício de ordem**: Não é permitido o benefício de ordem na solidariedade passiva

### Referências legais
- Art. 122 do CTN
- Art. 123 do CTN
- Art. 124 do CTN
- Art. 125 do CTN

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a noção de sujeito passivo e solidariedade passiva
- Conheça o entendimento do STJ sobre a não possibilidade de impugnar o lançamento de IPTU por parte do locatário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.170", "page_number": 170, "discipline": "Direito Tributário", "legal_refs": ["Art. 122 do CTN", "Art. 123 do CTN", "Art. 124 do CTN", "Art. 125 do CTN"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T16:42:33.232020+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=170", "doc_key": "633776e0cb071ff15b4fce348a6327ca"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7638c99480f88bc8badba6bd7e8e9e98148b0e2f3e2e6984c45210314c81e70c'),
  ('cpiuris2025::0810c20cc986b4fae2fb7aba35766147', 'doutrina', 'cp_iuris', 'Direito Tributário — Condição suspensiva e fato gerador de tributo', '## Condição suspensiva e fato gerador de tributo

Regra para a ocorrência do fato gerador de tributo em negócios jurídicos com condições suspensivas.

### Conceitos
- **Fato gerador**: O evento que gera a obrigação tributária
- **Condição suspensiva**: Cláusula que suspende o efetivo da obrigação

### Referências legais
- Art. 29 do Código Tributário Nacional

### Dicas de prova
- Distinção entre fato gerador e condição suspensiva
- Importância de considerar a condição suspensiva para o fato gerador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Direito Tributário", "legal_refs": ["Art. 29 do Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:43:52.624740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=172", "doc_key": "0810c20cc986b4fae2fb7aba35766147"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fbd2f012bebc8aeb3cb6affcfc9650fde90a8bdea47f07909916deb28172b222'),
  ('cpiuris2025::625718a33a7bc590c3ee359e6a1a052b', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Tributária', '## Obrigação Tributária

Resumo do texto sobre obrigação tributária, incluindo fato gerador e sua definição.

### Conceitos
- **Fato Gerador**: Situação que impõe a prática ou abstenção de ato para configurar obrigação principal.
- **Obrigação Principal**: Sanção administrativa imposta pela lei tributária
- **Obrigação Acessória**: Situação que impõe a prática ou abstenção de ato para configurar obrigação principal, mas não é sanção administrativa.

### Referências legais
- Art. 110 da Lei nº 5.172/1970

### Dicas de prova
- Entenda a distinção entre fato gerador e obrigação principal.
- Conheça as hipóteses de fato gerador, como situação jurídica ou negócio jurídico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.172 (1)", "page_number": 172, "discipline": "Direito Tributário", "legal_refs": ["Art. 110 da Lei nº 5.172/1970"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:44:17.085867+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=172", "doc_key": "625718a33a7bc590c3ee359e6a1a052b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '09a01d689c41627119a4a674810e1384305d7af9c8787734461757ad01a4ab05'),
  ('cpiuris2025::03578669c4ff263b45604e0c9dac144c', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Tributária Principal', '## Obrigação Tributária Principal

A obrigação tributária principal surge com o fato gerador, considerando-se a validade jurídica dos atos praticados pelos contribuintes. O fato gerador é necessário e suficiente para sua ocorrência.

### Conceitos
- **Fato Gerador**: Situação definida em lei como necessária e suficiente à sua ocorrência
- **Obrigação Tributária Principal**: Obrigação que surge com a ocorrência do fato gerador
- **Validade Jurídica dos Atos Praticados**: Considerada ao interpretar a definição legal do fato gerador

### Referências legais
- Art. 114 e 115 do CTN

### Dicas de prova
- Entenda a distinção entre obrigação principal e acessória
- Interprete a definição legal do fato gerador considerando-se a validade jurídica dos atos praticados pelos contribuintes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.173", "page_number": 173, "discipline": "Direito Tributário", "legal_refs": ["Art. 114 e 115 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:44:38.431724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=173", "doc_key": "03578669c4ff263b45604e0c9dac144c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd33f615a92a83cc7c88f90def08344d329a7ab1f92ec010b83aed102df64d909'),
  ('cpiuris2025::d4e33153018d30dd778e8179eb71a9c3', 'doutrina', 'cp_iuris', 'Direito Tributário — Fato Gerador da Obrigação Principal', '## Fato Gerador da Obrigação Principal

Define que o fato gerador é a situação necessária e suficiente para a ocorrência da obrigação principal, de acordo com a lei.

### Conceitos
- **Fato Gerador**: Situação necessária e suficiente para a ocorrência da obrigação principal
- **Obrigação Principal**: Dever tributário principal
- **Lei**: Fonte do direito que define a situação

### Referências legais
- Art. 114 Código Tributário Nacional

### Dicas de prova
- Entenda o conceito de fato gerador e sua relação com a obrigação principal
- Leia atentamente a lei para identificar a situação necessária e suficiente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.174 (2)", "page_number": 174, "discipline": "Direito Tributário", "legal_refs": ["Art. 114 Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:45:46.737807+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=174", "doc_key": "d4e33153018d30dd778e8179eb71a9c3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b20381c2c389d5ecff23c0959783cfbff052b77b7c79d85e157aa8d843ade516'),
  ('cpiuris2025::86634d83f8989135b49ac677dce93268', 'doutrina', 'cp_iuris', 'Direito Tributário — Ocorrência do Fato Gerador e Obigação Tributária', '## Ocorrência do Fato Gerador e Obigação Tributária

A Lei define o fato gerador como ocorrido desde que existam as circunstâncias materiais necessárias para produzir seus efeitos, seja em situação de fato ou jurídica.

### Conceitos
- **Fato Gerador**: Ocorrencia do fato que gera a obrigação tributária
- **Obrigação Tributária**: O dever de pagar tributo ou penalidade pecuniária
- **Obrigação Acessória**: Prestações positivas ou negativas previstas na legislação tributária

### Referências legais
- Art. 116 do CTN
- Art. 117 do CTN
- Art. 118 do CTN

### Dicas de prova
- Entenda a diferença entre fato gerador e obrigação tributária
- Conheça as regras para a ocorrência do fato gerador em situações de fato ou jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.174 (1)", "page_number": 174, "discipline": "Direito Tributário", "legal_refs": ["Art. 116 do CTN", "Art. 117 do CTN", "Art. 118 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:46:10.279297+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=174", "doc_key": "86634d83f8989135b49ac677dce93268"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ea0bef19edc38506c819056320cc3fb9e08e08758fc0d4e48f46a57c88f9fd52'),
  ('cpiuris2025::9f856d742d32b0a82deff5697dc05a1a', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Tributária', '## Obrigação Tributária

A obrigação tributária é considerada principal ou acessória, com a principal surgindo com o fato gerador e tendo como objeto o pagamento de tributo. A solidariedade das obrigações tributárias é mencionada no artigo 124 do CTN.

### Conceitos
- **Obrigação Tributária**: A obrigação tributária é considerada principal ou acessória
- **Fato Gerador**: O fato que gera a obrigação tributária
- **Sujeito Passivo das Obrigações Tributárias**: A pessoa jurídica ou física responsável pelo pagamento do tributo

### Referências legais
- Art. 117 do CTN
- Art. 123 do CTN
- Art. 113 do CTN
- Art. 124 do CTN

### Dicas de prova
- Entenda a distinção entre principal e acessória das obrigações tributárias
- Conheça o fato gerador e seu papel na geração da obrigação tributária
- A solidariedade das obrigações tributárias é um conceito importante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.175", "page_number": 175, "discipline": "Direito Tributário", "legal_refs": ["Art. 117 do CTN", "Art. 123 do CTN", "Art. 113 do CTN", "Art. 124 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:47:05.197501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=175", "doc_key": "9f856d742d32b0a82deff5697dc05a1a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ba51543b3e33341e0364138c4a4e2f8b275d0233b8e547b890e2f13ff07a3b33'),
  ('cpiuris2025::e208dfd8ecbdf3c07cba82d8c889e4c5', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária', '## Responsabilidade Tributária

A responsabilidade tributária pode ser atribuída a uma terceira pessoa vinculada ao fato gerador da obrigação, de acordo com o art. 128 do CTN.

### Conceitos
- **Substituição tributária**: Atribuição de responsabilidade pelo crédito tributário a uma terceira pessoa vinculada ao fato gerador
- **Transferência tributária**: A transferência da responsabilidade tributária para outra pessoa após a ocorrência do fato gerador
- **Substituição progressiva**: Substituição tributária ''para frente'' (ou progressiva), onde a lei impõe ao substituto a responsabilidade pelo recolhimento de obrigações oriundas de fatos geradores futuros
- **Responsabilidade tributária vinculada**: A responsabilidade tributária é vinculada ao fato gerador da obrigação

### Referências legais
- Art. 128 do CTN

### Dicas de prova
- Entenda a diferença entre substituição progressiva e regressiva
- Conheça os exemplos de substituição tributária em diferentes tipos de tributos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.177", "page_number": 177, "discipline": "Direito Tributário", "legal_refs": ["Art. 128 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:48:05.333531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=177", "doc_key": "e208dfd8ecbdf3c07cba82d8c889e4c5"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'dd7e2a7594b3c113b35a487d27669a74f6c61fab9dade578e35e9abd729ea8c6'),
  ('cpiuris2025::142ffc960c8b1209a767591932fe4099', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária', '## Responsabilidade Tributária

A responsabilidade tributária ocorre quando o fato gerador ainda não aconteceu, mas a lei permite o recolhimento do tributo com base no presumido. Se não acontecer o fato gerador, a pessoa jurídica terá direito à restituição da quantia paga.

### Conceitos
- **Fato Gerador**: O evento que gera a obrigação tributária
- **Presumido**: O valor do fato gerador presumido, usado para recolhimento do tributo antes de ocorrer o fato real
- **Responsabilidade Tributária**: A obrigação de pagar o tributo, mesmo que o fato gerador ainda não tenha acontecido
- **Substituição Tributária**: O processo pelo qual um contribuinte assume a responsabilidade por um tributo que deveria ser pago por outro

### Referências legais
- Art. 150, § 7º, da CF/88

### Dicas de prova
- Entenda a diferença entre fato gerador e presumido
- Conheça o conceito de responsabilidade tributária e substituição tributária
- Aprenda a aplicar as regras de responsabilidade tributária em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, § 7º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:48:25.078562+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=178", "doc_key": "142ffc960c8b1209a767591932fe4099"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f75399a2d87e7493e6f5e2e359419c487eecc4af9c2b02e22a0cb75afb9651f2'),
  ('cpiuris2025::7e0d4613366dc63685efc8ee15a75890', 'doutrina', 'cp_iuris', 'Direito Tributário — Substituição Tributária Progressiva e Regressiva', '## Substituição Tributária Progressiva e Regressiva

A substituição tributária progressiva ocorre quando o contribuinte está mais próximo do consumidor, enquanto a regressiva ocorre quando o contribuinte está atrás da cadeia produtiva.

### Conceitos
- **Substituição Tributária Progressiva**: Ocorre quando o contribuinte está mais próximo do consumidor
- **Substituição Tributária Regressiva**: Ocorre quando o contribuinte está atrás da cadeia produtiva

### Referências legais
- Art. 130 do CTN
- CF/88, artigo não especificado

### Dicas de prova
- Entenda a distinção entre progressiva e regressiva
- Conheça a previsão expressa na CF/88 para substituição progressiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Direito Tributário", "legal_refs": ["Art. 130 do CTN", "CF/88, artigo não especificado"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:48:25.642188+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=178", "doc_key": "7e0d4613366dc63685efc8ee15a75890"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '719567c7f871863f7339f16bee250530419107baf1448551011f272432ae1e7b'),
  ('cpiuris2025::72d9f23ea5af5bb59fb530810b588041', 'doutrina', 'cp_iuris', 'Direito Tributário — Sucessão e Responsabilidade Tributária', '## Sucessão e Responsabilidade Tributária

A sucessão ocorre após o falecimento de um contribuinte, transferindo a responsabilidade tributária para o espólio. Os sucessores são responsáveis pelos tributos não recolhidos antes do falecimento.

### Conceitos
- **Espólio**: Responsável tributário após o falecimento de um contribuinte
- **Sucessão**: Transferência da responsabilidade tributária para os sucessores
- **IPTU**: Imposto sobre veículos automotores
- **IPVA**: Imposto sobre veículos automotores - valor aduaneiro
- **IR**: Imposto sobre o Rendimento da Propriedade Imóvel
- **Partilha**: Divisão dos bens do falecido entre os sucessores

### Referências legais
- Art. 113, II, da Lei 10.365/2001

### Dicas de prova
- Entenda a diferença entre espólio e sucessão
- Conheça os tributos que são transferidos para o espólio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.179 (2)", "page_number": 179, "discipline": "Direito Tributário", "legal_refs": ["Art. 113, II, da Lei 10.365/2001"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:50:43.826762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=179", "doc_key": "72d9f23ea5af5bb59fb530810b588041"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'be5b15ebb6a4392459258e6936a64f2de90c5758ffbbe9399f15cf90b2d914bd'),
  ('cpiuris2025::c959486bf3bd20655403c64199fe21fe', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária e Sucessão Empresarial', '## Responsabilidade Tributária e Sucessão Empresarial

O STJ entende que a responsabilidade tributária inclui multas moratórias, e que o sucessor é responsável integralmente pelos tributos devidos e pela multa decorrente.

### Conceitos
- **Responsabilidade Tributária**: obrigação de pagar tributos
- **Sucessão Empresarial**: transmissão da propriedade ou dos ativos de uma empresa para outra
- **Legitimidade Passiva**: direito de ser considerado responsável por um débito tributário
- **Multa Moratória**: multa aplicada ao valor do crédito tributário em caso de atraso

### Referências legais
- Art. 85, § 1°, CPC/2015; Art. 133, CTN; Súmula 282/STF

### Jurisprudência
- REsp 670.224/RJ
- REsp 1684509/SP

### Dicas de prova
- Entenda a responsabilidade tributária e a sucessão empresarial
- Conheça as regras de legitimidade passiva e multa moratória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.180 (1)", "page_number": 180, "discipline": "Direito Tributário", "legal_refs": ["Art. 85, § 1°, CPC/2015; Art. 133, CTN; Súmula 282/STF"], "jurisprudence": ["REsp 670.224/RJ", "REsp 1684509/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T16:50:44.310581+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=180", "doc_key": "c959486bf3bd20655403c64199fe21fe"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '57371c1a0f322b4c338c25ca895ff54a83f1173c3c30b1304edd6899c9be574f'),
  ('cpiuris2025::e9c366c392a36b56be13d3a8386ee7b9', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária', '## Responsabilidade Tributária

O art. 130 do CTN estabelece que os créditos tributários relativos a impostos cujo fato gerador seja a propriedade, domínio útil ou posse de bens imóveis se sub-rogam na pessoa dos respectivos adquirentes, salvo quando conste do título a prova de sua quitação. Exceções incluem a prova da quitação e a aquisição do imóvel em hasta pública.

### Conceitos
- **Sub-rogação**: O processo pelo qual os créditos tributários se transferem para o adquirente de um bem
- **Responsabilidade por transferência**: A responsabilidade do adquirente por dívidas tributárias que já ocorreram antes da aquisição do bem
- **Prova de quitação**: Documentação que demonstra a quitação de tributos, como certidão negativa
- **Hasta pública**: Venda de imóveis realizada por meio de leilão público

### Referências legais
- Art. 130 do Código Tributário Nacional (CTN)

### Jurisprudência
- RE 123456
- Tema repetitivo da responsabilidade tributária

### Dicas de prova
- Entenda a diferença entre responsabilidade por transferência e responsabilidade por sucessão
- Conheça as exceções estabelecidas pelo art. 130 do CTN, como a prova de quitação e a aquisição em hasta pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.179 (1)", "page_number": 179, "discipline": "Direito Tributário", "legal_refs": ["Art. 130 do Código Tributário Nacional (CTN)"], "jurisprudence": ["RE 123456", "Tema repetitivo da responsabilidade tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T16:51:33.901311+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=179", "doc_key": "e9c366c392a36b56be13d3a8386ee7b9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '1bb4ebdfb54fd7670098d0443897f7bae133cf8c274f5738378a52d5a18cb3ac'),
  ('cpiuris2025::147e126e6f6db97c8d70cdc6136c60bd', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade por transformação empresarial', '## Responsabilidade por transformação empresarial

A responsabilidade tributária é estendida às pessoas jurídicas resultantes de fusão, transformação ou incorporação de outras, incluindo casos de cisão. A doutrina entende que a responsabilidade é estendida às empresas que sofreram cisão.

### Conceitos
- **Responsabilidade tributária**: A obrigação de pagar impostos por parte das pessoas jurídicas resultantes de fusão, transformação ou incorporação de outras
- **Sucessão empresarial**: O processo pelo qual uma empresa assume a responsabilidade tributária de outra empresa que foi dissolvida

### Referências legais
- Art. 132 do CTN

### Jurisprudência
- Súmula n.º 554 do STJ

### Dicas de prova
- Entenda a noção de responsabilidade tributária em casos de transformação empresarial
- Conheça o conceito de sucessão empresarial e sua relação com a responsabilidade tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.180 (2)", "page_number": 180, "discipline": "Direito Tributário", "legal_refs": ["Art. 132 do CTN"], "jurisprudence": ["Súmula n.º 554 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T16:52:37.661166+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=180", "doc_key": "147e126e6f6db97c8d70cdc6136c60bd"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '64c010bf483fb84dc1ac296429c2e7fb722898d18204a134535b4918e64824cc'),
  ('cpiuris2025::284e326f5aa9e0e7df2b263c2eda216c', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Subsidiária', '## Responsabilidade Subsidiária

O art. 134 do CTN trata da responsabilidade subsidiária, onde terceiros podem ser responsáveis pelos tributos devidos por outros, em casos de impossibilidade de exigência do cumprimento da obrigação principal.

### Conceitos
- **Responsabilidade Subsidiária**: Terceiros que respondem pelos tributos devidos por outros em casos de impossibilidade
- **Obrigação Principal**: A obrigação principal do contribuinte
- **Impossibilidade Exigência**: Caso em que não é possível exigir o cumprimento da obrigação principal

### Referências legais
- Art. 134 do CTN

### Dicas de prova
- Entenda a noção de responsabilidade subsidiária e seus casos de aplicação
- Diferencie entre responsabilidade subsidiária e responsabilidade solidária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.181 (2)", "page_number": 181, "discipline": "Direito Tributário", "legal_refs": ["Art. 134 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:53:15.277977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=181", "doc_key": "284e326f5aa9e0e7df2b263c2eda216c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'beab1f7b208cf529f7a03a17811cfaa8b2ef4a829697d72d31f7c8631fc9c0ae'),
  ('cpiuris2025::f3ffd00208abcd72298c8de37a354810', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária por Sucessão Empresarial', '## Responsabilidade Tributária por Sucessão Empresarial

A responsabilidade tributária é transferida para o adquirente da empresa, que responde pelos tributos devidos pela contribuinte, com base na continuidade da exploração do comércio ou estabelecimento.

### Conceitos
- **Sucessão Empresarial**: A transferência de uma empresa para outra pessoa jurídica
- **Responsabilidade Tributária**: O dever de pagar tributos devidos pela contribuinte
- **Continuidade da Exploração**: A continuação do comércio ou estabelecimento após a transferência
- **Cessação da Exploração**: O fim do comércio ou estabelecimento após a transferência
- **Responsabilidade Subsidiária**: A responsabilidade do adquirente apenas se ele prosseguir na exploração ou iniciar nova atividade dentro de 6 meses

### Referências legais
- Art. 133, do CTN

### Dicas de prova
- Entenda a noção de sucessão empresarial e sua relação com a responsabilidade tributária
- Identifique as hipóteses em que a responsabilidade tributária não é transferida para o adquirente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.181 (1)", "page_number": 181, "discipline": "Direito Tributário", "legal_refs": ["Art. 133, do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:53:25.501235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=181", "doc_key": "f3ffd00208abcd72298c8de37a354810"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '86ece5dde9f95e9cf8f8280f0641c374b89f285c20cc6a9d0e80d1e55b55f1e6'),
  ('cpiuris2025::f8c8621c18484ada2ed4dd24a843d6f3', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária das Sociedades', '## Responsabilidade Tributária das Sociedades

A responsabilidade tributária de uma sociedade é determinada pela lei do ente tributante, não havendo previsão expressa na Constituição. O sócio cotista não pode responder por débitos da sociedade, mas apenas o administrador ou aquele sócio com poderes de administração.

### Conceitos
- **Responsabilidade Tributária**: Dobro que a lei do ente tributante impõe ao contribuinte
- **Sociedade**: Entidade jurídica que pode ser responsabilizada por débitos tributários
- **Administrador**: Pessoa autorizada a gerir e administrar a sociedade
- **Sócio Cotista**: Membro da sociedade que recebe parte dos lucros

### Referências legais
- Art. 102 do CTN

### Dicas de prova
- Distinção entre administrador e sócio cotista
- Importância de observar as normas gerais de responsabilidade tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.182 (2)", "page_number": 182, "discipline": "Direito Tributário", "legal_refs": ["Art. 102 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T16:55:10.622313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=182", "doc_key": "f8c8621c18484ada2ed4dd24a843d6f3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '47713f46d015b75c95be9fff2d174882714d62bba1afa3627f8093bc64c3425f'),
  ('cpiuris2025::3217c53b4fd516700275769657cfc5a4', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária', '## Responsabilidade Tributária

A responsabilidade tributária é objetiva e independe da intenção ou efetividade dos atos ilícitos, sendo excluída pela denúncia espontânea do contribuinte.

### Conceitos
- **Responsabilidade Tributária**: Objetiva e independe da intenção ou efetividade dos atos ilícitos
- **Denúncia Espontânea**: Exclui a responsabilidade tributária, desde que acompanhada do pagamento do tributo devido e juros de mora
- **Infrações Tributárias**: Descumprimento de obrigações contributivas ou colaboração com a administração tributária

### Referências legais
- Art. 136, do CTN
- Art. 138, do CTN

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre responsabilidade objetiva e subjetiva
- Importância da denúncia espontânea para excluir a responsabilidade tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Direito Tributário", "legal_refs": ["Art. 136, do CTN", "Art. 138, do CTN"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T16:55:28.312755+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=183", "doc_key": "3217c53b4fd516700275769657cfc5a4"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7cf87d7eaae3121847a3bbc5d3bdc343ef545a873a3aa0a9a38f41e01b579d68'),
  ('cpiuris2025::c658de6be830ed358bde12faae602722', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária e Responsabilidade Pessoal', '## Responsabilidade Tributária e Responsabilidade Pessoal

O artigo 135 estabelece a responsabilidade pessoal por atos praticados com excesso de poderes ou infração de lei, contrato social ou estatutos. A responsabilidade é pessoalmente exercida pelos sócios, mandatários, prepostos e empregados.

### Conceitos
- **Responsabilidade Tributária**: obrigação de pagar tributos
- **Responsabilidade Pessoal**: obrigação de responder por atos praticados com excesso de poderes ou infração de lei
- **Sociedades**: pessoas jurídicas que podem ser responsáveis por tributos
- **Mandatários**: pessoas que agem em nome de outra pessoa jurídica
- **Prepostos**: pessoas que agem em nome de outra pessoa jurídica, mas com poderes limitados
- **Empregados**: pessoas que trabalham para uma empresa e podem ser responsáveis por tributos
- **Atos Ultra Vires**: atos praticados com excesso de poderes ou infração de lei

### Referências legais
- Art. 135 do Código Tributário Nacional
- Súmula n.º 430 do STJ
- Súmula n.º 435 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade tributária e responsabilidade pessoal

### Dicas de prova
- Entenda a distinção entre responsabilidade tributária e responsabilidade pessoal
- Conheça as pessoas jurídicas que podem ser responsáveis por tributos (sócios, mandatários, prepostos e empregados)
- Identifique os atos que podem gerar responsabilidade pessoal (atos ultra vires)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Direito Tributário", "legal_refs": ["Art. 135 do Código Tributário Nacional", "Súmula n.º 430 do STJ", "Súmula n.º 435 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade tributária e responsabilidade pessoal"], "confidence": 0.8, "extracted_at": "2026-05-29T16:55:59.785752+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=182", "doc_key": "c658de6be830ed358bde12faae602722"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3ea61d4a41a3b96cb2d8db71ea930b12677d597cca4299b4d6b45d768c8c1b26'),
  ('cpiuris2025::dc69b7c1c76940af856bc7d696887538', 'doutrina', 'cp_iuris', 'Direito Tributário — Denúncia Espontânea', '## Denúncia Espontânea

A denúncia espontânea é um instituto que beneficia a Administração Tributária, preservando-a de custos administrativos. Não se aplica em caso de depósito judicial do tributo devido.

### Conceitos
- **Denúncia Espontânea**: Instituto que beneficia a Administração Tributária, preservando-a de custos administrativos.
- **Depósito Judicial**: Ativo pelo qual o contribuinte paga o tributo devido antes da instauração do procedimento fiscal
- **Custo de Conformidade**: Custo suportado pelo contribuinte para se adequar ao comportamento exigido pelo Fisco

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre denúncia espontânea e depósito judicial.
- Conheça o instituto do custo de conformidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Direito Tributário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T16:57:17.540306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=183", "doc_key": "dc69b7c1c76940af856bc7d696887538"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9b58a6e29d6c55730784ad16ff635709a6283d5fc9d2d7b27ed474e00ac220d9'),
  ('cpiuris2025::10e514da3377ff07797aa539de2d7796', 'doutrina', 'cp_iuris', 'Direito Tributário — Denúncia Espontânea', '## Denúncia Espontânea

A denúncia espontânea é um benefício tributário que pode ser concedido ao contribuinte que paga o tributo devido e os juros de mora, ou depõe a importância arbitrada pela autoridade administrativa. No entanto, não se aplica aos tributos sujeitos a lançamento por homologação regularmente declarados, mas pagos a destempo.

### Conceitos
- **Denúncia Espontânea**: Benefício tributário que concede-se ao contribuinte que paga o tributo devido e os juros de mora
- **Lançamento por Homologação**: Procedimento pelo qual o contribuinte faz praticamente todo o processo de constituição do crédito tributário, exceto homologar o lançamento

### Referências legais
- Art. 138 do CTN
- Art. 151, II do CTN
- Súmula n.º 360 do STJ
- Súmula n.º 208 do extinto TFR

### Jurisprudência
- EREsp 1131090/RJ
- Tema repetitivo

### Dicas de prova
- Diferenciar entre denúncia espontânea e lançamento por homologação
- Entender o requisito do pagamento do tributo devido e dos juros de mora para a caracterização da denúncia espontânea', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.184 (1)", "page_number": 184, "discipline": "Direito Tributário", "legal_refs": ["Art. 138 do CTN", "Art. 151, II do CTN", "Súmula n.º 360 do STJ", "Súmula n.º 208 do extinto TFR"], "jurisprudence": ["EREsp 1131090/RJ", "Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-29T16:58:11.733125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=184", "doc_key": "10e514da3377ff07797aa539de2d7796"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '106cb1260acc9342832e9471ab24d42e44a9e23a2c8c327dca123278fc63bf0c'),
  ('cpiuris2025::6011e784a35fd36710da1d6e7db971b7', 'doutrina', 'cp_iuris', 'Direito Tributário — Denúncia Espontânea e Multa Moratória', '## Denúncia Espontânea e Multa Moratória

A denúncia espontânea é caracterizada pela vontade do contribuinte de pagar antes de iniciado o procedimento fiscal. Para fazer jus ao benefício do art. 138 do CTN, é preciso que a denúncia espontânea seja acompanhada do pagamento devido.

### Conceitos
- **Denúncia Espontânea**: Vontade do contribuinte de pagar antes de iniciado o procedimento fiscal
- **Multa Moratória**: Pena imposta pela lei por atraso no pagamento de tributos
- **Parcelamento**: Divisão do valor do tributo em prestações menores

### Referências legais
- Art. 138 do CTN
- Súmula N.º 208/TFR

### Jurisprudência
- REsp 173.423/RN
- AgRg no AREsp 852.024/MS
- AgRg no REsp 1414966/RJ

### Dicas de prova
- Entenda a diferença entre denúncia espontânea e parcelamento.
- Conheça o entendimento do STF sobre a elisão da multa moratória pela denúncia espontânea.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.184 (2)", "page_number": 184, "discipline": "Direito Tributário", "legal_refs": ["Art. 138 do CTN", "Súmula N.º 208/TFR"], "jurisprudence": ["REsp 173.423/RN", "AgRg no AREsp 852.024/MS", "AgRg no REsp 1414966/RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T16:58:21.193549+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=184", "doc_key": "6011e784a35fd36710da1d6e7db971b7"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fb75d0c12b4e0252fe6e472a8e9e150681f9599dc5ffb434e6fc1aaaa3d347f0'),
  ('cpiuris2025::d9aade7374971adafbdead627dc3b0e0', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária', '## Responsabilidade Tributária

A responsabilidade tributária é regulamentada pela Lei n. 9.430/96, que estabelece as penalidades aplicadas em razão do atraso no pagamento de tributo, incluindo as multas moratórias.

### Conceitos
- **multa moratória**: penalidade aplicada em razão do simples atraso no pagamento de tributo
- **denúncia espontânea**: ação do contribuinte que notifica a Administração Tributária da existência de erro ou omissão na declaração de rendimentos
- **lançamento por homologação**: procedimento utilizado para regularizar débitos tributários

### Referências legais
- Art. 61 da Lei n. 9.430/96

### Jurisprudência
- Súmula n.º 360 do STF
- REsp 1687145/DF
- AREsp 11.340/SC
- AgRg no AREsp 1022862/SP

### Dicas de prova
- Entenda a diferença entre multa moratória e denúncia espontânea
- Conheça o procedimento de lançamento por homologação
- Aplique as regras da Lei n. 9.430/96 às situações específicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.185 (1)", "page_number": 185, "discipline": "Direito Tributário", "legal_refs": ["Art. 61 da Lei n. 9.430/96"], "jurisprudence": ["Súmula n.º 360 do STF", "REsp 1687145/DF", "AREsp 11.340/SC", "AgRg no AREsp 1022862/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T16:59:51.858063+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=185", "doc_key": "d9aade7374971adafbdead627dc3b0e0"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b3677cca2290bd15fd1837ef165c6eaba07f7bce7897c58b0aec43067b0073bb'),
  ('cpiuris2025::30302f17b963e28343405e5d440477e8', 'doutrina', 'cp_iuris', 'Direito Tributário — Multa de Mora e Multas de Ofício', '## Multa de Mora e Multas de Ofício

A lei estabelece multas para os contribuintes que não pagam tributos nos prazos previstos, incluindo a multa de mora calculada à taxa de trinta e três centésimos por cento por dia de atraso.

### Conceitos
- **Multa de Mora**: multa aplicada aos contribuintes que não pagam tributos nos prazos previstos
- **Multas de Ofício**: multas aplicadas pela autoridade sem necessidade de processo judicial, por meio de auto de infração

### Referências legais
- Art. 30 da Lei n.º 9.430/1996

### Dicas de prova
- Entenda a diferença entre multa de mora e multas de ofício
- Conheça o percentual de multa aplicável nos casos de fraude, sonegação ou conluio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.185 (2)", "page_number": 185, "discipline": "Direito Tributário", "legal_refs": ["Art. 30 da Lei n.º 9.430/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:00:04.695399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=185", "doc_key": "30302f17b963e28343405e5d440477e8"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '5f0d193f451ec126951cc4b66e92dc2e950cbac17309b15b6006fc186fe4f961'),
  ('cpiuris2025::ef1b3707df0464e321c097a246a3fd8f', 'doutrina', 'cp_iuris', 'Direito Tributário — Fraude, sonegação e conluio para efeitos tributários', '## Fraude, sonegação e conluio para efeitos tributários

Definições de fraude, sonegação e conluio para fins tributários, conforme a Lei n. 4.502/64.

### Conceitos
- **Fraude**: Ação ou omissão dolosa tendente a impedir ou retardar a ocorrência do fato gerador da obrigação tributária principal.
- **Sonegação**: Toda ação ou omissão dolosa tendente a impedir ou retardar, total ou parcialmente, o conhecimento por parte da autoridade fazendária de certos fatos geradores da obrigação tributária principal.
- **Conluio**: Ajuste doloso entre duas ou mais pessoas naturais ou jurídicas visando qualquer dos efeitos referidos nos arts. 71 e 72.

### Referências legais
- Art. 71 da Lei n. 4.502/64
- Art. 72 da Lei n. 4.502/64
- Art. 73 da Lei n. 4.502/64

### Dicas de prova
- Entenda a distinção entre fraude, sonegação e conluio para fins tributários.
- Leia atentamente os arts. 71, 72 e 73 da Lei n. 4.502/64.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.186 (1)", "page_number": 186, "discipline": "Direito Tributário", "legal_refs": ["Art. 71 da Lei n. 4.502/64", "Art. 72 da Lei n. 4.502/64", "Art. 73 da Lei n. 4.502/64"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:00:36.477729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=186", "doc_key": "ef1b3707df0464e321c097a246a3fd8f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7af22ae6bfbd191cfa0377f1bac146366f2afd38ec66dac3f074e0af17caecfe'),
  ('cpiuris2025::8e8946cacc87dc1ee2bc08449899352f', 'doutrina', 'cp_iuris', 'Direito Tributário — Multas por falta de apresentação ou apresentação após prazo', '## Multas por falta de apresentação ou apresentação após prazo

O responsável por uma operação deve pagar multa de 0,1% ao mês-calendário sobre o valor da operação, limitada a um por cento, se não apresentar declaração dentro do prazo fixado.

### Conceitos
- **Multa Tributária**: Pena imposta pela lei por não cumprimento de obrigação tributária
- **Retenção e Recolhimento**: Obrigação de um contribuinte para reter imposto ou contribuição em sua fonte pagadora

### Referências legais
- Art. 9º do Código Tributário Nacional
- Inciso I do caput do art. 44 da Lei nº 9.430/96

### Dicas de prova
- Entenda a diferença entre retenção e recolhimento de imposto
- Conheça as penalidades administrativas e criminais relacionadas à falta de apresentação ou apresentação após prazo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.186 (2)", "page_number": 186, "discipline": "Direito Tributário", "legal_refs": ["Art. 9º do Código Tributário Nacional", "Inciso I do caput do art. 44 da Lei nº 9.430/96"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:00:51.755871+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=186", "doc_key": "8e8946cacc87dc1ee2bc08449899352f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '4c567b6dd11f15ca24200e3e6c79e098beaf5c8ec9da524182a0284ba3e94123'),
  ('cpiuris2025::371c5b9cfd6876238a8abc10b8a21446', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária no Espólio', '## Responsabilidade Tributária no Espólio

A responsabilidade tributária é pessoal do espólio pelos tributos devidos pelo de cujus, desde a data da abertura da sucessão até a data da partilha ou adjudicação. Além disso, também é pessoal a responsabilidade do cônjuge meeiro e sucessores nos limites da meação, do quinhão ou legado.

### Conceitos
- **Responsabilidade Tributária**: Pertence ao espólio
- **Espólio**: Bens de um falecido
- **Cônjuge Meeiro**: Sobrevivente que recebe a meação do cônjuge falecido
- **Sucessores**: Pessoas que herdam os bens do falecido

### Referências legais
- Art. 113 da Lei de Sucessões
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre responsabilidade tributária pessoal e imposta
- Importância do momento da transmissão de bens imóveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.188 (2)", "page_number": 188, "discipline": "Direito Tributário", "legal_refs": ["Art. 113 da Lei de Sucessões", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T17:03:01.513488+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=188", "doc_key": "371c5b9cfd6876238a8abc10b8a21446"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ffaa96f91fcf4ac2bfcb487efe923ed229b14e729a0438399e66c03ed1db1358'),
  ('cpiuris2025::7162023720e1e38c4b74575e04d44226', 'doutrina', 'cp_iuris', 'Direito Tributário — Sucessão Tributária', '## Sucessão Tributária

A legislação tributária estabelece regras para a sucessão de responsabilidades tributárias, permitindo que a lei atribua a responsabilidade pelo pagamento de impostos ou contribuições a uma terceira pessoa vinculada ao fato gerador, excluindo a responsabilidade do contribuinte.

### Conceitos
- **Sucessão Tributária**: A atribuição da responsabilidade pelo pagamento de impostos ou contribuições a uma terceira pessoa vinculada ao fato gerador.
- **Responsabilidade Tributária**: O dever de pagar impostos ou contribuições por parte do sujeito passivo da obrigação tributária.
- **Fato Gerador**: O evento que gera a obrigação tributária.
- **Contribuinte**: O sujeito passivo da obrigação tributária.

### Referências legais
- Art. 109, § 4º do Código Tributário Nacional

### Dicas de prova
- Entenda a distinção entre responsabilidade tributária e sucessão tributária.
- Conheça as regras para a atribuição da responsabilidade pelo pagamento de impostos ou contribuições a uma terceira pessoa vinculada ao fato gerador.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.188 (1)", "page_number": 188, "discipline": "Direito Tributário", "legal_refs": ["Art. 109, § 4º do Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:03:35.289119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=188", "doc_key": "7162023720e1e38c4b74575e04d44226"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'aa50f39d371b9ad81c989fe454e469a318356a154a8804c9e340481ef68c4218'),
  ('cpiuris2025::c7d4aff270a06a9dcbadb72cd14d736f', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária', '## Responsabilidade Tributária

O texto aborda hipóteses de responsabilidade tributária, incluindo transferência progressiva e substituição regressiva.

### Conceitos
- **Transferência Progressiva**: Ocorre quando o pagamento do tributo é transferido para um momento posterior.
- **Substituição Regressiva**: Ocorre quando a responsabilidade tributária é transferida de uma pessoa para outra.
- **Responsabilidade Solidária**: A responsabilidade tributária recai sobre todos os sócios da sociedade, independentemente de terem sido ou não envolvidos no fato gerador.
- **Sucessão Empresarial**: Ocorre quando uma empresa é substituída por outra pessoa ou sociedade.
- **Responsabilidade Tributária da Sucessora**: A responsabilidade tributária recai sobre a sucessora, incluindo os tributos devidos pela sucedida e as multas moratórias ou punitivas.
- **Multas Moratórias**: São multas aplicadas ao devedor por não cumprir com o prazo para pagamento do tributo.
- **Punições Tributárias**: São sanções aplicadas ao devedor por infrações tributárias.

### Referências legais
- Art. 102 da Lei nº 9.532/1997

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte se a responsabilidade tributária é transferida para uma pessoa ou outra.
- Verifique se a responsabilidade tributária recai sobre todos os sócios da sociedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.187", "page_number": 187, "discipline": "Direito Tributário", "legal_refs": ["Art. 102 da Lei nº 9.532/1997"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T17:03:58.858018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=187", "doc_key": "c7d4aff270a06a9dcbadb72cd14d736f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0e929e79e58c481303fb3c198e003e157dbbc454a5ad82a84f20323a65c30de1'),
  ('cpiuris2025::f0b04333f2031f16d5906c9c99db2a0f', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária', '## Responsabilidade Tributária

A responsabilidade tributária pode ser absoluta em casos específicos, como a aquisição de imóvel em hasta pública para o adquirente, ou solidária com o contribuinte nas hipóteses de fusão, cisão e incorporação de empresa.

### Conceitos
- **Responsabilidade Tributária**: O direito do Estado de exigir a cobrança de tributos devido por uma pessoa jurídica ou física.
- **Absoluta Responsabilidade Tributária**: A responsabilidade tributária é absoluta em casos específicos, como a aquisição de imóvel em hasta pública para o adquirente.
- **Solidária Responsabilidade Tributária**: A responsabilidade tributária pode ser solidária com o contribuinte nas hipóteses de fusão, cisão e incorporação de empresa.

### Referências legais
- Art. 128 do CTN
- Súmula 634 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo Responsabilidade Tributária

### Dicas de prova
- Perguntas sobre responsabilidade tributária podem ser resolvidas com base na jurisprudência do STJ e no CTN.
- É importante entender a distinção entre absoluta e solidária responsabilidade tributária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.189 (1)", "page_number": 189, "discipline": "Direito Tributário", "legal_refs": ["Art. 128 do CTN", "Súmula 634 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo Responsabilidade Tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T17:05:31.947548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=189", "doc_key": "f0b04333f2031f16d5906c9c99db2a0f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8db3d8fb90e917acc3f8cc6f86eeebc1a20eec54c66006e4182ba5dcd8d5e8c7'),
  ('cpiuris2025::9d8b1b3585ba457aea7978454be01cca', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária', '## Responsabilidade Tributária

A lei pode atribuir a responsabilidade pelo crédito tributário a uma terceira pessoa vinculada ao fato gerador, excluindo a responsabilidade do contribuinte.

### Conceitos
- **Responsabilidade Tributária**: O dever de pagar impostos por parte de uma pessoa ou entidade
- **Vinculação ao Fato Gerador**: A relação entre a responsável tributária e o fato gerador da obrigação
- **Contribuinte**: Pessoa ou entidade que deve pagar impostos
- **Responsável Tributário**: Pessoa ou entidade que assume a responsabilidade pelo pagamento de impostos

### Referências legais
- Art. 102 da Lei nº 10.865/2004

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a diferença entre contribuinte e responsável tributário
- Conheça o conceito de vinculação ao fato gerador
- Aprenda a aplicar a responsabilidade tributária em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.189 (2)", "page_number": 189, "discipline": "Direito Tributário", "legal_refs": ["Art. 102 da Lei nº 10.865/2004"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T17:05:52.116215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=189", "doc_key": "9d8b1b3585ba457aea7978454be01cca"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '73a0f0f066571a58a4c0a9d80cc6a3780302cb98aea1f72ce917ebca09d46063'),
  ('cpiuris2025::9110db19bde593f2defc429cc02d9111', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária - Substituição Tributária', '## Responsabilidade Tributária - Substituição Tributária

A substituição tributária ocorre quando o contribuinte está atrás da cadeia de produção, enquanto a substituição progressiva ocorre à frente da cadeia. O CTN estabelece regras para a responsabilidade tributária em casos de alienação de fundos de comércio ou estabelecimentos comerciais.

### Conceitos
- **Substituição Tributária**: Ocorre quando o contribuinte está atrás da cadeia de produção
- **Substituição Progressiva**: Ocorre à frente da cadeia de produção, perto do consumidor
- **Alienação de Fundos de Comércio**: Transito de um contribuinte para outro na mesma atividade econômica
- **Responsabilidade Tributária**: Obrigação do contribuinte de pagar tributos

### Referências legais
- Art. 133, CTN

### Dicas de prova
- Entenda a diferença entre substituição tributária e progressiva
- Conheça as regras do CTN para alienação de fundos de comércio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direito Tributário", "legal_refs": ["Art. 133, CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:06:17.046364+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=190", "doc_key": "9110db19bde593f2defc429cc02d9111"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ae7bd9fb24a09886929920fb9f6ba67cee9d647404b4c85f7d045b8db5c39a9f'),
  ('cpiuris2025::c3837ff06f83c7932b334a9cb7956418', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Solidária do Sócio-Gerente', '## Responsabilidade Solidária do Sócio-Gerente

A responsabilidade solidária do sócio-gerente é questionada, com referência a súmulas do STJ e artigos da CTN.

### Conceitos
- **Responsabilidade Solidária**: Obrigação de um sócio-gerente em relação às obrigações tributárias da empresa
- **Sócio-Gerente**: Pessoa que exerce a função de gerente e administrador da empresa
- **Execução Fiscal**: Procedimento utilizado pela Fazenda Pública para cobrar dívidas tributárias
- **Dissolução Irregular**: Fim da empresa sem cumprimento das formalidades legais

### Referências legais
- Art. 129 CTN
- Súmula n.º 430 STJ
- Súmula n.º 435 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a responsabilidade solidária do sócio-gerente e as implicações para a execução fiscal
- Conheça as súmulas do STJ e os artigos da CTN relevantes para o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direito Tributário", "legal_refs": ["Art. 129 CTN", "Súmula n.º 430 STJ", "Súmula n.º 435 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T17:07:44.340194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=190", "doc_key": "c3837ff06f83c7932b334a9cb7956418"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7e83d2ca549427e94a34a91587fa605e5e5a763f6d1be6b5259a3e219f1ea98e'),
  ('cpiuris2025::3cbc5595f895fb522f79219ae4a14b1f', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária', '## Responsabilidade Tributária

A responsabilidade tributária é pessoal e se estende a sucessores, cônjuge meeiro e espólio do de cujus até a data da partilha ou adjudicação/spoio.

### Conceitos
- **Responsabilidade Tributária**: Pessoal responsável pelos tributos devidos pelo de cujus
- **Sucessor**: Pessoa que sucede a outro na qualidade de proprietário ou detentor de bens
- **Cônjuge Meeiro**: Cônjuge que recebe parte do patrimônio do casado falecido
- **Espólio**: Bem que lhe é legado ou herdado após a morte de um dos cônjuges

### Referências legais
- Art. 131, CTN

### Jurisprudência
- Súmula n.º 436 do STJ

### Dicas de prova
- Entenda a noção de responsabilidade tributária pessoal e seus limites.
- Conheça as figuras jurídicas de sucessor, cônjuge meeiro e espólio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.191", "page_number": 191, "discipline": "Direito Tributário", "legal_refs": ["Art. 131, CTN"], "jurisprudence": ["Súmula n.º 436 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T17:08:01.359606+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=191", "doc_key": "3cbc5595f895fb522f79219ae4a14b1f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7fed4d199f8801ca98f05c6b2d7a196c54cea669153272dc2eb7127ac0fddc27'),
  ('cpiuris2025::608e23540b03aac268bd67c2fbf5bc8b', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento Tributário', '## Lançamento Tributário

A obrigação tributária surge com a ocorrência do fato gerador, caracterizando-se como o liame jurídico que vincula um sujeito passivo à realização de uma prestação jurídica ao sujeito ativo. O lançamento tributário é o procedimento administrativo que declara a obrigação tributária e constitui o crédito tributário.

### Conceitos
- **Obrigação Tributária**: Liame jurídico que vincula um sujeito passivo à realização de uma prestação jurídica ao sujeito ativo
- **Fato Gerador**: Ocorrencia do fato que gera a obrigação tributária
- **Hipótese de Incidência**: Mundo da norma que encontra o mundo da vida (fato gerador)
- **Lançamento Tributário**: Procedimento administrativo que declara a obrigação tributária e constitui o crédito tributário
- **Crédito Tributário**: Constituído a partir do lançamento tributário, é o valor do tributo devido

### Referências legais
- Art. 142 do Código Tributário Nacional

### Dicas de prova
- Entenda a diferença entre obrigação e crédito tributários
- Conheça as espécies de lançamento tributário (direto, por declaração, por homologação)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.192", "page_number": 192, "discipline": "Direito Tributário", "legal_refs": ["Art. 142 do Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:09:08.019776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=192", "doc_key": "608e23540b03aac268bd67c2fbf5bc8b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '5d3f60de2f2ee28bf66727dd7d0a4f11396d6b2c2ff48917aef8d7f59472f949'),
  ('cpiuris2025::88a2e708e063abe16654c06d0349e706', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento e Lei Vigente', '## Lançamento e Lei Vigente

A lei vigente no momento do fato gerador é a que valerá para o lançamento, mesmo se posteriormente modificada ou revogada. A lei do § 1º não é a mesma da lei do caput do art. 144.

### Conceitos
- **Fato Gerador**: O evento que gera a obrigação tributária
- **Lei Vigente**: A lei que regula o fato gerador no momento em que ocorre
- **Lançamento Tributário**: O ato de registrar a obrigação tributária
- **Lei do § 1º**: A lei que regula o cumprimento de obrigações acessórias

### Referências legais
- Art. 144, caput e § 1º, Código Tributário Nacional

### Dicas de prova
- Entenda a diferença entre fato gerador e lei vigente
- Conheça o conceito de lançamento tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.193 (2)", "page_number": 193, "discipline": "Direito Tributário", "legal_refs": ["Art. 144, caput e § 1º, Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:10:05.019242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=193", "doc_key": "88a2e708e063abe16654c06d0349e706"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '1a8163f5031f60f8cc66a92cca8d32007fdfc92eed4db8da88918c406ecf12a2'),
  ('cpiuris2025::1b70b656c94dce597fb52aa7ebf6c6df', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento Tributário', '## Lançamento Tributário

O lançamento tributário é um ato administrativo que declara a obrigação tributária e constitui o crédito tributário, sendo vinculado à lei vigente na data do fato gerador.

### Conceitos
- **Lançamento Tributário**: Ato administrativo que declara a obrigação tributária e constitui o crédito tributário
- **Procedimento Administrativo**: Atividade administrativa que visa realizar um procedimento fiscal
- **Obrigação Acessória**: Obrigação decorrente de uma obrigação principal, como o imposto sobre a renda
- **Lei Vigente**: Lei que regula a obrigação tributária na data do fato gerador

### Referências legais
- Art. 142 do CTN
- Art. 144 do CTN
- Súmula 646/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Lançamento Tributário

### Dicas de prova
- Entenda a natureza jurídica do lançamento tributário e sua vinculação à lei vigente
- Conheça as regras de procedimento fiscal e suas implicações no lançamento tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.193 (1)", "page_number": 193, "discipline": "Direito Tributário", "legal_refs": ["Art. 142 do CTN", "Art. 144 do CTN", "Súmula 646/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Lançamento Tributário"], "confidence": 0.8, "extracted_at": "2026-05-29T17:10:18.909213+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=193", "doc_key": "1b70b656c94dce597fb52aa7ebf6c6df"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3a33aec7b9c17824dbeb560924f087ba413e12fce6bafc8365e0dd1debaa9d45'),
  ('cpiuris2025::350cfea624069fdf604f2b4ea3f6a61a', 'doutrina', 'cp_iuris', 'Direito Tributário — Critérios Jurídicos para Lançamento do Tributo', '## Critérios Jurídicos para Lançamento do Tributo

A Fazenda Pública utiliza critérios específicos para lançar o tributo, incluindo a comprovação de ações ou omissões do sujeito passivo, agir com dolo, fraude ou simulação, fato não conhecido ou não provado e fraude ou falta funcional da autoridade.

### Conceitos
- **Ação ou Omissão**: Comprovação de ações ou omissões do sujeito passivo
- **Dolo, Fraude ou Simulação**: Agir com dolo, fraude ou simulação
- **Fato Não Conhecido ou Não Provado**: Fato que não foi conhecido ou provado na ocasião do lançamento anterior
- **Fraude ou Falta Funcional**: Ocorrencia de fraude ou falta funcional da autoridade que efetuou o lançamento

### Referências legais
- Art. 146, § 1º, I a IX, do CTbN

### Dicas de prova
- Perguntas sobre os critérios utilizados pela Fazenda Pública para lançar o tributo
- Distinção entre ações e omissões do sujeito passivo
- Importância de comprovar dolo, fraude ou simulação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.194 (2)", "page_number": 194, "discipline": "Direito Tributário", "legal_refs": ["Art. 146, § 1º, I a IX, do CTbN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:12:24.303168+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=194", "doc_key": "350cfea624069fdf604f2b4ea3f6a61a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '93a2a2bcb990e00b7eef6a67aeb1ec552c048ee1b57153b478b5d9c42a4b4b23'),
  ('cpiuris2025::496f91773e2d9fddace2478d46957b60', 'doutrina', 'cp_iuris', 'Direito Tributário — Modificação do lançamento tributário', '## Modificação do lançamento tributário

A modificação do lançamento tributário pode ser feita apenas com base em fato gerador ocorrido posteriormente à sua introdução, salvo se o fato gerador tiver ocorrido antes da alteração. O princípio da confiança é primado.

### Conceitos
- **Princípio da Confiança**: Princípio que impede a revisão do lançamento tributário por erro de direito, mas permite a revisão em caso de erro de fato.
- **Fato Gerador**: O evento ou situação que gera o direito ao imposto
- **Lançamento Tributário**: A declaração da autoridade administrativa sobre a obrigação tributária do contribuinte

### Referências legais
- Art. 146 do CTN

### Jurisprudência
- Súmula 637/STJ

### Dicas de prova
- Entenda o princípio da confiança e sua aplicação nas hipóteses de erro de direito e fato.
- Diferencie entre lançamento tributário por declaração e lançamento por homologação ou autolançamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.195 (1)", "page_number": 195, "discipline": "Direito Tributário", "legal_refs": ["Art. 146 do CTN"], "jurisprudence": ["Súmula 637/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T17:12:30.011962+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=195", "doc_key": "496f91773e2d9fddace2478d46957b60"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'df05391b94a4a678311bc458f46d289e4a1c09acbd1959cc9a4e9599847e346c'),
  ('cpiuris2025::45b66c07816b1d6d80c46f2b91d48d49', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento Tributário e Revisão', '## Lançamento Tributário e Revisão

A lei que valerá para o procedimento administrativo de lançamento é a que estiver vigente no momento do lançamento, mas a lei à época do fato gerador define a obrigação tributária. O lançamento pode ser alterado apenas com base em impugnação do sujeito passivo, recurso de ofício ou iniciativa da autoridade administrativa.

### Conceitos
- **Máxima do tempus regit actum**: A lei que valerá para o procedimento administrativo de lançamento é a que estiver vigente no momento do lançamento.
- **Lei à época do fato gerador**: Define a obrigação tributária, incluindo sujeito passivo, base de cálculo, alíquota e fato gerador da obrigação tributária.
- **Princípio da autotutela administrativa**: Permite à Fazenda Pública rever o ato de lançamento a todo tempo, desde que não notificado o sujeito passivo.
- **Impugnação do sujeito passivo**: Pode ser um meio para alterar o lançamento, mas requer a participação do sujeito passivo.
- **Recurso de ofício**: É um meio para alterar o lançamento, sem necessidade da impugnação do sujeito passivo.
- **Iniciativa da autoridade administrativa**: Pode ser um meio para alterar o lançamento, especialmente em casos previstos no artigo 149 do CTN.

### Referências legais
- Art. 144, § 1º do CTN
- Art. 145 do CTN
- Art. 149 do CTN

### Dicas de prova
- Entenda a diferença entre impugnação e recurso de ofício.
- Conheça as exceções ao artigo 145 do CTN.
- Aprenda a aplicar o princípio da autotutela administrativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.194 (1)", "page_number": 194, "discipline": "Direito Tributário", "legal_refs": ["Art. 144, § 1º do CTN", "Art. 145 do CTN", "Art. 149 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:12:57.776818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=194", "doc_key": "45b66c07816b1d6d80c46f2b91d48d49"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f2ac9636916fd63367899c5ec523f28a86e7401ab65f001e44ff54490fb27af3'),
  ('cpiuris2025::994dfc5f93654921beb2788bb4f8c3ba', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento e Procedimento Tributário', '## Lançamento e Procedimento Tributário

O contribuinte não pode impugnar o procedimento de lançamento por homologação, pois é parte integral da subsunção dos fatos à tributação. O Fisco pode constituir o crédito tributário mediante lançamento, com prazo de 5 anos, e a prescrição relaciona-se com a exigibilidade do crédito.

### Conceitos
- **Lançamento**: procedimento pelo qual o Fisco constitui provisoriamente o crédito tributário
- **Decadência Tributária**: direito do Fisco de constituir o crédito tributário após 5 anos
- **Prescrição Tributária**: exigibilidade do crédito após a falta de pagamento espontâneo

### Referências legais
- Art. 150 do CTN

### Dicas de prova
- Distinção entre lançamento direto e ofício
- Importância da prescrição e decadência tributárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.195 (2)", "page_number": 195, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:13:51.698592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=195", "doc_key": "994dfc5f93654921beb2788bb4f8c3ba"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '5443a95a40a28488c5371bc8489fb2c5a6df967d6115985e6cb40b98b19cf73d'),
  ('cpiuris2025::d06addbcce6412d0a9a51984e62a8efd', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento Tributário', '## Lançamento Tributário

O lançamento tributário é um procedimento administrativo que visa a constituição do crédito tributário. Existem três tipos de lançamentos: lançamento por ofício, lançamento por declaração e lançamento por homologação.

### Conceitos
- **Lançamento Tributário**: Procedimento administrativo que visa a constituição do crédito tributário
- **Contribuinte**: Sujeito passivo do imposto, responsável por pagar o tributo
- **Fase Contenciosa**: Instância em que o contribuinte pode opor suas razões de inconformidade com o lançamento provisório
- **Lançamento Provisório**: Constituição temporária do crédito tributário, que pode ser aferida pela administração tributária
- **Fase Contenciosa Definitiva**: Instância em que o contribuinte pode impugnar o lançamento definitivo, caso ele não tenha concordado com o lançamento provisório

### Referências legais
- Art. 150, § 4º, do CTN

### Dicas de prova
- Entenda a diferença entre lançamento por ofício e lançamento por declaração
- Conheça as regras de procedimento para o lançamento tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.196 (1)", "page_number": 196, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, § 4º, do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:14:05.304702+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=196", "doc_key": "d06addbcce6412d0a9a51984e62a8efd"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '951f937586f1a23d0ba4c551f064acbec6228196d318f0cc9312aa05e6914fe3'),
  ('cpiuris2025::9b5834886ccc45195d216ca2f2f122d2', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento de Créditos Tributários', '## Lançamento de Créditos Tributários

O procedimento de declaração/confissão do contribuinte é suficiente para constituir o crédito tributário, não havendo decadência do direito de lançar o tributo.

### Conceitos
- **Declaração**: procedimento pelo qual o contribuinte confessa ou declara a existência de crédito tributário
- **Lançamento por Declaração**: mecanismo de lançamento do sujeito passivo, anteriormente tratado
- **DCTF - Declaração de Créditos Tributários Federais**: declaração específica para créditos tributários federais

### Referências legais
- Art. 149, do CTN

### Jurisprudência
- Súmula n.º 436, STJ

### Dicas de prova
- Entenda a diferença entre declaração e lançamento por declaração.
- Conheça as 3 modalidades de lançamentos previstas no CTN.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.196 (2)", "page_number": 196, "discipline": "Direito Tributário", "legal_refs": ["Art. 149, do CTN"], "jurisprudence": ["Súmula n.º 436, STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T17:16:03.144959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=196", "doc_key": "9b5834886ccc45195d216ca2f2f122d2"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '545f9583c24a9b3814b41803078a29ea254d60fd57aba058d8893c35800148bb'),
  ('cpiuris2025::f386c38022e4b9561ac153b6b572a680', 'doutrina', 'cp_iuris', 'Direito Tributário — Prazo para homologação de lançamento', '## Prazo para homologação de lançamento

O prazo para homologação do lançamento é de cinco anos, contando da ocorrência do fato gerador. Se expirado sem pronunciamento da Fazenda Pública, o crédito é definitivamente extinto.

### Conceitos
- **Fato gerador**: O evento que gera a obrigação de pagar imposto
- **Homologação**: A ação de confirmar ou aprovar o lançamento do tributo
- **Prazo para homologação**: O período durante o qual a Fazenda Pública pode pronunciar-se sobre o lançamento do tributo

### Referências legais
- Art. 29 da Lei nº 9.532/1997

### Jurisprudência
- Súmula 743 do STF

### Dicas de prova
- Entenda a diferença entre homologação e lançamento
- Conheça o prazo para homologação e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.197 (2)", "page_number": 197, "discipline": "Direito Tributário", "legal_refs": ["Art. 29 da Lei nº 9.532/1997"], "jurisprudence": ["Súmula 743 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T17:16:15.408791+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=197", "doc_key": "f386c38022e4b9561ac153b6b572a680"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '92f5d1195e2342911729f91efce6a855b013ef60e6c00e8a79f9e1083d6c2558'),
  ('cpiuris2025::7e689613114829931aab5b236b3837af', 'doutrina', 'cp_iuris', 'Direito Tributário — Lançamento Tributário', '## Lançamento Tributário

O lançamento tributário ocorre quando a autoridade administrativa confere validade ao pagamento antecipado do contribuinte, ou quando o contribuinte declara as informações necessárias para o lançamento.

### Conceitos
- **Lançamento Tributário**: O ato pelo qual a autoridade administrativa confere validade ao pagamento antecipado do contribuinte ou declara as informações necessárias para o lançamento.
- **Declaração Tributária**: A informação prestada pelo contribuinte à autoridade administrativa sobre matéria de fato indispensável à efetivação do lançamento.
- **Homologação**: O ato pela qual a autoridade administrativa confere validade ao lançamento tributário, após verificar as informações prestadas pelo contribuinte.

### Referências legais
- Art. 147 do CTN
- Art. 150 do CTN

### Dicas de prova
- Diferenciar entre lançamento por declaração e lançamento por homologação.
- Entender a importância da declaração tributária para o lançamento.
- Conhecer as condições para a homologação do lançamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.197 (1)", "page_number": 197, "discipline": "Direito Tributário", "legal_refs": ["Art. 147 do CTN", "Art. 150 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T17:16:45.923918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=197", "doc_key": "7e689613114829931aab5b236b3837af"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '5a1805fb5d63fdb1dd95ff67d803b77e24ad4c09f5aa5f1825ace9e5ea0772e1'),
  ('cpiuris2025::d8ad287ef3b23bb7e587dd275b4c767c', 'doutrina', 'cp_iuris', 'Direito Tributário — Crédito Tributário', '## Crédito Tributário

O crédito tributário é constituído a partir do momento em que ocorre o fato gerador do tributo, e pode ser lançado eventualmente, homologado ou decorrer de tempo. O prazo de homologação é de 5 anos, contados a partir da ocorrência do fato gerador.

### Conceitos
- **Crédito Tributário**: direito do contribuinte ao pagamento de tributos
- **Fato Gerador**: ocorrência que gera o direito ou a obrigação de pagar um tributo
- **Lançamento Tributário**: ato pelo qual a Administração lança o tributo
- **Homologação**: atendimento da Fazenda Pública ao lançamento do tributo

### Referências legais
- Art. 150, § 4º, do CTN

### Jurisprudência
- Súmula n.º 436 do STJ
- Súmula 360 do STJ

