  ('cpiuris2025::db98e492a6376744f31513eed19c0a9f', 'doutrina', 'cp_iuris', 'Direito Tributário — Fato Gerador e Imposto', '## Fato Gerador e Imposto

O fato gerador do imposto deve ser uma situação independente de atividade estatal específica, previsto na Constituição ou instituído com base na competência residual da União. O imposto pode ter o mesmo fato gerador que outros impostos, desde que a destinação seja diferente.

### Conceitos
- **Fato Gerador**: Situação independente de atividade estatal específica
- **Imposto**: Tributo cuja obrigação tem por fato gerador uma situação independente de qualquer atividade estatal específica, relativa ao contribuinte
- **Competência Residual**: Poder da União para instituir tributos sem necessidade de prévia autorização legislativa

### Referências legais
- Art. 110 do Código Tributário Nacional
- Súmula 439 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Fato Gerador e Imposto

### Dicas de prova
- Entenda a distinção entre fato gerador de obrigação principal e obrigação acessória
- Conheça as limitações constitucionais para a instituição de tributos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.199 (1)", "page_number": 199, "discipline": "Direito Tributário", "legal_refs": ["Art. 110 do Código Tributário Nacional", "Súmula 439 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Fato Gerador e Imposto"], "confidence": 0.8, "extracted_at": "2026-05-29T17:18:34.283711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=199", "doc_key": "db98e492a6376744f31513eed19c0a9f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '463099edcede50fc3f148a9c9e5066a1ffafc0329dccee155b625d0dc63615e1'),
  ('cpiuris2025::9d2cc98f406a08f4c7d164f504a5e9ad', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária e Infrações', '## Responsabilidade Tributária e Infrações

Resumo do texto: Discute-se a responsabilidade tributária e as hipóteses em que a sociedade em comum é considerada sujeita passiva da obrigação tributária principal. Além disso, aborda-se a elisão da responsabilidade por infrações mediante denúncia espontânea do contribuinte.

### Conceitos
- **Responsabilidade Tributária**: Obrigação de pagar impostos ou taxas
- **Sociedade em Comum**: Pessoa jurídica que tem capacidade tributária passiva
- **Capacidade Tributária Passiva**: Condição que permite a sociedade em comum ser considerada sujeita passiva da obrigação tributária principal
- **Responsabilidade Pessoal**: Obrigação de pagar impostos ou taxas por parte dos sócios
- **Denúncia Espontânea**: Ação do contribuinte que denuncia a infração e paga o crédito tributário devido

### Referências legais
- Art. 102 da Lei 9.532/1997

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunta sobre responsabilidade tributária e capacidade tributária passiva
- Distinção entre responsabilidade pessoal e responsabilidade pela sociedade em comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.199 (2)", "page_number": 199, "discipline": "Direito Tributário", "legal_refs": ["Art. 102 da Lei 9.532/1997"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T17:19:12.120942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=199", "doc_key": "9d2cc98f406a08f4c7d164f504a5e9ad"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e44cb4cedc625c4d18ab277706ebfce5873838094735a94b2ed9af3d50e52653'),
  ('cpiuris2025::d8725c2df9f7a9701c9635b20066bb00', 'doutrina', 'cp_iuris', 'Direito Tributário — Capacidade Tributária Ativa e Competência Tributária', '## Capacidade Tributária Ativa e Competência Tributária

A capacidade tributária ativa não se confunde com a competência tributária, pois a capacidade pode ser delegada a qualquer pessoa jurídica. A competência, por outro lado, é verificada pela autoridade tributária competente.

### Conceitos
- **Capacidade Tributária Ativa**: A capacidade de um contribuinte para gerar o crédito tributário
- **Competência Tributária**: A verificação da competência da autoridade tributária competente
- **Delegação de Capacidade Tributária Ativa**: O ato de delegar a capacidade tributária ativa a outra pessoa jurídica

### Referências legais
- Art. 129, § 3º, da CF/88

### Jurisprudência
- RE 123456/ES

### Dicas de prova
- Entenda a distinção entre capacidade tributária ativa e competência tributária
- Conheça o conceito de delegação de capacidade tributária ativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.200 (1)", "page_number": 200, "discipline": "Direito Tributário", "legal_refs": ["Art. 129, § 3º, da CF/88"], "jurisprudence": ["RE 123456/ES"], "confidence": 0.8, "extracted_at": "2026-05-29T17:20:39.672537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=200", "doc_key": "d8725c2df9f7a9701c9635b20066bb00"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8667b5653fd300953f940f92ea91e580b3b715ecd3922aa507503146fd3c011b')
